import React, { useState } from 'react';
import { createPortal } from 'react-dom';
import { X, GraduationCap, BookOpen, ChevronRight, Calendar, ArrowLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { PROGRAMS } from '../../config/academics';
import './CourseSelectionModal.css';

const CourseSelectionModal = ({ isOpen, onClose }) => {
    const navigate = useNavigate();
    const [selectedYear, setSelectedYear] = useState(null);
    const [selectedBranch, setSelectedBranch] = useState(null);
    const [selectedProgram, setSelectedProgram] = useState(null);

    if (!isOpen) return null;

    const handleYearSelect = (program, year) => {
        setSelectedProgram(program);
        setSelectedYear(year);
    };

    const handleSemesterSelect = (semId) => {
        navigate(`/courses/${selectedYear.id}/${semId}${selectedBranch ? `?branch=${selectedBranch.id}` : ''}`);
        onClose();
        // Reset state after a small delay so closing animation doesn't show the first screen
        setTimeout(() => {
            setSelectedYear(null);
            setSelectedBranch(null);
            setSelectedProgram(null);
        }, 300);
    };

    const handleBranchSelect = (branch) => {
        setSelectedBranch(branch);
    };

    const handleBack = () => {
        if (selectedBranch) {
            setSelectedBranch(null);
        } else {
            setSelectedYear(null);
            setSelectedProgram(null);
        }
    };

    const handleClose = () => {
        onClose();
        setTimeout(() => {
            setSelectedYear(null);
            setSelectedBranch(null);
            setSelectedProgram(null);
        }, 300);
    };

    return createPortal(
        <div className="course-modal-overlay animate-fade-in" onClick={handleClose}>
            <div className="course-modal-content animate-slide-up" onClick={e => e.stopPropagation()}>
                <div className="course-modal-grabber"></div>

                <div className="course-modal-header">
                    {selectedYear ? (
                        <button className="back-btn-circle" onClick={handleBack}>
                            <ArrowLeft size={20} />
                        </button>
                    ) : (
                        <div className="header-icon">
                            <BookOpen size={24} />
                        </div>
                    )}
                    <div className="header-text">
                        <h2>{selectedBranch ? selectedBranch.label : (selectedYear ? selectedYear.label : 'Academic Programs')}</h2>
                        <p>{selectedYear ? (selectedYear.branches && !selectedBranch ? 'Select your branch' : 'Select your semester') : 'Select your year to view courses'}</p>
                    </div>
                    <button className="close-btn-circle" onClick={handleClose}>
                        <X size={20} />
                    </button>
                </div>

                <div className="course-modal-body">
                    {selectedYear ? (
                        selectedYear.branches && !selectedBranch ? (
                            <div className="semesters-list animate-fade-in">
                                {selectedYear.branches.map(branch => (
                                    <button 
                                        key={branch.id} 
                                        className="semester-item-row"
                                        onClick={() => handleBranchSelect(branch)}
                                    >
                                        <div className="sem-icon-box">
                                            <BookOpen size={18} />
                                        </div>
                                        <span className="sem-label">{branch.label}</span>
                                        <ChevronRight size={18} className="sem-arrow" />
                                    </button>
                                ))}
                            </div>
                        ) : (
                            <div className="semesters-list animate-fade-in">
                                {(selectedBranch ? selectedBranch.semesters : selectedYear.semesters).map(sem => (
                                    <button 
                                        key={sem.id} 
                                        className="semester-item-row"
                                        onClick={() => handleSemesterSelect(sem.id)}
                                    >
                                        <div className="sem-icon-box">
                                            <Calendar size={18} />
                                        </div>
                                        <span className="sem-label">{sem.label}</span>
                                        <ChevronRight size={18} className="sem-arrow" />
                                    </button>
                                ))}
                            </div>
                        )
                    ) : (
                        PROGRAMS.map(program => (
                            <div key={program.id} className="program-section">
                                <div className="section-label">
                                    <span>{program.id === 'puc' ? 'Pre-University' : 'Engineering'}</span>
                                    <div className="section-line"></div>
                                </div>
                                <div className="years-list">
                                    {program.years.map(year => (
                                        <button 
                                            key={year.id} 
                                            className={`year-item-card theme-${program.color}`}
                                            onClick={() => handleYearSelect(program, year)}
                                        >
                                            <div className="year-icon-box">
                                                <program.icon size={20} />
                                            </div>
                                            <div className="year-details">
                                                <span className="y-label">{year.label}</span>
                                                <span className="y-sub">{year.subLabel}</span>
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>,
        document.body
    );
};

export default CourseSelectionModal;

import React, { useState, useRef } from 'react';
import { auth } from '../../config/firebase';
import * as imageService from '../../services/imageService';
import { Upload, X, Check, Loader, ImageIcon } from 'lucide-react';
import './ImageUpload.css';

const ImageUpload = ({
    onUploadComplete,
    userId: propUserId, // Allow passing userId as prop, or use current auth user
    path = 'uploads/profile_images/',
    maxSizeMB = 2,
    allowedTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/jpg']
}) => {
    const [file, setFile] = useState(null);
    const [previewUrl, setPreviewUrl] = useState(null);
    const [uploading, setUploading] = useState(false);
    const [progress, setProgress] = useState(0);
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(false);
    const fileInputRef = useRef(null);

    const effectiveUserId = propUserId || auth.currentUser?.uid;

    const handleFileSelect = (e) => {
        const selectedFile = e.target.files[0];
        if (!selectedFile) return;

        // Reset states
        setError(null);
        setSuccess(false);
        setProgress(0);

        // Type Validation
        if (!allowedTypes.includes(selectedFile.type)) {
            setError('Invalid file type. Please upload JPG, PNG, or WebP.');
            return;
        }

        // Initial Size Check (pre-optimization)
        // We'll optimize later, but if it's monstrously large, we might warn.
        // But let's stick to the 2MB limit for the FINAL saved file.

        setFile(selectedFile);

        // Create preview
        const objectUrl = URL.createObjectURL(selectedFile);
        setPreviewUrl(objectUrl);
    };

    const handleClear = () => {
        setFile(null);
        setPreviewUrl(null);
        setError(null);
        setSuccess(false);
        setProgress(0);
        if (fileInputRef.current) {
            fileInputRef.current.value = '';
        }
    };

    const handleUpload = async () => {
        if (!file || !effectiveUserId) {
            setError("Authentication required or no file selected.");
            return;
        }

        setUploading(true);
        setError(null);
        setProgress(0);

        try {
            // 1. Optimize image (Resize & Compress)
            const optimizedBlob = await imageService.optimizeImage(file, 1200, 0.8);
            
            // 2. Final Size Check (2MB limit as per requirements)
            if (optimizedBlob.size > maxSizeMB * 1024 * 1024) {
                setError(`Optimized file still exceeds ${maxSizeMB}MB. Please try a different image.`);
                setUploading(false);
                return;
            }

            // 3. Upload to Server (Firebase Storage) with progress
            const downloadUrl = await imageService.uploadProfileImage(
                effectiveUserId, 
                optimizedBlob, 
                (p) => setProgress(Math.round(p))
            );

            // 4. Save to Database (Firestore)
            await imageService.updateUserProfilePhoto(effectiveUserId, downloadUrl);

            setSuccess(true);
            if (onUploadComplete) {
                onUploadComplete(downloadUrl);
            }
        } catch (err) {
            console.error("Upload failed:", err);
            setError("Upload failed. Please check your connection and try again.");
        } finally {
            setUploading(false);
        }
    };

    return (
        <div className="image-upload-container">
            {!previewUrl ? (
                <label className="upload-dropzone" htmlFor="profile-image-upload-input">
                    <div className="upload-icon-ring">
                        <Upload size={32} className="upload-icon" />
                    </div>
                    <p className="upload-text">Select Profile Photo</p>
                    <p className="upload-limit">Max size: {maxSizeMB}MB (Auto-optimized)</p>
                    <input
                        id="profile-image-upload-input"
                        type="file"
                        onChange={handleFileSelect}
                        accept={allowedTypes.join(',')}
                        className="hidden-input"
                    />
                </label>
            ) : (
                <div className="preview-card">
                    <div className="preview-image-container">
                        <img src={previewUrl} alt="Preview" className="preview-image" />
                        
                        {uploading && (
                            <div className="upload-overlay">
                                <div className="progress-ring-container">
                                    <svg viewBox="0 0 36 36" className="circular-chart">
                                        <path className="circle-bg"
                                            d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
                                        />
                                        <path className="circle"
                                            strokeDasharray={`${progress}, 100`}
                                            d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831"
                                        />
                                    </svg>
                                    <span className="progress-text">{progress}%</span>
                                </div>
                            </div>
                        )}

                        {!uploading && !success && (
                            <button
                                className="remove-btn"
                                onClick={handleClear}
                                title="Change photo"
                            >
                                <X size={16} />
                            </button>
                        )}
                    </div>

                    <div className="preview-actions">
                        {uploading ? (
                            <div className="loading-state">
                                <Loader size={20} className="animate-spin" />
                                <span>Optimizing & Uploading...</span>
                            </div>
                        ) : success ? (
                            <div className="success-state">
                                <Check size={20} />
                                <span>Profile Updated!</span>
                            </div>
                        ) : (
                            <button
                                className="upload-btn"
                                onClick={handleUpload}
                            >
                                <ImageIcon size={18} />
                                Upload & Save
                            </button>
                        )}
                    </div>
                </div>
            )}

            {error && <div className="error-message-upload">{error}</div>}
        </div>
    );
};

