import React, { useState, useRef, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { Upload, X, Check, AlertCircle, Camera, Crop } from 'lucide-react';
import Cropper from 'react-easy-crop';
import getCroppedImg from '../../utils/cropImage';
import { generateCloudinarySignature } from '../../utils/cloudinaryUtils';
import './ImageUploadModal.css';

const ImageUploadModal = ({ isOpen, onClose, currentPreview, onUploadSuccess, userId }) => {
    const [selectedFile, setSelectedFile] = useState(null);
    const [rawImageSrc, setRawImageSrc] = useState(null);

    // Cropper states
    const [crop, setCrop] = useState({ x: 0, y: 0 });
    const [zoom, setZoom] = useState(1);
    const [croppedAreaPixels, setCroppedAreaPixels] = useState(null);

    const [error, setError] = useState('');
    const [status, setStatus] = useState('idle'); // idle, uploading, success
    const [progress, setProgress] = useState(0);
    const fileInputRef = useRef(null);

    const CLOUDINARY_URL = 'https://api.cloudinary.com/v1_1/dzbmrdpzu/image/upload';
    // Requires your Cloudinary API Key and Secret (Get these from your Dashboard)
    const CLOUDINARY_API_KEY = import.meta.env.VITE_CLOUDINARY_API_KEY || ''; 
    const CLOUDINARY_API_SECRET = import.meta.env.VITE_CLOUDINARY_API_SECRET || '';

    const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2 MB

    if (!isOpen) return null;

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (!file) return;

        setError('');

        const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
        if (!validTypes.includes(file.type)) {
            setError('Please select a valid image format (jpg, jpeg, png, webp).');
            return;
        }

        if (file.size > MAX_FILE_SIZE) {
            setError('File size must be less than 2 MB.');
            return;
        }

        setSelectedFile(file);

        const reader = new FileReader();
        reader.onloadend = () => setRawImageSrc(reader.result);
        reader.readAsDataURL(file);
    };

    const onCropComplete = useCallback((croppedArea, croppedAreaPixels) => {
        setCroppedAreaPixels(croppedAreaPixels);
    }, []);

    const handleCropAndUpload = async () => {
        if (!rawImageSrc || !croppedAreaPixels) return;

        if (!CLOUDINARY_API_KEY || !CLOUDINARY_API_SECRET) {
            setError('Missing VITE_CLOUDINARY_API_KEY or SECRET in your .env file. Required for overriding.');
            return;
        }

        setStatus('uploading');
        setProgress(0);
        setError('');

        try {
            const croppedBlob = await getCroppedImg(rawImageSrc, croppedAreaPixels);

            // Build Signed Upload Request
            const timestamp = Math.round((new Date()).getTime() / 1000);
            const safeUserId = userId ? userId.toString().replace(/[^a-zA-Z0-9_-]/g, '') : 'default_user';
            const public_id = `avatar_${safeUserId}`;

            // Generate SHA-1 Hash
            const signature = await generateCloudinarySignature(public_id, timestamp, CLOUDINARY_API_SECRET);

            const formData = new FormData();
            formData.append('file', croppedBlob, 'profile.jpg');
            formData.append('api_key', CLOUDINARY_API_KEY);
            formData.append('timestamp', timestamp);
            formData.append('signature', signature);
            formData.append('public_id', public_id);
            // Notice we do NOT include 'upload_preset' in the signature generation if it's not signed, 
            // standard signed uploads override securely.

            const xhr = new XMLHttpRequest();
            xhr.open('POST', CLOUDINARY_URL, true);

            xhr.upload.onprogress = (e) => {
                if (e.lengthComputable) {
                    const percentComplete = Math.round((e.loaded / e.total) * 100);
                    setProgress(percentComplete);
                }
            };

            xhr.onload = function() {
                if (xhr.status >= 200 && xhr.status < 300) {
                    const response = JSON.parse(xhr.responseText);
                    setStatus('success');
                    onUploadSuccess(response.secure_url);

                    setTimeout(() => {
                        handleClose();
                    }, 2000);
                } else {
                    setStatus('idle');
                    setError('Signed Upload failed. Check your API Keys.');
                    console.error('Cloudinary Error:', xhr.responseText);
                }
            };

            xhr.onerror = function() {
                setStatus('idle');
                setError('Upload failed. Please check your internet connection.');
            };

            xhr.send(formData);

        } catch (e) {
            console.error(e);
            setStatus('idle');
            setError('Failed to crop image. Please try another photo.');
        }
    };

    const handleClose = () => {
        setSelectedFile(null);
        setRawImageSrc(null);
        setCrop({ x: 0, y: 0 });
        setZoom(1);
        setError('');
        setStatus('idle');
        setProgress(0);
        onClose();
    };

    return createPortal(
        <div className="image-upload-overlay animate-fade-in">
            <div className="image-upload-modal animate-slide-up">

                <div className="image-upload-header">
                    <h3 className="section-title !mb-0 text-lg">Update Profile Photo</h3>
                    <button onClick={handleClose} disabled={status === 'uploading'} className="modal-close-btn">
                        <X size={20} />
                    </button>
                </div>

                <div className="image-upload-body">
                    {/* View Area */}
                    {!rawImageSrc ? (
                        <div className="upload-preview-container">
                            <img 
                                src={currentPreview || 'https://ui-avatars.com/api/?name=User'} 
                                alt="Profile Preview" 
                                className="upload-preview-avatar"
                            />
                            {status === 'idle' && (
                                <button 
                                    className="upload-select-btn" 
                                    onClick={() => fileInputRef.current?.click()}
                                    title="Change avatar"
                                >
                                    <Camera size={18} />
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="cropper-container">
                            <div className="cropper-workspace">
                                <Cropper
                                    image={rawImageSrc}
                                    crop={crop}
                                    zoom={zoom}
                                    aspect={3/4}
                                    cropShape="rect"
                                    showGrid={false}
                                    onCropChange={setCrop}
                                    onCropComplete={onCropComplete}
                                    onZoomChange={setZoom}
                                />
                            </div>
                            {/* Zoom Control */}
                            <div className="zoom-control-container">
                                <span className="text-xs font-semibold text-slate-500">Zoom</span>
                                <input
                                    type="range"
                                    value={zoom}
                                    min={1}
                                    max={3}
                                    step={0.1}
                                    aria-labelledby="Zoom"
                                    onChange={(e) => setZoom(e.target.value)}
                                    className="zoom-slider"
                                />
                            </div>
                        </div>
                    )}

                    <input 
                        type="file" 
                        accept=".jpg,.jpeg,.png,.webp" 
                        ref={fileInputRef} 
                        style={{ display: 'none' }} 
                        onChange={handleFileChange} 
                    />

                    {error && (
                        <div className="upload-error-msg animate-fade-in">
                            <AlertCircle size={16} />
                            <span>{error}</span>
                        </div>
                    )}

                    {status === 'uploading' && (
                        <div className="upload-progress-container animate-fade-in">
                            <div className="flex justify-between items-center text-xs mb-1 font-bold text-slate-600 dark:text-slate-300">
                                <span>Uploading...</span>
                                <span>{progress}%</span>
                            </div>
                            <div className="upload-progress-bar-bg">
                                <div 
                                    className="upload-progress-bar-fill" 
                                    style={{ width: `${progress}%` }}
                                ></div>
                            </div>
                        </div>
                    )}

                    {status === 'success' && (
                        <div className="upload-success-msg animate-slide-up">
                            <Check size={18} />
                            <span>Photo uploaded successfully</span>
                        </div>
                    )}

                    {/* Action Area */}
                    <div className="upload-action-area">
                        {status === 'idle' && (
                            <>
                                {rawImageSrc ? (
                                    <button className="btn-primary w-full py-3 flex items-center justify-center gap-2" onClick={handleCropAndUpload}>
                                        <Crop size={18} />
                                        Crop & Upload
                                    </button>
                                ) : (
                                    <button className="upload-action-btn w-full flex items-center justify-center gap-2" onClick={() => fileInputRef.current?.click()}>
                                        <Upload size={20} />
                                        Select New Photo
                                    </button>
                                )}
                                {!rawImageSrc && (
                                    <p className="text-[12px] text-center text-slate-400 mt-5 mb-2 font-medium">
                                        JPG, PNG, or WEBP. Max size: 2 MB
                                    </p>
                                )}
                            </>
                        )}
                    </div>
                </div>

            </div>
        </div>,
        document.body
    );
};

export default ImageUploadModal;

import React, { useState } from 'react';
import { Lock, Fingerprint, ShieldCheck, Eye, EyeOff } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { useToast } from '../../context/ToastContext';
import { nativeAuthService } from '../../services/nativeAuthService';

const SecuritySettings = () => {
    const { user, updateProfileData, changePassword } = useAuth();
    const { showToast } = useToast();
    const [isPasswordUpdating, setIsPasswordUpdating] = useState(false);
    const [passwords, setPasswords] = useState({ current: '', new: '', confirm: '' });
    const [passwordError, setPasswordError] = useState('');
    const [showPasswords, setShowPasswords] = useState(false);

    const handlePasswordUpdate = async () => {
        if (!passwords.current || !passwords.new || !passwords.confirm) {
            setPasswordError('Please fill all password fields.');
            return;
        }
        if (passwords.new !== passwords.confirm) {
            setPasswordError('New passwords do not match.');
            return;
        }
        if (passwords.new.length < 6) {
            setPasswordError('Password must be at least 6 characters.');
            return;
        }

        setIsPasswordUpdating(true);
        setPasswordError('');
        try {
            await changePassword(passwords.current, passwords.new);
            showToast("Password updated successfully!", "success");
            setPasswords({ current: '', new: '', confirm: '' });
        } catch (err) {
            setPasswordError(err.message || "Failed to update password.");
        } finally {
            setIsPasswordUpdating(false);
        }
    };

    return (
        <div className="space-y-6 pb-8">
            {/* Biometric Section */}
            <div className="settings-section-card">
                <div className="settings-item-row">
                    <div className="settings-item-info">
                        <div className="settings-item-icon biometric">
                            <Fingerprint size={22} />
                        </div>
                        <div>
                            <h3 className="settings-item-title">Biometric Unlock</h3>
                            <p className="settings-item-desc">Secure access with fingerprint/FaceID</p>
                        </div>
                    </div>
                    <label className="premium-toggle">
                        <input 
                            type="checkbox" 
                            checked={user?.biometricAuth || false}
                            onChange={async (e) => {
                                const isChecked = e.target.checked;
                                try {
                                    await nativeAuthService.setAuthEnabled(isChecked);
                                    await updateProfileData({ biometricAuth: isChecked });
                                    showToast(isChecked ? "Biometrics enabled!" : "Biometrics disabled", "success");
                                } catch (err) {
                                    showToast("Biometric update failed", "error");
                                }
                            }}
                        />
                        <span className="toggle-slider"></span>
                    </label>
                </div>
            </div>

            {/* Password Update Card */}
            <div className="settings-section-card">
                <div className="settings-item-header">
                    <div className="settings-item-icon security">
                        <Lock size={20} />
                    </div>
                    <div className="flex-1">
                        <h3 className="settings-item-title">Change Password</h3>
                        <p className="settings-item-desc">Keep your account secure</p>
                    </div>
                </div>

                <div className="settings-form-container">
                    <div className="premium-input-group">
                        <label>Current Password</label>
                        <div className="premium-input-wrapper">
                            <input
                                type={showPasswords ? "text" : "password"}
                                placeholder="Current password"
                                value={passwords.current}
                                onChange={(e) => setPasswords({ ...passwords, current: e.target.value })}
                            />
                        </div>
                    </div>

                    <div className="premium-input-group">
                        <label>New Password</label>
                        <div className="premium-input-wrapper">
                            <input
                                type={showPasswords ? "text" : "password"}
                                placeholder="New password"
                                value={passwords.new}
                                onChange={(e) => setPasswords({ ...passwords, new: e.target.value })}
                            />
                        </div>
                    </div>

                    <div className="premium-input-group">
                        <label>Confirm New Password</label>
                        <div className="premium-input-wrapper">
                            <input
                                type={showPasswords ? "text" : "password"}
                                placeholder="Confirm new password"
                                value={passwords.confirm}
                                onChange={(e) => setPasswords({ ...passwords, confirm: e.target.value })}
                            />
                            <button 
                                type="button"
                                onClick={() => setShowPasswords(!showPasswords)}
                                className="input-action-btn"
                            >
                                {showPasswords ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>
                    </div>

                    {passwordError && (
                        <p className="settings-error-text">{passwordError}</p>
                    )}

                    <button
                        className="premium-save-btn"
                        onClick={handlePasswordUpdate}
                        disabled={isPasswordUpdating}
                    >
                        {isPasswordUpdating ? (
                            <span className="flex items-center gap-2 justify-center">
                                <div className="btn-spinner"></div>
                                Updating...
                            </span>
                        ) : 'Save New Password'}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default SecuritySettings;

import React, { useRef, useState } from 'react';
import QRCode from 'react-qr-code';
import { X, Download, Share2, QrCode, GraduationCap, Mail, Phone, MapPin, Calendar, Shield, RefreshCw } from 'lucide-react';
import { Capacitor } from '@capacitor/core';
import { Share as CapacitorShare } from '@capacitor/share';
import { Filesystem, Directory } from '@capacitor/filesystem';
import html2canvas from 'html2canvas';
import './StudentIDCard.css';

const StudentIDCard = ({ user, formData, previewUrl, onClose }) => {
    const cardRef = useRef(null);
    const [isDownloading, setIsDownloading] = useState(false);
    const [isSharing, setIsSharing] = useState(false);
    const [isFlipped, setIsFlipped] = useState(false);

    const qrValue = `STUDENT_ID:${user?.uid || 'UNKNOWN'}`;

    const studentName = formData?.fullName || user?.fullName || 'Student Name';
    const studentId = formData?.studentId || user?.studentId || '—';
    const department = formData?.department || user?.department || 'B.Tech';
    const email = formData?.email || user?.email || '—';
    const phone = formData?.phone ? `+91 ${formData.phone}` : (user?.phone ? `+91 ${user.phone}` : '—');
    const campus = (formData?.campus || user?.campus || 'RGUKT').replace('RGUKT ', '');
    const year = formData?.academicYear || user?.academicYear || '2023 – 2027';
    const avatar = previewUrl || user?.avatar || null;

    const captureCard = async () => {
        if (!cardRef.current) return null;
        const canvas = await html2canvas(cardRef.current, {
            scale: 3,
            useCORS: true,
            backgroundColor: null,
            logging: false,
        });
        return canvas;
    };

    const handleDownload = async () => {
        setIsDownloading(true);
        try {
            const canvas = await captureCard();
            if (!canvas) return;

            if (Capacitor.isNativePlatform()) {
                const base64 = canvas.toDataURL('image/png').split(',')[1];
                const fileName = `Student_ID_${studentId}.png`;
                await Filesystem.writeFile({
                    path: fileName,
                    data: base64,
                    directory: Directory.Documents,
                });
            } else {
                const link = document.createElement('a');
                link.download = `Student_ID_${studentId}.png`;
                link.href = canvas.toDataURL('image/png');
                link.click();
            }
        } catch (err) {
            console.error('Download failed:', err);
        } finally {
            setIsDownloading(false);
        }
    };

    const handleShare = async () => {
        setIsSharing(true);
        try {
            const canvas = await captureCard();
            if (!canvas) return;
            const base64 = canvas.toDataURL('image/png').split(',')[1];
            const fileName = `Student_ID_${studentId}.png`;

            if (Capacitor.isNativePlatform()) {
                const fileResult = await Filesystem.writeFile({
                    path: fileName,
                    data: base64,
                    directory: Directory.Cache,
                });
                await CapacitorShare.share({
                    title: 'My Student ID Card',
                    text: `${studentName} — ${department}`,
                    url: fileResult.uri,
                });
            } else {
                // Web fallback
                const blob = await (await fetch(canvas.toDataURL('image/png'))).blob();
                if (navigator.share && navigator.canShare?.({ files: [new File([blob], fileName)] })) {
                    await navigator.share({ files: [new File([blob], fileName, { type: 'image/png' })], title: 'My Student ID' });
                } else {
                    handleDownload();
                }
            }
        } catch (err) {
            console.error('Share failed:', err);
        } finally {
            setIsSharing(false);
        }
    };

    return (
        <div className="id-card-overlay" onClick={(e) => e.target === e.currentTarget && onClose()}>
            <div className="id-card-modal">
                {/* Close button */}
                <button className="id-card-close" onClick={onClose}>
                    <X size={20} />
                </button>

                <p className="id-card-label">Digital Student ID</p>

                {/* ── THE CARD ── */}
                <div className={`id-card-scene ${isFlipped ? 'is-flipped' : ''}`} onClick={() => setIsFlipped(!isFlipped)}>
                    <div className="id-card-wrapper flip-card-inner" ref={cardRef}>

                        {/* --- FRONT OF CARD --- */}
                        <div className="flip-card-face flip-card-front premium-glass-card landscape-layout">
                            {/* Decorative Background Elements */}
                            <div className="glass-blob glass-blob-tr"></div>
                            <div className="glass-blob glass-blob-bl"></div>
                            <div className="glass-noise-overlay"></div>

                            {/* Header */}
                            <div className="glass-card-header landscape-header">
                                <div className="glass-logo-container">
                                    <GraduationCap size={18} color="#ffffff" strokeWidth={2} />
                                </div>
                                <div className="glass-header-text">
                                    <h3>RGUKT CONNECT</h3>
                                    <p>OFFICIAL STUDENT ID</p>
                                </div>
                            </div>

                            {/* Body (Row based for landscape) */}
                            <div className="glass-card-body landscape-body">
                                <div className="glass-avatar-container landscape-avatar">
                                    <div className="glass-avatar-ring">
                                        {avatar ? (
                                            <img src={avatar} alt="Student" className="glass-avatar-img" crossOrigin="anonymous" />
                                        ) : (
                                            <div className="glass-avatar-placeholder">
                                                {studentName.split(' ').map(n => n[0]).slice(0, 2).join('')}
                                            </div>
                                        )}
                                    </div>
                                    <div className="glass-verified-pill">
                                        <Shield size={10} />
                                        <span>VERIFIED</span>
                                    </div>
                                </div>

                                <div className="glass-student-info landscape-info">
                                    <h2 className="glass-student-name">{studentName}</h2>
                                    <div className="glass-id-badge">{studentId}</div>

                                    <div className="glass-details-grid landscape-grid">
                                        <div className="glass-detail-item">
                                            <div className="glass-detail-icon-wrapper">
                                                <GraduationCap size={12} className="glass-detail-icon" />
                                            </div>
                                            <span>{department}</span>
                                        </div>
                                        <div className="glass-detail-item">
                                            <div className="glass-detail-icon-wrapper">
                                                <Calendar size={12} className="glass-detail-icon" />
                                            </div>
                                            <span>{year}</span>
                                        </div>
                                        <div className="glass-detail-item">
                                            <div className="glass-detail-icon-wrapper">
                                                <Phone size={12} className="glass-detail-icon" />
                                            </div>
                                            <span>{phone}</span>
                                        </div>
                                        <div className="glass-detail-item">
                                            <div className="glass-detail-icon-wrapper">
                                                <MapPin size={12} className="glass-detail-icon" />
                                            </div>
                                            <span className="glass-truncate">{campus}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* --- BACK OF CARD --- */}
                        <div className="flip-card-face flip-card-back premium-glass-card landscape-layout">
                            {/* Decorative Background Elements */}
                            <div className="glass-blob glass-blob-tr"></div>
                            <div className="glass-blob glass-blob-bl"></div>
                            <div className="glass-noise-overlay"></div>

                            <div className="glass-back-content">
                                <h3 className="glass-back-title">Scan to Verify</h3>
                                <div className="glass-qr-container-large">
                                    <QRCode
                                        value={qrValue}
                                        size={140}
                                        level="H"
                                        fgColor="#0f172a"
                                        bgColor="#ffffff"
                                        className="glass-qr-code-large"
                                    />
                                </div>
                                <div className="glass-back-footer">
                                    <div className="glass-barcode-aesthetic back-barcode">
                                        {Array.from({ length: 30 }).map((_, i) => (
                                            <div key={i} className="glass-bar" style={{ height: `${Math.random() * 60 + 40}%`, opacity: Math.random() * 0.4 + 0.3 }} />
                                        ))}
                                    </div>
                                    <span className="glass-back-uid">UID: {user?.uid?.toUpperCase() || '—'}</span>
                                </div>
                            </div>
                        </div>

                    </div>
                </div>

                {/* Action buttons */}
                <div className="id-card-actions">
                    <button className="id-card-action-btn" onClick={handleDownload} disabled={isDownloading}>
                        {isDownloading ? <RefreshCw size={16} className="animate-spin" /> : <Download size={16} />}
                        <span>{isDownloading ? 'Saving…' : 'Download'}</span>
                    </button>
                    <button className="id-card-action-btn id-card-action-share" onClick={handleShare} disabled={isSharing}>
                        {isSharing ? <RefreshCw size={16} className="animate-spin" /> : <Share2 size={16} />}
                        <span>{isSharing ? 'Sharing…' : 'Share'}</span>
                    </button>
                </div>
            </div>
        </div>
    );
};

