import React, { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Html5Qrcode } from 'html5-qrcode';
import { QrCode, FlashlightOff, Flashlight, X, AlertCircle, RefreshCw } from 'lucide-react';
import './AdminQRScanner.css';

const AdminQRScanner = () => {
    const navigate = useNavigate();
    const [scannerState, setScannerState] = useState('idle'); // idle | scanning | success | error
    const [errorMsg, setErrorMsg] = useState('');
    const [torchOn, setTorchOn] = useState(false);
    const scannerRef = useRef(null);
    const html5QrRef = useRef(null);

    const startScanner = async () => {
        setScannerState('scanning');
        setErrorMsg('');

        try {
            const cameras = await Html5Qrcode.getCameras();
            if (!cameras || cameras.length === 0) {
                setErrorMsg('No camera found on this device.');
                setScannerState('error');
                return;
            }

            // Prefer back camera
            const backCamera = cameras.find(c =>
                c.label?.toLowerCase().includes('back') ||
                c.label?.toLowerCase().includes('rear') ||
                c.label?.toLowerCase().includes('environment')
            ) || cameras[cameras.length - 1];

            html5QrRef.current = new Html5Qrcode('qr-scanner-region');

            await html5QrRef.current.start(
                { deviceId: { exact: backCamera.id } },
                {
                    fps: 12,
                    qrbox: { width: 240, height: 240 },
                    aspectRatio: 1.0,
                },
                (decodedText) => handleScanSuccess(decodedText),
                () => { /* quiet scan errors */ }
            );
        } catch (err) {
            console.error('Scanner start failed:', err);
            setErrorMsg('Could not access camera. Please grant camera permission.');
            setScannerState('error');
        }
    };

    const stopScanner = async () => {
        if (html5QrRef.current) {
            try {
                await html5QrRef.current.stop();
                html5QrRef.current.clear();
                html5QrRef.current = null;
            } catch (e) {
                console.warn('Scanner stop error:', e);
            }
        }
    };

    const handleScanSuccess = async (raw) => {
        await stopScanner();
        setScannerState('success');

        let uid = null;

        // Parse formats: "STUDENT_ID:{uid}" or a URL ending in /student/{uid}
        if (raw.startsWith('STUDENT_ID:')) {
            uid = raw.replace('STUDENT_ID:', '').trim();
        } else {
            const urlMatch = raw.match(/\/student\/([a-zA-Z0-9_-]{20,})/);
            if (urlMatch) uid = urlMatch[1];
        }

        if (uid) {
            setTimeout(() => navigate(`/admin/student/${uid}`), 800);
        } else {
            setErrorMsg(`Unrecognized QR format:\n"${raw}"`);
            setScannerState('error');
        }
    };

    const handleReset = async () => {
        await stopScanner();
        setScannerState('idle');
        setErrorMsg('');
    };

    useEffect(() => {
        startScanner();
        return () => { stopScanner(); };
    }, []);

    return (
        <div className="qr-scan-page">
            <div className="qr-scan-header">
                <button className="qr-scan-back" onClick={() => { stopScanner(); navigate('/admin/dashboard'); }}>
                    <X size={20} />
                </button>
                <div>
                    <h1 className="qr-scan-title">QR Scanner</h1>
                    <p className="qr-scan-sub">Scan student ID card QR code</p>
                </div>
            </div>

            <div className="qr-scan-body">
                {/* Camera view */}
                <div className="qr-scan-viewport">
                    <div id="qr-scanner-region" className="qr-scanner-region" />

                    {/* Overlay corners */}
                    {scannerState === 'scanning' && (
                        <>
                            <div className="qr-corner qr-corner-tl" />
                            <div className="qr-corner qr-corner-tr" />
                            <div className="qr-corner qr-corner-bl" />
                            <div className="qr-corner qr-corner-br" />
                            <div className="qr-scan-line" />
                        </>
                    )}

                    {/* Success overlay */}
                    {scannerState === 'success' && (
                        <div className="qr-scan-status-overlay success">
                            <div className="qr-status-icon success-icon">
                                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                                    <polyline points="20 6 9 17 4 12" />
                                </svg>
                            </div>
                            <p>QR Detected!</p>
                            <p className="qr-status-sub">Loading student profile…</p>
                        </div>
                    )}

                    {/* Error overlay */}
                    {scannerState === 'error' && (
                        <div className="qr-scan-status-overlay error">
                            <AlertCircle size={48} />
                            <p>{errorMsg || 'Scan failed'}</p>
                            <button className="qr-retry-btn" onClick={handleReset}>
                                <RefreshCw size={14} /> Try Again
                            </button>
                        </div>
                    )}

                    {/* Idle overlay */}
                    {scannerState === 'idle' && (
                        <div className="qr-scan-status-overlay idle">
                            <QrCode size={48} className="qr-idle-icon" />
                            <p>Starting camera…</p>
                            <button className="qr-retry-btn" onClick={startScanner}>
                                <RefreshCw size={14} /> Start Scanner
                            </button>
                        </div>
                    )}
                </div>

                {/* Instructions */}
                <div className="qr-scan-instructions">
                    <div className="qr-instruction-item">
                        <div className="qr-instr-dot" />
                        <span>Point camera at student's digital ID card QR code</span>
                    </div>
                    <div className="qr-instruction-item">
                        <div className="qr-instr-dot" />
                        <span>Hold steady — scan happens automatically</span>
                    </div>
                    <div className="qr-instruction-item">
                        <div className="qr-instr-dot" />
                        <span>QR always shows live data — no regeneration needed</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AdminQRScanner;

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Users, CheckCircle, Clock, XCircle, AlertCircle } from 'lucide-react';
import { collection, query, where, getDocs, onSnapshot } from 'firebase/firestore';
import { db, contentDb } from '../../config/firebase';
import { getQuestionsForQuiz } from '../../services/quizService';
import { getModuleById, getUnitById } from '../../utils/academicsUtils';
import { PROGRAMS } from '../../config/academics';
import LoadingTransition from '../../components/Common/LoadingTransition';
import { BarChart, Bar, Cell, XAxis, YAxis, Tooltip as RechartsTooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import './AdminQuizAnalytics.css'; // Reuse styles

const AdminQuestionAnalytics = () => {
    const { quizId, questionIndex } = useParams();
    const navigate = useNavigate();

    const [loading, setLoading] = useState(true);
    const [quiz, setQuiz] = useState(null);
    const [attempts, setAttempts] = useState([]);
    const [question, setQuestion] = useState(null);
    const [usersMap, setUsersMap] = useState({});

    // Fetch initial static data
    useEffect(() => {
        const fetchStaticData = async () => {
            try {
                const [usersSnap, questionsSnap] = await Promise.all([
                    getDocs(collection(db, 'users')),
                    getQuestionsForQuiz(quizId)
                ]);

                const qIdx = parseInt(questionIndex, 10);
                if (questionsSnap && questionsSnap.length > qIdx) {
                    setQuestion({ ...questionsSnap[qIdx], originalIndex: qIdx });
                }

                // Fetch module or unit logic
                let targetData = await getModuleById(quizId);
                if (!targetData) {
                    targetData = await getUnitById(quizId);
                }

                if (!targetData) {
                    let found = false;
                    for (const p of PROGRAMS) {
                        for (const y of p.years) {
                            for (const s of y.semesters) {
                                for (const sub of (s.subjects || [])) {
                                    for (const u of (sub.units || [])) {
                                        const matchMod = (u.modules || []).find(m => m.id === quizId);
                                        if (matchMod) {
                                            targetData = matchMod;
                                            found = true;
                                            break;
                                        }
                                        if (u.id === quizId) {
                                            targetData = u;
                                            found = true;
                                            break;
                                        }
                                    }
                                    if (found) break;
                                }
                                if (found) break;
                            }
                            if (found) break;
                        }
                        if (found) break;
                    }
                }

                if (targetData) {
                    setQuiz({ ...targetData, title: targetData.label });
                } else {
                    setQuiz({ title: 'Unknown Quiz' });
                }

                const uMap = {};
                usersSnap.forEach(doc => {
                    uMap[doc.id] = doc.data();
                });
                setUsersMap(uMap);

            } catch (error) {
                console.error("Error fetching question analytics data:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchStaticData();
    }, [quizId, questionIndex]);

    // Real-time listener for attempts
    useEffect(() => {
        if (!quizId) return;
        const q = query(collection(contentDb, 'quiz_attempts'), where('quizId', '==', quizId));

        const unsubscribe = onSnapshot(q, (snapshot) => {
            let liveAttempts = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            // Filter out dummy students
            liveAttempts = liveAttempts.filter(a => !(a.studentId && a.studentId.startsWith('STU')));
            liveAttempts.sort((a, b) => {
                const timeA = a.submittedAt?.toMillis ? a.submittedAt.toMillis() : 0;
                const timeB = b.submittedAt?.toMillis ? b.submittedAt.toMillis() : 0;
                return timeB - timeA;
            });
            setAttempts(liveAttempts);
        });

        return () => unsubscribe();
    }, [quizId]);

    const formatTime = (seconds) => {
        if (!seconds) return "0m 0s";
        const m = Math.floor(seconds / 60);
        const s = Math.floor(seconds % 60);
        return `${m}m ${s}s`;
    };

    // Calculate Question Metrics
    const metrics = useMemo(() => {
        if (!question || !attempts.length) return null;

        let attemptedCount = 0;
        let correctCount = 0;
        let optionDistribution = Array(question.options.length).fill(0);
        const studentAnswersList = [];

        attempts.forEach(attempt => {
            if (attempt.answers && attempt.answers.hasOwnProperty(question.originalIndex)) {
                attemptedCount++;
                const selectedOpt = attempt.answers[question.originalIndex];
                const isCorrect = selectedOpt === question.correctAnswerIndex;

                if (isCorrect) correctCount++;
                if (selectedOpt >= 0 && selectedOpt < question.options.length) {
                    optionDistribution[selectedOpt]++;
                }

                studentAnswersList.push({
                    attemptId: attempt.id,
                    studentId: attempt.studentId,
                    studentName: attempt.studentName,
                    selectedOpt,
                    isCorrect,
                    marks: isCorrect ? (question.marks || 1) : 0,
                    timeTaken: attempt.timeTaken,
                    submittedAt: attempt.submittedAt
                });
            }
        });

        const incorrectCount = attemptedCount - correctCount;
        const correctPercent = attemptedCount > 0 ? Math.round((correctCount / attemptedCount) * 100) : 0;
        const incorrectPercent = attemptedCount > 0 ? Math.round((incorrectCount / attemptedCount) * 100) : 0;

        return {
            attemptedCount,
            correctCount,
            incorrectCount,
            correctPercent,
            incorrectPercent,
            optionDistribution,
            studentAnswersList
        };
    }, [question, attempts]);

    if (loading) return <LoadingTransition message="Loading Question Analytics..." />;
    if (!quiz || !question) return <div className="p-8 text-center text-red-500">Question not found.</div>;

    return (
        <div className="analytics-dashboard-container">
            <div className="premium-header">
                <div className="header-left">
                    <button onClick={() => navigate('/admin/quizzes')} className="back-btn-premium" title="Back to Dashboard">
                        <ArrowLeft size={22} />
                    </button>
                    <div className="header-text-group">
                        <h1 style={{fontSize: '1.25rem', marginBottom: '0.25rem'}}>{quiz.title}</h1>
                        <p style={{fontSize: '0.875rem', opacity: 0.8}}>Question {question.originalIndex + 1} Analytics</p>
                    </div>
                </div>
            </div>

            {/* Question Details Card */}
            <div className="single-question-card">
                <div className="single-question-header">
                    <div>
                        <span className="text-gray-400 font-bold uppercase tracking-wider text-xs mb-2 block">Question {question.originalIndex + 1}</span>
                        <h2 className="single-question-text">{question.questionText}</h2>
                    </div>
                    <div className="single-question-marks">
                        <span className="single-question-marks-label">Marks</span>
                        <span className="single-question-marks-value">{question.marks || 1}</span>
                    </div>
                </div>

                <div className="single-question-body">
                    <div>
                        <h4 className="single-question-section-title">Options</h4>
                        <div className="options-list-premium">
                            {question.options.map((opt, optIdx) => {
