                         <p className="text-3xl font-black text-blue-400">{formatTime(avgTimeTakenSeconds)}</p>
                         <p className="text-sm text-gray-400 mt-2">Across all {totalParticipants} attempts</p>
                    </div>
                </div>
            )}

            <div className="filters-bar">
