export default AttendanceManagement;

import React, { useState } from 'react';
import { db, bulkUploadDb } from '../../config/firebase';
import { collection, doc, writeBatch, serverTimestamp } from 'firebase/firestore';
import readXlsxFile from 'read-excel-file';
import { Upload, FileText, CheckCircle2, AlertCircle, Loader2, Award, Users } from 'lucide-react';
import './AttendanceManagement.css'; // Reusing AttendanceManagement CSS

const CgpaManagement = () => {
    const [file, setFile] = useState(null);
    const [loading, setLoading] = useState(false);
    const [status, setStatus] = useState({ type: '', message: '' });
    const [preview, setPreview] = useState([]);

    const handleFileChange = async (e) => {
        const selectedFile = e.target.files[0];
        if (!selectedFile) return;

        setFile(selectedFile);
        setStatus({ type: '', message: '' });

        try {
            const rows = await readXlsxFile(selectedFile);
            setPreview(rows.slice(1, 11)); // Show first 10 for preview
        } catch (error) {
            console.error("Error reading excel:", error);
            setStatus({ type: 'error', message: 'Failed to read Excel file. Ensure it is a valid .xlsx file.' });
        }
    };

    const formatCgpa = (val) => {
        if (val === undefined || val === null) return "0.00";
        let num = parseFloat(val);
        if (isNaN(num)) return "0.00";
        // Ensure CGPA is properly formatted to 2 decimal places
        return num.toFixed(2);
    };

    const handleUpload = async () => {
        if (!file) {
            setStatus({ type: 'error', message: 'Please select an Excel file first.' });
            return;
        }

        setLoading(true);
        setStatus({ type: 'info', message: 'Processing and uploading data...' });

        try {
            const rows = await readXlsxFile(file);
            const dataRows = rows.slice(1);
            let batch = writeBatch(bulkUploadDb);
            const cgpaRef = collection(bulkUploadDb, 'cgpa_records');

            let count = 0;
            for (const row of dataRows) {
                // Ensure at least 3 columns: ID NUMBER, Name, CGPA
                const [studentIdRaw, name, cgpaRaw] = row;

                if (!studentIdRaw) continue;

                const id = studentIdRaw.toString().toUpperCase().trim();
                const docRef = doc(cgpaRef, id);

                batch.set(docRef, {
                    studentId: id,
                    name: (name || 'N/A').toString().trim(),
                    cgpa: formatCgpa(cgpaRaw),
                    updatedAt: serverTimestamp()
                });

                count++;

                // Firestore batches are limited to 500 operations
                if (count % 500 === 0) {
                    await batch.commit();
                    batch = writeBatch(bulkUploadDb); // RESET BATCH
                }
            }

            if (count % 500 !== 0) {
                await batch.commit();
            }
            setStatus({ type: 'success', message: `Successfully updated CGPA for ${count} students.` });
            setPreview([]);
            setFile(null);
        } catch (error) {
            console.error("Bulk upload error:", error);
            setStatus({ type: 'error', message: 'An error occurred during upload. Please try again.' });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="attendance-mgmt-container animate-fade-in">
            <div className="admin-header">
                <div className="header-content">
                    <Award className="header-icon" />
                    <div>
                        <h1>CGPA Management</h1>
                        <p>Upload student CGPA via Excel (.xlsx)</p>
                    </div>
                </div>
            </div>

            <div className="upload-section card">
                <div className="upload-zone">
                    <input 
                        type="file" 
                        accept=".xlsx" 
                        onChange={handleFileChange} 
                        id="excel-upload"
                        className="hidden-input"
                    />
                    <label htmlFor="excel-upload" className="upload-label">
                        <div className="upload-icon-box">
                            <Upload size={32} />
                        </div>
                        <div className="upload-text">
                            <h3>{file ? file.name : 'Click to select or drag Excel file'}</h3>
                            <p>Required columns: [ID NUMBER, Name, CGPA]</p>
                        </div>
                    </label>
                </div>

                {preview.length > 0 && (
                    <div className="preview-area">
                        <div className="preview-header">
                            <Users size={16} />
                            <span>Preview (Check alignment below)</span>
                        </div>
                        <div className="table-responsive">
                            <table className="preview-table">
                                <thead>
                                    <tr>
                                        <th>ID Number</th>
                                        <th>Name</th>
                                        <th>CGPA</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {preview.map((row, i) => (
                                        <tr key={i}>
                                            <td className="font-bold">{row[0]}</td>
                                            <td>{row[1]}</td>
                                            <td className="text-primary-600 font-bold">{formatCgpa(row[2])}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                <div className="action-bar">
                    {status.message && (
                        <div className={`status-pill ${status.type}`}>
                            {status.type === 'success' ? <CheckCircle2 size={16} /> : 
                             status.type === 'error' ? <AlertCircle size={16} /> : 
                             <Loader2 size={16} className="animate-spin" />}
                            <span>{status.message}</span>
                        </div>
                    )}
                    <button 
                        className={`btn btn-primary btn-upload ${loading ? 'loading' : ''}`}
                        onClick={handleUpload}
                        disabled={loading || !file}
                    >
                        {loading ? 'Uploading...' : 'Confirm Bulk Upload'}
                    </button>
                </div>
            </div>

            <div className="instructions card">
                <div className="card-header">
                    <FileText size={18} />
                    <h2>Excel Template Format</h2>
                </div>
                <div className="card-body">
                    <p>Ensure your Excel file follows this structure exactly for successful processing:</p>
                    <div className="template-grid" style={{ gridTemplateColumns: 'repeat(3, 1fr)' }}>
                        <div className="template-item"><span>A</span> ID NUMBER</div>
                        <div className="template-item"><span>B</span> Student Name</div>
                        <div className="template-item"><span>C</span> CGPA</div>
                    </div>
                    <div className="alert-box info">
                        <AlertCircle size={16} />
                        <span>Existing records with the same Student ID will be overwritten.</span>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CgpaManagement;

import React, { useState, useEffect, useRef } from 'react';
import { collection, query, orderBy, onSnapshot, doc, updateDoc, serverTimestamp, arrayUnion, deleteDoc, where, getDocs, getDoc } from 'firebase/firestore';
import { db, complaintsDb } from '../../config/firebase';
import { useAuth } from '../../context/AuthContext';
import { MessageSquare, Clock, CheckCircle, AlertCircle, Filter, Search, Send, User, Trash2, ChevronDown, Circle, UserX, ShieldCheck, ShieldX, RefreshCw, Check, Hourglass, Settings, Target, TrendingUp, ArrowLeft, ArrowUpRight, AlertTriangle, BarChart2, CheckSquare, XCircle } from 'lucide-react';
import { createPortal } from 'react-dom';
import LoadingTransition from '../../components/Common/LoadingTransition';
import './ComplaintsManagement.css';
import { deleteProfileImage } from '../../services/imageService';

const ComplaintsManagement = () => {
    const { user } = useAuth();
    const [complaints, setComplaints] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [filter, setFilter] = useState('all');
    const [activeTab, setActiveTab] = useState('new'); // 'new' (pending/active) or 'history' (resolved)
    const [selectedId, setSelectedId] = useState(null); // Track only ID
    const [selectedComplaint, setSelectedComplaint] = useState(null); // Full data via dedicated listener
    const [isDetailLoading, setIsDetailLoading] = useState(false);
    const [adminReply, setAdminReply] = useState('');
    const [isUpdating, setIsUpdating] = useState(false);
    const [showResolveModal, setShowResolveModal] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [complaintToDelete, setComplaintToDelete] = useState(null);
    const [showDeleteSuccess, setShowDeleteSuccess] = useState(false);
    const [isFilterOpen, setIsFilterOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');
    const [categoryFilter, setCategoryFilter] = useState('all'); // 'all', 'academic', 'hostel', 'mess', 'transport', 'wifi/network', 'facilities', 'examination', 'other', 'follow-up'

    // New Admin Controls State
    const [editStatus, setEditStatus] = useState('pending');
    const [editAssigneeName, setEditAssigneeName] = useState('');
    const [editAssigneeRole, setEditAssigneeRole] = useState('');
    const [editEta, setEditEta] = useState('');
    const [editPriority, setEditPriority] = useState('Medium');
    const [editCategory, setEditCategory] = useState('academic');
    const [showUpdateStatusModal, setShowUpdateStatusModal] = useState(false);

    const chatContainerRef = useRef(null);
    const filterDropdownRef = useRef(null);

    // Section tabs: 'complaints' | 'deletions'
    const [sectionTab, setSectionTab] = useState('complaints');

    // Deletion Requests State
    const [deletionRequests, setDeletionRequests] = useState([]);
    const [isDeletionLoading, setIsDeletionLoading] = useState(true);
    const [selectedDeletion, setSelectedDeletion] = useState(null);
    const [isDeletionProcessing, setIsDeletionProcessing] = useState(false);
    const [showApproveModal, setShowApproveModal] = useState(false);
    const [showRejectModal, setShowRejectModal] = useState(false);
    const [rejectNote, setRejectNote] = useState('');
    const [deletionFilter, setDeletionFilter] = useState('pending');

    // List Listener
    useEffect(() => {
        const q = query(collection(complaintsDb, 'complaints'), orderBy('createdAt', 'desc'));
        let isInitialLoad = true;
        const unsubscribe = onSnapshot(q, (snapshot) => {
            const data = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            setComplaints(data);

            if (isInitialLoad) {
                setTimeout(() => {
                    setIsLoading(false);
                    isInitialLoad = false;
                }, 2000);
            } else {
                setIsLoading(false);
            }
        });

        const handleClickOutside = (event) => {
            if (filterDropdownRef.current && !filterDropdownRef.current.contains(event.target)) {
                setIsFilterOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);

        return () => {
            unsubscribe();
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, []);

    // Deletion Requests Listener
    useEffect(() => {
        const q = query(collection(db, 'deletion_requests'), orderBy('createdAt', 'desc'));
        const unsubscribe = onSnapshot(q, (snapshot) => {
            const data = snapshot.docs.map(d => ({ id: d.id, ...d.data() }));
            setDeletionRequests(data);
            setIsDeletionLoading(false);
        }, () => setIsDeletionLoading(false));
        return () => unsubscribe();
    }, []);

    const handleApproveDeletion = async () => {
        if (!selectedDeletion) return;
        setIsDeletionProcessing(true);
        try {
            // Fetch user to get avatar
            const userRef = doc(db, 'users', selectedDeletion.uid);
            const userSnap = await getDoc(userRef);
            if (userSnap.exists()) {
                const userData = userSnap.data();
                if (userData.avatar || userData.photo) {
                    const photoUrl = userData.avatar || userData.photo;
                    await deleteProfileImage(photoUrl);
                }
            }
            
            // Delete the user document from Firestore
            await deleteDoc(userRef);
            // Mark the request as approved
            await updateDoc(doc(db, 'deletion_requests', selectedDeletion.id), {
                status: 'approved',
                resolvedAt: serverTimestamp(),
                resolvedBy: user?.uid || 'admin'
            });
            setShowApproveModal(false);
            setSelectedDeletion(null);
        } catch (err) {
            console.error('Approve deletion error:', err);
            alert('Failed to approve deletion: ' + err.message);
        } finally {
            setIsDeletionProcessing(false);
        }
    };

    const handleRejectDeletion = async () => {
        if (!selectedDeletion) return;
        setIsDeletionProcessing(true);
        try {
            await updateDoc(doc(db, 'deletion_requests', selectedDeletion.id), {
                status: 'rejected',
                adminNote: rejectNote.trim() || null,
                resolvedAt: serverTimestamp(),
                resolvedBy: user?.uid || 'admin'
            });
            setShowRejectModal(false);
            setRejectNote('');
            setSelectedDeletion(null);
        } catch (err) {
            console.error('Reject deletion error:', err);
            alert('Failed to reject deletion: ' + err.message);
        } finally {
            setIsDeletionProcessing(false);
        }
    };

    const handleUpdateProgress = async (newStep) => {
        if (!selectedDeletion) return;
        setIsDeletionProcessing(true);
        try {
            await updateDoc(doc(db, 'deletion_requests', selectedDeletion.id), {
                progressStep: newStep
            });
            // Update local state for immediate feedback
            setSelectedDeletion(prev => ({ ...prev, progressStep: newStep }));
        } catch (err) {
            console.error('Update progress error:', err);
            alert('Failed to update progress: ' + err.message);
        } finally {
            setIsDeletionProcessing(false);
        }
    };

    const REASON_LABELS = {
        graduated: 'Graduated / No longer a student',
        privacy: 'Privacy concerns',
        duplicate: 'Duplicate account',
        not_using: 'No longer using the app',
        data_concerns: 'Data / security concerns',
        other: 'Other'
    };

    // Selected Complaint Detail Listener
    useEffect(() => {
        if (!selectedId) {
            setSelectedComplaint(null);
            setIsDetailLoading(false);
            return;
        }

        setIsDetailLoading(true);
        const unsubscribe = onSnapshot(doc(complaintsDb, 'complaints', selectedId), (docSnap) => {
            if (docSnap.exists()) {
                const data = { id: docSnap.id, ...docSnap.data() };
                if (data.messages) {
                    data.messages.sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
                }
                setSelectedComplaint(data);
                
                // Populate Edit States
                setEditStatus(data.status || 'pending');
                setEditAssigneeName(data.assigneeName || '');
                setEditAssigneeRole(data.assigneeRole || '');
                setEditPriority(data.priority || 'Medium');
                setEditCategory(data.category || 'academic');
                if (data.etaDate) {
                    try {
                        const d = data.etaDate?.toDate ? data.etaDate.toDate() : new Date(data.etaDate);
                        if (!isNaN(d.getTime())) {
                            // format to YYYY-MM-DDThh:mm
                            setEditEta(new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0,16));
                        }
                    } catch (e) {
                        setEditEta('');
                    }
                } else {
                    setEditEta('');
                }
            }
            setIsDetailLoading(false);
        });

        return () => unsubscribe();
    }, [selectedId]);

    const handleUpdateStatus = async (id, newStatus) => {
        // Optimistic UI update for immediate feedback
        if (newStatus === 'resolved') {
            setShowSuccessModal(true);
            setTimeout(() => setShowSuccessModal(false), 2000); // Auto hide after 2s
        }

        try {
            const updateData = {
                status: newStatus,
                updatedAt: serverTimestamp(),
                [`statusHistory.${newStatus}`]: serverTimestamp()
            };

            if (newStatus === 'resolved') {
                const resolutionMessage = {
                    senderId: 'system',
                    senderRole: 'system',
                    senderName: 'System',
                    text: 'Complaint marked as resolved.',
                    type: 'resolution',
                    createdAt: new Date().toISOString()
                };
                updateData.messages = arrayUnion(resolutionMessage);
            }

            await updateDoc(doc(complaintsDb, 'complaints', id), updateData);
        } catch (error) {
            console.error("Error updating status:", error);
            alert("Failed to update status.");
            if (newStatus === 'resolved') setShowSuccessModal(false); // Revert on error
        }
    };

    const handleSaveControls = async () => {
        if (!selectedComplaint) return;
        setIsUpdating(true);
        try {
            const updateData = {
                status: editStatus,
                assigneeName: editAssigneeName.trim(),
                assigneeRole: editAssigneeRole.trim(),
                priority: editPriority,
                category: editCategory,
                etaDate: editEta ? new Date(editEta) : null,
                updatedAt: serverTimestamp(),
                ...(editStatus !== selectedComplaint?.status ? { [`statusHistory.${editStatus}`]: serverTimestamp() } : {})
            };
            
            if (editStatus === 'resolved' && selectedComplaint.status !== 'resolved') {
                 const resolutionMessage = {
                    senderId: 'system',
                    senderRole: 'system',
                    senderName: 'System',
                    text: 'Complaint marked as resolved.',
                    type: 'resolution',
                    createdAt: new Date().toISOString()
                };
                updateData.messages = arrayUnion(resolutionMessage);
                setShowSuccessModal(true);
                setTimeout(() => setShowSuccessModal(false), 2000);
            }

            await updateDoc(doc(complaintsDb, 'complaints', selectedComplaint.id), updateData);
            alert("Complaint details saved successfully!");
        } catch (err) {
            console.error(err);
            alert("Failed to save complaint details.");
        } finally {
            setIsUpdating(false);
        }
    };

    const handleDeleteClick = (e, id) => {
        e.stopPropagation();
        setComplaintToDelete(id);
        setShowDeleteModal(true);
    };

    const confirmDelete = async () => {
        if (!complaintToDelete) return;

        try {
            await deleteDoc(doc(complaintsDb, 'complaints', complaintToDelete));

            // If the deleted complaint was selected, clear selection
            if (selectedId === complaintToDelete) {
                setSelectedId(null);
                setSelectedComplaint(null);
            }

            setShowDeleteModal(false);
            setComplaintToDelete(null);

            // Show red success animation
            setShowDeleteSuccess(true);
            setTimeout(() => setShowDeleteSuccess(false), 2000);
        } catch (error) {
            console.error("Error deleting complaint:", error);
            alert("Failed to delete complaint.");
        }
    };

    const handleSendReply = async () => {
        if (!selectedComplaint || !adminReply.trim()) return;

        setIsUpdating(true);
        try {
            const newMessage = {
                id: Date.now().toString(),
                senderId: user.uid,
                senderRole: 'admin',
                senderName: 'Admin',
                text: adminReply.trim(),
                createdAt: new Date().toISOString()
            };

            const isFollowUpActive = selectedComplaint.followUpEnquiry && selectedComplaint.followUpEnquiry.isActive;

            // Optimistic update
            if (isFollowUpActive) {
                const updatedMessages = [...(selectedComplaint.followUpEnquiry.messages || []), newMessage];
                setSelectedComplaint(prev => ({
                    ...prev,
                    followUpEnquiry: {
                        ...prev.followUpEnquiry,
                        messages: updatedMessages,
                        status: 'replied'
                    }
                }));

                setAdminReply('');

                await updateDoc(doc(complaintsDb, 'complaints', selectedComplaint.id), {
                    'followUpEnquiry.messages': updatedMessages,
                    'followUpEnquiry.status': 'replied',
                    updatedAt: serverTimestamp()
                });
            } else {
                setSelectedComplaint(prev => ({
                    ...prev,
                    messages: [...(prev.messages || []), newMessage]
                }));

                setAdminReply('');

                await updateDoc(doc(complaintsDb, 'complaints', selectedComplaint.id), {
                    messages: arrayUnion(newMessage),
                    hasUnreadReply: true, // Notify student
                    updatedAt: serverTimestamp()
                });
            }
        } catch (error) {
            console.error("Detailed error sending reply:", error);
            alert("Failed to send reply: " + error.message);
        } finally {
            setIsUpdating(false);
        }
    };

    const handleActivateAccount = async (complaint) => {
        if (!complaint.uid) return;

        setIsUpdating(true);
        try {
            // 1. Activate the user
            const userRef = doc(db, 'users', complaint.uid);
            await updateDoc(userRef, {
                status: 'active',
                updatedAt: serverTimestamp()
            });

            // 2. Resolve the complaint
            await handleUpdateStatus(complaint.id, 'resolved');

            alert("Account activated successfully!");
        } catch (error) {
            console.error("Error activating account:", error);
            alert("Failed to activate account.");
        } finally {
            setIsUpdating(false);
        }
    };

    const messagesEndRef = useRef(null);

    // Auto-scroll effect
    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [selectedComplaint?.messages]);

    const [isFocused, setIsFocused] = useState(false);

    const getFormattedId = (c) => {
        if (c.complaintId) return c.complaintId;
        // Fallback for older complaints
        const shortId = c.id ? c.id.slice(-4).toUpperCase() : 'UNK';
        return `ID-${shortId}`;
    };

    const filteredComplaints = complaints.filter(c => {
        // First filter by section
        if (activeTab === 'new') {
            if (c.status === 'resolved') return false;
        } else { // history
            if (c.status !== 'resolved') return false;
        }

        // Then filter by search query
        if (searchQuery.trim()) {
            const query = searchQuery.toLowerCase();
            const formattedId = getFormattedId(c).toLowerCase();
            const matchesId = formattedId.includes(query) || (c.id?.toLowerCase().includes(query));
            const matchesName = c.studentName?.toLowerCase().includes(query);
            const matchesSubject = c.subject?.toLowerCase().includes(query);
            if (!matchesId && !matchesName && !matchesSubject) return false;
        }

        // Then filter by status if applicable (within the section)
        if (filter !== 'all' && c.status !== filter) return false;

        // Then filter by category
        if (categoryFilter !== 'all') {
            if (categoryFilter === 'follow-up') {
                if (!c.followUpEnquiry || !c.followUpEnquiry.isActive) return false;
            } else {
                if (c.category?.toLowerCase() !== categoryFilter.toLowerCase()) return false;
            }
        }

        return true;
    });

    // Counts for badges
    const newCount = complaints.filter(c => c.status !== 'resolved').length;
    const historyCount = complaints.filter(c => c.status === 'resolved').length;

    const quickReplies = [
        "Your issue has been resolved. Let us know if you need anything else.",
        "We are looking into this and will get back to you soon.",
        "Please provide more details or a screenshot of the issue.",
        "This has been forwarded to the relevant department."
    ];

    if (isLoading) return <LoadingTransition message="Complaints Database Loading" persistent />;

    const pendingDeletionCount = deletionRequests.filter(r => r.status === 'pending').length;
    const filteredDeletions = deletionRequests.filter(r => {
        if (deletionFilter === 'all') return true;
        return r.status === deletionFilter;
    });

    return (
        <div className="admin-container">
            {!selectedId && !selectedDeletion && (
                <>
                    <div className="page-header-v2">
                        <div className="header-accent-bar"></div>
                        <div className="header-content-v2">
                            <h1 className="page-title-v2">Complaints Management</h1>
                            <p className="page-subtitle-v2">Listen to student concerns and resolve issues effectively.</p>
                        </div>
                    </div>

                    {/* Section Tabs */}
                    <div className="sidebar-tabs-container" style={{ marginBottom: '1.5rem', maxWidth: 400 }}>
                        <button
                            className={`sidebar-tab ${sectionTab === 'complaints' ? 'active' : ''}`}
                            onClick={() => setSectionTab('complaints')}
                        >
                            <span className="tab-label">Complaints</span>
                            {complaints.filter(c => c.status !== 'resolved').length > 0 && (
                                <span className="tab-badge">{complaints.filter(c => c.status !== 'resolved').length}</span>
                            )}
                        </button>
                        <button
                            className={`sidebar-tab ${sectionTab === 'deletions' ? 'active' : ''}`}
                            onClick={() => setSectionTab('deletions')}
                        >
                            <span className="tab-label">Deletion Requests</span>
                            {pendingDeletionCount > 0 && (
                                <span className="tab-badge" style={{ background: '#ef4444' }}>{pendingDeletionCount}</span>
                            )}
                        </button>
                    </div>
                </>
            )}

            {sectionTab === 'deletions' ? (
                /* ===== DELETION REQUESTS PANEL ===== */
                <div className="complaints-mgmt-layout full-width-mode">
                    {!selectedDeletion ? (
                    <div className="complaints-sidebar section-card flex flex-col w-full h-full">
                        <div className="sidebar-tabs-container">
                            {['pending','approved','rejected','all'].map(f => (
                                <button
                                    key={f}
                                    className={`sidebar-tab ${deletionFilter === f ? 'active' : ''}`}
                                    style={{ fontSize: '0.7rem', padding: '0.5rem 0.6rem' }}
                                    onClick={() => setDeletionFilter(f)}
                                >
                                    {f.charAt(0).toUpperCase() + f.slice(1)}
                                    {f === 'pending' && pendingDeletionCount > 0 && (
                                        <span className="tab-badge" style={{ background: '#ef4444', marginLeft: 4 }}>{pendingDeletionCount}</span>
                                    )}
                                </button>
                            ))}
                        </div>
                        <div className="complaints-mgmt-list">
                            {isDeletionLoading ? (
                                <div className="p-8 text-center text-slate-400">Loading...</div>
                            ) : filteredDeletions.length === 0 ? (
                                <div style={{ padding: '4rem 2rem', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: '#64748b', height: '100%', flex: 1, textAlign: 'center' }}>
                                    <div style={{ background: '#f1f5f9', padding: '1.25rem', borderRadius: '50%', marginBottom: '1rem' }}>
                                        <UserX size={48} color="#94a3b8" />
                                    </div>
                                    <h3 style={{ fontSize: '1.1rem', fontWeight: 600, color: '#334155', marginBottom: '0.25rem' }}>No Requests Found</h3>
                                    <p style={{ fontSize: '0.85rem', color: '#64748b' }}>There are no {deletionFilter === 'all' ? 'account deletion' : `${deletionFilter} deletion`} requests at this time.</p>
                                </div>
                            ) : filteredDeletions.map(req => (
                                <div
                                    key={req.id}
                                    className={`cm-premium-card ${selectedDeletion?.id === req.id ? 'active' : ''}`}
                                    onClick={() => setSelectedDeletion(req)}
                                >
                                    <div className="cm-card-content">
                                        <div className="cm-card-left">
                                            <div className="cm-card-header" style={{ marginBottom: '0.25rem' }}>
                                                <span className={`detail-metadata-pill ${
                                                    req.status === 'pending' ? 'priority-medium' :
                                                    req.status === 'approved' ? 'priority-low' :
                                                    'priority-high'
                                                }`} style={{ fontSize: '0.65rem', padding: '0.2rem 0.5rem', textTransform: 'uppercase', marginBottom: '0.25rem' }}>
                                                    {req.status?.toUpperCase()}
                                                </span>
                                            </div>
                                            <h3 className="cm-title truncate" style={{ fontSize: '0.9rem', marginBottom: '0.25rem', display: 'flex', alignItems: 'center', gap: '0.35rem' }}>
                                                <User size={14} color="#94a3b8" />
                                                {req.studentName}
                                            </h3>
                                            <div className="text-sm font-semibold truncate text-red-600" style={{ fontSize: '0.8rem', color: '#ef4444' }}>
                                                {REASON_LABELS[req.reason] || req.reason}
                                            </div>
                                        </div>
                                        <div className="cm-card-right">
                                            <div className="cm-date-label">
                                                {req.createdAt?.toDate?.()?.toLocaleDateString() || 'Recently'}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                    ) : (
                    <div className="complaint-detail-container section-card no-padding flex flex-col h-full overflow-hidden relative w-full animate-slide-in">
                        <div style={{ padding: '1.25rem 2rem', display: 'flex', alignItems: 'center', gap: '1rem', borderBottom: '1px solid #e2e8f0', background: '#ffffff', flexShrink: 0 }}>
                            <button 
                                onClick={() => setSelectedDeletion(null)}
                                style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', width: '36px', height: '36px', borderRadius: '50%', background: '#f1f5f9', color: '#0f172a', border: 'none', cursor: 'pointer', transition: 'background 0.2s' }}
                                onMouseOver={(e) => e.currentTarget.style.background = '#e2e8f0'}
                                onMouseOut={(e) => e.currentTarget.style.background = '#f1f5f9'}
                            >
                                <ArrowLeft size={20} strokeWidth={2.5} />
                            </button>
                            <h2 style={{ fontSize: '1.5rem', fontWeight: 800, color: '#0f172a', margin: 0, letterSpacing: '-0.025em', lineHeight: 1 }}>Request Details</h2>
                        </div>
                        {selectedDeletion ? (
                            <div style={{ padding: '2rem', display: 'flex', flexDirection: 'column', gap: '1.5rem', height: '100%', overflowY: 'auto', background: '#f8fafc' }}>
                                {/* Top Header Breadcrumb & Status */}
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '0.75rem', fontWeight: 600, color: '#64748b' }}>
                                        <span>Requests</span>
                                        <span>›</span>
                                        <span style={{ color: '#3b82f6' }}>Deletion Request #{selectedDeletion.id.slice(0, 5).toUpperCase()}</span>
                                    </div>
                                    <span className={`detail-metadata-pill ${
                                        selectedDeletion.status === 'pending' ? 'priority-medium' :
                                        selectedDeletion.status === 'approved' ? 'priority-low' :
                                        'priority-high'
                                    }`} style={{ fontSize: '0.7rem', padding: '0.3rem 0.75rem', textTransform: 'uppercase', borderRadius: '1rem', background: selectedDeletion.status === 'pending' ? '#ffedd5' : selectedDeletion.status === 'approved' ? '#dcfce7' : '#fee2e2', color: selectedDeletion.status === 'pending' ? '#ea580c' : selectedDeletion.status === 'approved' ? '#16a34a' : '#ef4444' }}>
                                        <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'currentColor', display: 'inline-block', marginRight: 6 }}></div>
                                        {selectedDeletion.status?.toUpperCase()}
                                    </span>
                                </div>

                                {/* Main 2-Column Layout */}
                                <div style={{ display: 'grid', gridTemplateColumns: '1.5fr 1fr', gap: '1.5rem', alignItems: 'start' }}>
                                    
                                    {/* LEFT COLUMN */}
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                                        
                                        {/* Profile Card */}
                                        <div style={{ background: '#ffffff', borderRadius: '0.5rem', border: '1px solid #e2e8f0', padding: '1.25rem', display: 'flex', alignItems: 'center', gap: '1.25rem' }}>
                                            <div style={{ width: 56, height: 56, borderRadius: '50%', background: '#fee2e2', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                                                <UserX size={28} color="#ef4444" />
                                            </div>
                                            <div style={{ flex: 1 }}>
                                                <h2 style={{ fontSize: '1.1rem', fontWeight: 700, color: '#1e293b', margin: 0, marginBottom: '0.15rem' }}>{selectedDeletion.studentName}</h2>
                                                <p style={{ fontSize: '0.8rem', color: '#64748b', margin: 0, marginBottom: '0.5rem' }}>{selectedDeletion.studentEmail}</p>
                                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                                    <span style={{ fontSize: '0.65rem', fontWeight: 700, background: '#f1f5f9', color: '#64748b', padding: '0.2rem 0.5rem', borderRadius: '0.25rem' }}>STUDENT ID: {selectedDeletion.studentId}</span>
                                                    <span style={{ fontSize: '0.65rem', fontWeight: 700, background: '#dcfce7', color: '#16a34a', padding: '0.2rem 0.5rem', borderRadius: '0.25rem' }}>ACTIVE STATUS</span>
                                                </div>
                                            </div>
                                            <div style={{ alignSelf: 'flex-start' }}>
                                                <ArrowUpRight size={20} color="#3b82f6" />
                                            </div>
                                        </div>

                                        {/* Request Details Card */}
                                        <div style={{ background: '#ffffff', borderRadius: '0.5rem', border: '1px solid #e2e8f0', overflow: 'hidden' }}>
                                            <div style={{ display: 'flex', borderBottom: '1px solid #f1f5f9' }}>
                                                <div style={{ flex: 1, padding: '1.25rem', borderRight: '1px solid #f1f5f9' }}>
                                                    <p style={{ fontSize: '0.65rem', fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.25rem' }}>Reason</p>
                                                    <p style={{ fontSize: '0.95rem', fontWeight: 600, color: '#ef4444', margin: 0 }}>{REASON_LABELS[selectedDeletion.reason] || selectedDeletion.reason}</p>
                                                </div>
                                                <div style={{ flex: 1, padding: '1.25rem' }}>
                                                    <p style={{ fontSize: '0.65rem', fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.25rem' }}>Submitted</p>
                                                    <p style={{ fontSize: '0.95rem', fontWeight: 700, color: '#334155', margin: 0 }}>
                                                        {selectedDeletion.createdAt?.toDate?.()?.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) || 'N/A'}
                                                    </p>
                                                </div>
                                            </div>
                                            <div style={{ padding: '1.25rem' }}>
                                                <p style={{ fontSize: '0.65rem', fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.5rem' }}>Student Comments</p>
                                                <p style={{ fontSize: '0.85rem', color: '#64748b', fontStyle: 'italic', margin: 0, padding: '1rem', background: '#f8fafc', borderRadius: '0.25rem', border: '1px solid #f1f5f9' }}>
                                                    "{selectedDeletion.comments || 'No comments provided.'}"
                                                </p>
                                            </div>
                                        </div>

                                        {/* Impact Assessment Card */}
                                        <div style={{ background: '#fef2f2', border: '1px solid #fecaca', borderRadius: '0.5rem', padding: '1.25rem' }}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem' }}>
                                                <AlertTriangle size={18} color="#ef4444" />
                                                <h3 style={{ fontSize: '0.9rem', fontWeight: 600, color: '#dc2626', margin: 0 }}>Impact Assessment</h3>
                                            </div>
                                            <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                                                <li style={{ display: 'flex', alignItems: 'flex-start', gap: '0.5rem', fontSize: '0.8rem', color: '#334155' }}>
                                                    <CheckCircle size={14} color="#ef4444" style={{ marginTop: 2, flexShrink: 0 }} />
                                                    Access to portal will be permanently revoked.
                                                </li>
                                                <li style={{ display: 'flex', alignItems: 'flex-start', gap: '0.5rem', fontSize: '0.8rem', color: '#334155' }}>
                                                    <CheckCircle size={14} color="#ef4444" style={{ marginTop: 2, flexShrink: 0 }} />
                                                    All academic history will be archived but inaccessible to the student.
                                                </li>
                                                <li style={{ display: 'flex', alignItems: 'flex-start', gap: '0.5rem', fontSize: '0.8rem', color: '#334155' }}>
                                                    <CheckCircle size={14} color="#ef4444" style={{ marginTop: 2, flexShrink: 0 }} />
                                                    Linked email alias will be decommissioned.
                                                </li>
                                            </ul>
                                        </div>

                                    </div>

                                    {/* RIGHT COLUMN */}
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                                        
                                        {/* Status Track */}
                                        <div style={{ background: '#ffffff', borderRadius: '0.5rem', border: '1px solid #e2e8f0', padding: '1.25rem' }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
                                                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                                                    <div style={{ background: '#eff6ff', padding: '0.5rem', borderRadius: '0.5rem' }}>
                                                        <BarChart2 size={18} color="#3b82f6" />
                                                    </div>
                                                    <div>
                                                        <h3 style={{ fontSize: '0.9rem', fontWeight: 600, color: '#1e293b', margin: 0 }}>Status Track</h3>
                                                        <p style={{ fontSize: '0.65rem', color: '#94a3b8', margin: 0 }}>Lifecycle monitoring</p>
                                                    </div>
                                                </div>
                                                <span style={{ fontSize: '0.65rem', fontWeight: 700, color: '#16a34a', background: '#dcfce7', padding: '0.2rem 0.5rem', borderRadius: '1rem' }}>Step {selectedDeletion.progressStep || 1}/11</span>
                                            </div>

                                            {/* Timeline Visual */}
                                            <div style={{ maxHeight: '350px', overflowY: 'auto', paddingRight: '0.5rem' }}>
                                                <div style={{ position: 'relative', paddingLeft: '0.5rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                                                    <div style={{ position: 'absolute', left: '0.8rem', top: '0.5rem', bottom: '1.5rem', width: 2, background: '#e2e8f0', zIndex: 0 }}></div>
                                                    
                                                    {[
                                                    { step: 1, label: 'Submitted', desc: 'Request received' },
                                                    { step: 2, label: 'Received', desc: 'System acknowledged' },
                                                    { step: 3, label: 'Verification', desc: 'Checking details' },
                                                    { step: 4, label: 'Under Review', desc: 'Admin assessing' },
                                                    { step: 5, label: 'Data Assessment', desc: 'Identifying data' },
                                                    { step: 6, label: 'Awaiting Decision', desc: 'Pending approval' },
                                                    { step: 7, label: 'Approved/Rejected', desc: 'Decision made' },
                                                    { step: 8, label: 'Processing', desc: 'Executing deletion' },
                                                    { step: 9, label: 'Authentication Removed', desc: 'Access revoked' },
                                                    { step: 10, label: 'User Notified', desc: 'Confirmation sent' },
                                                    { step: 11, label: 'Completed', desc: 'Fully resolved' }
                                                ].map((item, index) => {
                                                    const currentStep = selectedDeletion.progressStep || 1;
                                                    const isCompleted = item.step < currentStep;
                                                    const isCurrent = item.step === currentStep;
                                                    const isPending = item.step > currentStep;
                                                    
                                                    let circleColor = '#e2e8f0';
                                                    let outlineColor = '#cbd5e1';
                                                    if (isCompleted) {
                                                        circleColor = '#16a34a';
                                                        outlineColor = '#16a34a';
                                                    } else if (isCurrent) {
                                                        circleColor = '#16a34a';
                                                        outlineColor = '#86efac';
                                                    }

                                                    return (
                                                        <div key={item.step} style={{ display: 'flex', gap: '1rem', position: 'relative', zIndex: 1, opacity: isPending ? 0.4 : 1, paddingBottom: index === 10 ? 0 : '0.25rem' }}>
                                                            <div style={{ width: 12, height: 12, borderRadius: '50%', background: circleColor, border: '2px solid #ffffff', outline: `2px solid ${outlineColor}`, marginTop: 2, flexShrink: 0 }}></div>
                                                            <div>
                                                                <p style={{ fontSize: '0.8rem', fontWeight: 700, color: '#1e293b', margin: 0 }}>{item.label}</p>
                                                                <p style={{ fontSize: '0.7rem', color: '#64748b', margin: 0 }}>
                                                                    {item.step === 1 ? (selectedDeletion.createdAt?.toDate?.()?.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) || 'N/A') : item.desc}
                                                                </p>
                                                            </div>
                                                        </div>
                                                    );
                                                })}
                                                </div>
                                            </div>
                                        </div>

                                        {/* Update Progress Dropdown */}
                                        <div style={{ background: '#ffffff', borderRadius: '0.5rem', border: '1px solid #e2e8f0', padding: '1.25rem' }}>
                                            <label style={{ display: 'block', fontSize: '0.7rem', fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.75rem' }}>Update Step Progress</label>
                                            <div style={{ position: 'relative' }}>
                                                <select 
                                                    value={selectedDeletion.progressStep || 1} 
                                                    onChange={(e) => handleUpdateProgress(Number(e.target.value))}
                                                    disabled={isDeletionProcessing}
                                                    style={{ 
                                                        width: '100%', 
                                                        padding: '0.75rem 1rem', 
                                                        borderRadius: '0.375rem', 
                                                        border: '1px solid #cbd5e1', 
                                                        backgroundColor: '#f8fafc', 
                                                        color: '#334155', 
                                                        fontSize: '0.875rem',
                                                        fontWeight: 600,
                                                        appearance: 'none',
                                                        outline: 'none',
                                                        cursor: isDeletionProcessing ? 'not-allowed' : 'pointer',
                                                        opacity: isDeletionProcessing ? 0.6 : 1
                                                    }}
                                                >
                                                    <option value={1}>1. Submitted</option>
                                                    <option value={2}>2. Received</option>
                                                    <option value={3}>3. Verification</option>
                                                    <option value={4}>4. Under Review</option>
                                                    <option value={5}>5. Data Assessment</option>
                                                    <option value={6}>6. Awaiting Decision</option>
                                                    <option value={7}>7. Approved/Rejected</option>
                                                    <option value={8}>8. Processing</option>
                                                    <option value={9}>9. Authentication Removed</option>
                                                    <option value={10}>10. User Notified</option>
                                                    <option value={11}>11. Completed</option>
                                                </select>
                                                <div style={{ position: 'absolute', right: '1rem', top: '50%', transform: 'translateY(-50%)', pointerEvents: 'none', color: '#64748b' }}>
                                                    <ChevronDown size={16} />
                                                </div>
                                            </div>
                                        </div>

                                        {/* Action Buttons */}
                                        {selectedDeletion.status === 'pending' && (
                                            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                                                <button
                                                    onClick={() => setShowApproveModal(true)}
                                                    disabled={isDeletionProcessing}
                                                    style={{ width: '100%', padding: '0.875rem', borderRadius: '0.5rem', background: 'linear-gradient(to bottom, #dc2626, #b91c1c)', color: 'white', border: '1px solid #991b1b', fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', fontSize: '0.9rem', boxShadow: '0 2px 4px rgba(220,38,38,0.2)' }}
                                                >
                                                    <CheckSquare size={16} /> Approve Deletion
                                                </button>
                                                <button
                                                    onClick={() => setShowRejectModal(true)}
                                                    disabled={isDeletionProcessing}
                                                    style={{ width: '100%', padding: '0.875rem', borderRadius: '0.5rem', background: '#ffffff', color: '#475569', border: '1px solid #cbd5e1', fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', fontSize: '0.9rem', boxShadow: '0 1px 2px rgba(0,0,0,0.05)' }}
                                                >
                                                    <XCircle size={16} /> Reject Request
                                                </button>
                                            </div>
                                        )}

                                        {/* Info Footer */}
                                        <div style={{ marginTop: '0.5rem', background: '#f1f5f9', borderRadius: '0.5rem', padding: '1rem', display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.7rem', fontWeight: 600, color: '#64748b' }}>
                                                <span>Request ID</span>
                                                <span style={{ color: '#3b82f6' }}>#DEL-{selectedDeletion.id.slice(0, 5).toUpperCase()}</span>
                                            </div>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.7rem', fontWeight: 600, color: '#64748b' }}>
                                                <span>Wait Time</span>
                                                <span style={{ color: '#1e293b' }}>2 hours</span>
                                            </div>
                                        </div>

                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="flex flex-col items-center justify-center h-full text-slate-400 p-12 text-center">
                                <UserX size={48} className="mb-4 opacity-40" />
                                <h3 className="text-lg font-bold text-slate-600 mb-2">Request Not Found</h3>
                            </div>
                        )}
                    </div>
                    )}
                </div>
            ) : (
            <div className="complaints-mgmt-layout full-width-mode">
                {!selectedId ? (
                <div className="complaints-sidebar section-card flex flex-col w-full h-full">
                    <div className="sidebar-tabs-container">
                        <button
                            className={`sidebar-tab ${activeTab === 'new' ? 'active' : ''}`}
                            onClick={() => {
                                setActiveTab('new');
                                setFilter('all');
                            }}
                        >
                            <span className="tab-label">New Complaints</span>
                            {newCount > 0 && <span className="tab-badge">{newCount}</span>}
                        </button>
                        <button
                            className={`sidebar-tab ${activeTab === 'history' ? 'active' : ''}`}
                            onClick={() => {
                                setActiveTab('history');
                                setFilter('all');
                            }}
                        >
                            <span className="tab-label">History</span>
                            {historyCount > 0 && <span className="tab-badge history">{historyCount}</span>}
                        </button>
                    </div>

                    <div className="flex items-center justify-between border-b" style={{ padding: '1rem 1.5rem 0.5rem 1.5rem' }}>
                        <h2 className="text-sm font-bold text-slate-500 uppercase tracking-wider">
                            {activeTab === 'new' ? 'Active Tickets' : 'Resolved Archive'}
                        </h2>
                        <div className="flex items-center gap-2">
                            {/* Search Bar */}
                            <div className={`admin-search-box ${searchQuery ? 'has-value' : ''}`}>
                                <Search size={14} className="search-icon" />
                                <input
                                    type="text"
                                    placeholder="Search ID/Name..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="admin-search-input"
                                />
                                {searchQuery && (
                                    <button className="clear-search" onClick={() => setSearchQuery('')}>×</button>
                                )}
                            </div>

                            {activeTab === 'new' && (
                                <div className="admin-filter-wrapper" ref={filterDropdownRef}>
                                    <button
                                        className={`admin-filter-trigger compact ${isFilterOpen ? 'active' : ''}`}
                                        onClick={() => setIsFilterOpen(!isFilterOpen)}
                                    >
                                        <Filter size={12} className="text-slate-400" />
                                        <span className="capitalize text-xs">{filter}</span>
                                        <ChevronDown size={12} className={`trigger-chevron ${isFilterOpen ? 'rotate' : ''}`} />
                                    </button>

                                    {isFilterOpen && (
                                        <div className="admin-filter-options animate-scale-up">
                                            {[
                                                { id: 'all', label: 'All Active', icon: <MessageSquare size={14} /> },
                                                { id: 'pending', label: 'Pending Only', icon: <AlertCircle size={14} className="text-amber-500" /> },
                                                { id: 'in-progress', label: 'In Progress', icon: <Clock size={14} className="text-blue-500" /> }
                                            ].map((opt) => (
                                                <button
                                                    key={opt.id}
                                                    className={`admin-filter-opt ${filter === opt.id ? 'active' : ''}`}
                                                    onClick={() => {
                                                        setFilter(opt.id);
                                                        setIsFilterOpen(false);
                                                    }}
                                                >
                                                    <span className="opt-icon">{opt.icon}</span>
                                                    <span className="opt-label">{opt.label}</span>
                                                    {filter === opt.id && <div className="active-dot" />}
                                                </button>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Category Filters */}
                    <div className="admin-category-filters overflow-x-auto whitespace-nowrap px-4 py-3 border-b flex gap-2 hide-scrollbar">
                        <button
                            className={`admin-cat-pill ${categoryFilter === 'all' ? 'active' : ''}`}
                            onClick={() => setCategoryFilter('all')}
                        >
                            All
                        </button>
                        {['Academic', 'Hostel', 'Mess', 'Transport', 'WiFi/Network', 'Facilities', 'Examination', 'Other'].map(cat => (
                            <button
                                key={cat}
                                className={`admin-cat-pill ${categoryFilter.toLowerCase() === cat.toLowerCase() ? 'active' : ''}`}
                                onClick={() => setCategoryFilter(cat.toLowerCase())}
                            >
                                {cat}
                            </button>
                        ))}
                        <button
                            className={`admin-cat-pill follow-up ${categoryFilter === 'follow-up' ? 'active' : ''}`}
                            onClick={() => setCategoryFilter('follow-up')}
                        >
                            Follow-ups
                        </button>
                    </div>

                    <div className="complaints-mgmt-list">
                        {filteredComplaints.length === 0 ? (
                                <div style={{ padding: '4rem 2rem', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', color: '#64748b', height: '100%', flex: 1, textAlign: 'center' }}>
                                    <div style={{ background: '#f1f5f9', padding: '1.25rem', borderRadius: '50%', marginBottom: '1rem' }}>
                                        <MessageSquare size={48} color="#94a3b8" />
                                    </div>
                                    <h3 style={{ fontSize: '1.1rem', fontWeight: 600, color: '#334155', marginBottom: '0.25rem' }}>No Complaints</h3>
                                    <p style={{ fontSize: '0.85rem', color: '#64748b' }}>There are no {categoryFilter === 'all' ? '' : `${categoryFilter} `}complaints matching your filters.</p>
                                </div>
                        ) : (
                            filteredComplaints.map(c => (
                                <div
                                    key={c.id}
                                    className={`cm-premium-card ${selectedId === c.id ? 'active' : ''} bg-grad-${(c.category || 'other').toLowerCase().replace(/[^a-z0-9]/g, '-')}`}
                                    onClick={() => {
                                        setSelectedId(c.id);
                                        setAdminReply('');
                                    }}
                                >
                                    {/* Main Content Area: 2 Columns */}
                                    <div className="cm-card-content">
                                        
                                        {/* Left Column: Info */}
                                        <div className="cm-card-left">
                                            <div className="cm-card-header">
                                                <div className="cm-icon-container">
                                                    <MessageSquare size={14} className="cm-main-icon" />
                                                </div>
                                                <span className="cm-id-label">{getFormattedId(c)}</span>
                                            </div>
                                            
                                            <h3 className="cm-title truncate">{c.subject}</h3>
                                            
                                            <div className="cm-meta-row">
                                                <span className="cm-meta-item">
                                                    <User size={12} className="cm-meta-icon" />
                                                    <span className="truncate max-w-[100px]">{c.studentName}</span>
                                                </span>
                                                <span className="cm-meta-divider">•</span>
                                                <span className="cm-meta-item">
                                                    <Clock size={12} className="cm-meta-icon" />
                                                    <span>{c.createdAt?.toDate()?.toLocaleDateString([], { month: 'short', day: 'numeric' }) || 'Recent'}</span>
                                                </span>
                                                {c.priority && (
                                                    <>
                                                        <span className="cm-meta-divider">•</span>
                                                        <span className={`cm-priority-pill ${c.priority.toLowerCase()}`}>
                                                            {c.priority}
                                                        </span>
                                                    </>
                                                )}
                                            </div>
                                        </div>

                                        {/* Right Column: Status & Actions */}
                                        <div className="cm-card-right flex flex-col items-end gap-2">
                                            <span className={`cm-status-badge ${c.status}`}>
                                                <div className="cm-status-glow" />
                                                {c.status === 'in-progress' ? 'In Progress' : c.status === 'under_review' ? 'Under Review' : c.status}
                                            </span>
                                            {c.followUpEnquiry && c.followUpEnquiry.isActive && (
                                                <span className="text-[9px] font-bold uppercase tracking-wider text-amber-600 bg-amber-100 px-2 py-0.5 rounded-full border border-amber-200">
                                                    Follow-up
                                                </span>
                                            )}
                                            
                                            <button
                                                className="cm-delete-btn"
                                                onClick={(e) => handleDeleteClick(e, c.id)}
                                                title="Delete Complaint"
                                            >
                                                <Trash2 size={14} />
                                            </button>
                                        </div>
                                    </div>

                                    {/* Bottom: Progress Indicator */}
                                    <div className="cm-progress-bar-container">
                                        <div 
                                            className={`cm-progress-fill ${c.status}`} 
                                            style={{ 
                                                width: c.status === 'resolved' ? '100%' : 
                                                       c.status === 'in-progress' ? '75%' : 
                                                       (c.status === 'under_review' || c.status === 'assigned') ? '50%' : '25%' 
                                            }}
                                        />
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
                ) : (
                <div className="complaint-detail-container section-card no-padding flex flex-col h-full overflow-hidden relative w-full animate-slide-in">
                    {isDetailLoading ? (
                        <div className="p-8 flex flex-col space-y-8 h-full">
                            <div className="flex justify-between items-start">
                                <div className="space-y-3 w-1/2">
                                    <div className="h-8 skeleton w-full rounded-xl"></div>
                                    <div className="h-4 skeleton w-3/4 rounded-md"></div>
                                </div>
                                <div className="flex gap-2">
                                    <div className="h-10 skeleton w-20 rounded-xl"></div>
                                    <div className="h-10 skeleton w-20 rounded-xl"></div>
                                    <div className="h-10 skeleton w-20 rounded-xl"></div>
                                </div>
                            </div>
                            <div className="flex-1 space-y-6 overflow-hidden">
                                <div className="h-20 skeleton w-2/3 rounded-2xl opacity-60"></div>
                                <div className="h-16 skeleton w-3/4 rounded-2xl ml-auto opacity-40"></div>
                                <div className="h-24 skeleton w-1/2 rounded-2xl opacity-50"></div>
                                <div className="h-20 skeleton w-2/3 rounded-2xl ml-auto opacity-30"></div>
                            </div>
                        </div>
                    ) : selectedComplaint ? (
                        <>
                            {/* Header - Fixed at Top */}
                            <div className="complaint-detail-header p-6 z-10 relative">
                                <div className="flex items-center mb-2" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '0.5rem' }}>
                                    <button 
                                        onClick={() => { setSelectedId(null); setSelectedComplaint(null); }}
                                        className="flex items-center justify-center p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-slate-500 hover:text-slate-800 dark:hover:text-slate-200"
                                    >
                                        <ArrowLeft size={20} />
                                    </button>
                                    <h2 className="text-2xl font-extrabold text-[#1e293b] tracking-tight truncate mb-1" title={selectedComplaint.subject}>{selectedComplaint.subject}</h2>
                                </div>
                                <div className="flex justify-between items-start" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                    <div className="min-w-0 flex-1 mr-4 ml-10">
                                        <div className="complaint-metadata-bar">
                                            <span className="detail-metadata-pill highlight">
                                                <User size={14} />
                                                {selectedComplaint.studentName}
                                            </span>
                                            <span className="detail-metadata-pill">
                                                <Clock size={12} />
                                                {selectedComplaint.createdAt?.toDate()?.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }) || 'Recently'}
                                            </span>
                                            <span className="detail-metadata-pill id-pill">
                                                {getFormattedId(selectedComplaint)}
                                            </span>
                                            <span className="detail-metadata-pill" style={{ textTransform: 'uppercase', fontSize: '0.7rem', fontWeight: 800 }}>
                                                {selectedComplaint.category || 'N/A'}
                                            </span>
                                            {selectedComplaint.priority && (
                                                <span className={`detail-metadata-pill ${
                                                    selectedComplaint.priority.toLowerCase() === 'high' ? 'priority-high' :
                                                    selectedComplaint.priority.toLowerCase() === 'medium' ? 'priority-medium' :
                                                    'priority-low'
                                                }`} style={{ textTransform: 'uppercase', fontSize: '0.7rem', fontWeight: 800 }}>
                                                    {selectedComplaint.priority} Priority
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                    <div className="flex gap-2 flex-shrink-0">
                                        <button 
                                            onClick={() => setShowUpdateStatusModal(true)}
                                            className="admin-update-status-btn"
                                        >
                                            <Settings size={16} className="mr-1.5" />
                                            Update Status
                                        </button>
                                        {selectedComplaint.category === 'activation' && selectedComplaint.status !== 'resolved' && (
                                            <button
                                                onClick={() => handleActivateAccount(selectedComplaint)}
                                                disabled={isUpdating}
                                                className="status-btn resolved active"
                                                style={{ background: 'linear-gradient(135deg, #10b981 0%, #059669 100%)', color: 'white', border: 'none' }}
                                            >
                                                Approve & Activate
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div className="complaint-chat-history flex-1 overflow-y-auto p-6" ref={chatContainerRef}>
                                {/* Admin Advanced Controls Modal Trigger is in Header now */}


                                {(selectedComplaint.messages || []).map((msg, idx) => {
                                    if (msg.type === 'resolution') {
                                        return (
                                            <div key={`res-${idx}`} className="resolution-message-container">
                                                <div className="resolution-animation-wrapper">
                                                    <div className="checkmark-circle small">
                                                        <svg className="checkmark-svg" viewBox="0 0 52 52">
                                                            <circle className="checkmark-circle-stroke" cx="26" cy="26" r="25" fill="none" />
                                                            <path className="checkmark-check" fill="none" d="M14.1 27.2l7.1 7.2 16.7-16.8" />
                                                        </svg>
                                                    </div>
                                                </div>
                                                <p className="resolution-message-text">Complaint Resolved / Closed</p>
                                                <span className="resolution-time">{msg.createdAt ? new Date(msg.createdAt).toLocaleString() : ''}</span>
                                            </div>
                                        );
                                    }
                                    return (
                                        <div key={`msg-${idx}`} className={`chat-bubble ${msg.senderRole}`}>
                                            <div className="chat-bubble-info">
                                                <span className="sender">{msg.senderRole === 'admin' ? 'You' : msg.senderName}</span>
                                                <span className="time">{msg.createdAt ? new Date(msg.createdAt).toLocaleString() : ''}</span>
                                            </div>
                                            <p className="chat-text">{msg.text}</p>
                                        </div>
                                    );
                                })}
                                
                                {/* Follow-up Thread Rendering */}
                                {selectedComplaint.followUpEnquiry && selectedComplaint.followUpEnquiry.messages && (
                                    <>
                                        <div className="flex items-center my-6">
                                            <div className="flex-1 border-t border-slate-200 dark:border-slate-700"></div>
                                            <span className="px-4 text-xs font-bold uppercase text-amber-600 bg-amber-50 rounded-full py-1 border border-amber-200">
                                                Follow-up Enquiry: {selectedComplaint.followUpEnquiry.subject}
                                            </span>
                                            <div className="flex-1 border-t border-slate-200 dark:border-slate-700"></div>
                                        </div>
                                        {selectedComplaint.followUpEnquiry.messages.map((msg, idx) => (
                                            <div key={`fu-${idx}`} className={`chat-bubble ${msg.senderRole}`}>
                                                <div className="chat-bubble-info">
                                                    <span className="sender">{msg.senderRole === 'admin' ? 'You' : msg.senderName}</span>
                                                    <span className="time">{msg.createdAt ? new Date(msg.createdAt).toLocaleString() : ''}</span>
                                                </div>
                                                <p className="chat-text">{msg.text}</p>
                                            </div>
                                        ))}
                                    </>
                                )}
                                <div ref={messagesEndRef} />
                            </div>

                            {/* Reply Box - Fixed at Bottom of Flex Container */}
                            <div className="complaint-detail-footer p-5 z-10 relative">
                                <div className={`response-box-wrapper-single ${isFocused ? 'focused' : ''}`}>
                                    <input
                                        type="text"
                                        className="single-line-reply-input"
                                        placeholder="Type your reply..."
                                        value={adminReply}
                                        onChange={(e) => setAdminReply(e.target.value)}
                                        onFocus={() => setIsFocused(true)}
                                        onBlur={() => setIsFocused(false)}
                                        onKeyPress={(e) => e.key === 'Enter' && handleSendReply()}
                                    />
                                    <button
                                        className="send-reply-btn"
                                        onClick={handleSendReply}
                                        disabled={isUpdating || !adminReply.trim()}
                                        title="Send Reply"
                                    >
                                        <Send size={20} />
                                    </button>
                                </div>
                            </div>
                        </>
                    ) : (
                        <div className="flex flex-col items-center justify-center h-full text-slate-400 p-12 text-center animate-fade-in">
                            <div className="empty-chat-icon-wrapper">
                                <MessageSquare size={48} className="mb-4 opacity-40" />
                            </div>
                            <h3 className="text-lg font-bold text-slate-600 mb-2">No Ticket Selected</h3>
                            <p className="max-w-xs text-sm text-slate-400">Select a complaint from the sidebar to view the discussion thread and respond.</p>
                        </div>
                    )}
                </div>
                )}
            </div>
            )}

            {/* ===== APPROVE DELETION MODAL ===== */}
            {showApproveModal && createPortal(
                <div className="delete-modal-overlay animate-fade-in" onClick={() => setShowApproveModal(false)}>
                    <div className="delete-modal-content animate-scale-up" onClick={e => e.stopPropagation()}>
                        <div className="delete-modal-icon" style={{ background: 'rgba(239,68,68,0.1)', borderRadius: '50%', width: 64, height: 64, display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1rem' }}>
                            <UserX size={32} color="#ef4444" />
                        </div>
                        <h3 style={{ color: '#ef4444', marginBottom: '0.5rem' }}>Approve Account Deletion?</h3>
                        <p style={{ marginBottom: '1.5rem', lineHeight: 1.5 }}>
                            This will <strong>permanently delete</strong> the Firestore data for <strong>{selectedDeletion?.studentName}</strong> ({selectedDeletion?.studentEmail}). The student will lose access to the platform. This action <strong>cannot be undone</strong>.
                        </p>
                        <div className="delete-modal-actions">
                            <button onClick={() => setShowApproveModal(false)} className="btn-cancel" disabled={isDeletionProcessing}>Cancel</button>
                            <button
                                onClick={handleApproveDeletion}
                                className="btn-delete"
                                disabled={isDeletionProcessing}
                                style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}
                            >
                                {isDeletionProcessing ? <RefreshCw size={16} className="animate-spin" /> : <UserX size={16} />}
                                {isDeletionProcessing ? 'Processing...' : 'Yes, Delete Account'}
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* ===== REJECT DELETION MODAL ===== */}
            {showRejectModal && createPortal(
                <div className="delete-modal-overlay animate-fade-in" onClick={() => { setShowRejectModal(false); setRejectNote(''); }}>
                    <div className="delete-modal-content animate-scale-up" onClick={e => e.stopPropagation()} style={{ maxWidth: 420 }}>
                        <div className="delete-modal-icon" style={{ background: 'rgba(100,116,139,0.1)', borderRadius: '50%', width: 64, height: 64, display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1rem' }}>
                            <ShieldX size={32} color="#64748b" />
                        </div>
                        <h3 style={{ marginBottom: '0.5rem' }}>Reject Deletion Request?</h3>
                        <p style={{ marginBottom: '1rem', lineHeight: 1.5, color: 'var(--color-text-muted)', fontSize: '0.875rem' }}>
                            The request will be marked as rejected and the student will retain their account.
                        </p>
                        <textarea
                            placeholder="Optional: Reason for rejection (visible to student)"
                            value={rejectNote}
                            onChange={e => setRejectNote(e.target.value)}
                            maxLength={300}
                            style={{ width: '100%', height: 90, padding: '0.75rem', borderRadius: '0.75rem', border: '1px solid var(--color-border)', background: 'var(--color-background)', color: 'var(--color-text-main)', fontFamily: 'inherit', fontSize: '0.875rem', resize: 'none', outline: 'none', marginBottom: '1.25rem', boxSizing: 'border-box' }}
                        />
                        <div className="delete-modal-actions">
                            <button onClick={() => { setShowRejectModal(false); setRejectNote(''); }} className="btn-cancel" disabled={isDeletionProcessing}>Cancel</button>
                            <button
                                onClick={handleRejectDeletion}
                                disabled={isDeletionProcessing}
                                style={{ flex: 1, padding: '0.75rem', borderRadius: '0.75rem', background: 'linear-gradient(135deg,#64748b,#475569)', color: 'white', border: 'none', fontWeight: 700, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem' }}
                            >
                                {isDeletionProcessing ? <RefreshCw size={16} className="animate-spin" /> : <ShieldX size={16} />}
                                {isDeletionProcessing ? 'Processing...' : 'Reject Request'}
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* Update Status Modal */}
            {showUpdateStatusModal && createPortal(
                <div className="fixed inset-0 flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm animate-[fadeIn_0.2s_ease-out]" style={{ zIndex: 999999, position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(15, 23, 42, 0.5)', backdropFilter: 'blur(4px)' }}>
                    <div 
                        className="admin-premium-controls-card m-0 w-full overflow-y-auto shadow-2xl relative animate-[slideUp_0.3s_ease-out]"
                        style={{ maxWidth: '600px', maxHeight: '90vh' }}
                    >
                        <div className="admin-controls-header flex justify-between items-start mb-6">
                            <div className="flex items-center gap-4">
                                <div className="admin-controls-icon-bg flex-shrink-0">
                                    <Settings size={22} className="text-indigo-500 animate-[spin_4s_linear_infinite]" />
                                </div>
                                <div>
                                    <h3 className="admin-controls-title">Complaint Configuration</h3>
                                    <p className="admin-controls-subtitle">Real-time sync with student timeline</p>
                                </div>
                            </div>
                            <button 
                                onClick={() => setShowUpdateStatusModal(false)}
                                className="admin-close-btn"
                            >
                                <span className="text-2xl leading-none">&times;</span>
                            </button>
                        </div>
                        
                        <div className="admin-controls-grid">
                            <div className="admin-input-group">
                                <label>Timeline Status</label>
                                <div className="admin-select-wrapper">
                                    <select 
                                        className="admin-premium-input cursor-pointer"
                                        value={editStatus}
                                        onChange={(e) => setEditStatus(e.target.value)}
                                    >
                                        <option value="pending">Submitted</option>
                                        <option value="viewed">Viewed by Admin</option>
                                        <option value="under_review">Under Review</option>
                                        <option value="in-progress">In Progress</option>
                                        <option value="resolved">Resolved</option>
                                        <option value="closed">Closed</option>
                                    </select>
                                    <ChevronDown size={16} className="admin-select-icon" />
                                </div>
                            </div>

                            <div className="admin-input-group">
                                <label>Estimated Resolution (ETA)</label>
                                <input 
                                    type="datetime-local" 
                                    className="admin-premium-input cursor-pointer"
                                    value={editEta}
                                    onChange={(e) => setEditEta(e.target.value)}
                                />
                            </div>

                            <div className="admin-input-group">
                                <label>Priority</label>
                                <div className="admin-select-wrapper">
                                    <select 
                                        className="admin-premium-input cursor-pointer"
                                        value={editPriority}
                                        onChange={(e) => setEditPriority(e.target.value)}
                                    >
                                        <option value="High">High Priority</option>
                                        <option value="Medium">Medium Priority</option>
                                        <option value="Low">Low Priority</option>
                                    </select>
                                    <ChevronDown size={16} className="admin-select-icon" />
                                </div>
                            </div>

                            <div className="admin-input-group">
                                <label>Category</label>
                                <div className="admin-select-wrapper">
                                    <select 
                                        className="admin-premium-input cursor-pointer"
                                        value={editCategory}
                                        onChange={(e) => setEditCategory(e.target.value)}
                                    >
                                        <option value="academic">Academic & Classes</option>
                                        <option value="facilities">Facilities & Infrastructure</option>
                                        <option value="hostel">Hostel & Accommodation</option>
                                        <option value="mess">Mess & Food</option>
                                        <option value="it">IT & Network</option>
                                        <option value="administration">Administration</option>
                                        <option value="other">Other</option>
                                    </select>
                                    <ChevronDown size={16} className="admin-select-icon" />
                                </div>
                            </div>

                            <div className="admin-input-group">
                                <label>Assignee Name</label>
                                <input 
                                    type="text" 
                                    placeholder="e.g. Mr. Arjun Sharma"
                                    className="admin-premium-input"
                                    value={editAssigneeName}
                                    onChange={(e) => setEditAssigneeName(e.target.value)}
                                />
                            </div>

                            <div className="admin-input-group">
                                <label>Assignee Role</label>
                                <input 
                                    type="text" 
                                    placeholder="e.g. Network Administrator"
                                    className="admin-premium-input"
                                    value={editAssigneeRole}
                                    onChange={(e) => setEditAssigneeRole(e.target.value)}
                                />
                            </div>
                        </div>
                        
                        <div className="admin-controls-footer">
                            <button 
                                onClick={() => setShowUpdateStatusModal(false)}
                                className="admin-premium-cancel-btn"
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={() => {
                                    handleSaveControls();
                                    setShowUpdateStatusModal(false);
                                }}
                                disabled={isUpdating}
                                className="admin-premium-save-btn flex items-center gap-2"
                            >
                                {isUpdating ? <RefreshCw size={16} className="animate-spin" /> : <CheckCircle size={16} strokeWidth={2.5} />}
                                {isUpdating ? 'Synchronizing...' : 'Save & Publish Timeline'}
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* Resolution Confirmation Modal */}
            {showResolveModal && (
                <div className="resolve-modal-overlay">
                    <div className="resolve-modal-content">
                        <div className="resolve-modal-header">
                            <AlertCircle size={24} />
                            <h3>Mark as Resolved?</h3>
                        </div>
                        <p className="resolve-modal-text">
                            Are you sure you want to mark this complaint as resolved? This will signal to the student that the issue has been addressed.
                        </p>
                        <div className="resolve-modal-actions">
                            <button
                                onClick={() => setShowResolveModal(false)}
                                className="btn-cancel"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={() => {
                                    handleUpdateStatus(selectedComplaint.id, 'resolved');
                                    setShowResolveModal(false);
                                }}
                                className="btn-confirm-resolve"
                            >
                                Yes, Resolve
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Success Animation Modal */}
            {showSuccessModal && (
                <div className="success-modal-overlay">
                    <div className="success-modal-content">
                        <div className="success-animation-container">
                            <div className="checkmark-circle">
                                <svg className="checkmark-svg" viewBox="0 0 52 52">
                                    <circle className="checkmark-circle-stroke" cx="26" cy="26" r="25" fill="none" />
                                    <path className="checkmark-check" fill="none" d="M14.1 27.2l7.1 7.2 16.7-16.8" />
                                </svg>
                            </div>
                            <h3 className="success-text">Resolved!</h3>
                            <p className="success-subtext">Complaint has been marked as resolved.</p>
                        </div>
                    </div>
                </div>
            )}

            {/* Delete Confirmation Modal */}
            {showDeleteModal && createPortal(
                <div className="delete-modal-overlay animate-fade-in">
                    <div className="delete-modal-content animate-scale-up">
                        <div className="delete-modal-icon">
                            <Trash2 size={32} className="text-red-500 animate-bounce-short" />
                        </div>
                        <h3>Delete Complaint?</h3>
                        <p>This will permanently remove the complaint and all its messages. This action cannot be undone.</p>
                        <div className="delete-modal-actions">
                            <button
                                onClick={() => setShowDeleteModal(false)}
                                className="btn-cancel"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={confirmDelete}
                                className="btn-delete"
                            >
                                <Trash2 size={18} />
                                Delete Permanently
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* Delete Success Animation */}
            {showDeleteSuccess && createPortal(
                <div className="delete-modal-overlay success-red-theme animate-fade-in">
                    <div className="delete-modal-content success-red-theme">
                        <div className="delete-modal-icon icon-red-bg">
                            <Trash2 size={40} className="text-red-600 animate-bounce-short" />
                        </div>
                        <h3 className="text-red-700">Deleted!</h3>
                        <p className="text-red-600 mb-0">The complaint has been permanently removed.</p>
                    </div>
                </div>,
                document.body
            )}
        </div >
    );
};

export default ComplaintsManagement;

import React, { useState, useEffect } from 'react';
import LoadingTransition from '../../components/Common/LoadingTransition';
import { useAuth } from '../../context/AuthContext';
import { db } from '../../config/firebase';
import { collection, addDoc, getDocs, deleteDoc, doc, updateDoc, query, orderBy } from 'firebase/firestore';
import { Plus, Trash2, Edit2, ExternalLink, Save, X } from 'lucide-react';
import './Admin.css'; // Reusing Admin styles

const ContentManagement = () => {
    const [links, setLinks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [isEditing, setIsEditing] = useState(false);
    const [currentId, setCurrentId] = useState(null);

    // Form State
    const [formData, setFormData] = useState({
        title: '',
        url: '',
        category: 'General',
        description: ''
    });

    const { user } = useAuth();
    const [adminUser, setAdminUser] = useState(null);

    const categories = ['General', 'Academic', 'Exam', 'Utility', 'External Resource'];

    useEffect(() => {
        const fetchAdminData = async () => {
            if (!user?.uid) return;
            const snapshot = await getDocs(collection(db, 'users'));
            const data = snapshot.docs.find(doc => doc.id === user.uid)?.data();
            setAdminUser(data);
        };
        fetchAdminData();
    }, [user]);


    useEffect(() => {
        fetchLinks();
    }, []);

    const fetchLinks = async () => {
        try {
            const q = query(collection(db, 'content_links'), orderBy('createdAt', 'desc'));
            const querySnapshot = await getDocs(q);
            const linksData = querySnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));
            setLinks(linksData);
        } catch (error) {
            console.error("Error fetching links:", error);
        } finally {
            setTimeout(() => {
                setLoading(false);
            }, 2000);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!formData.title || !formData.url) return;

        try {
            const linkData = {
                ...formData,
                updatedAt: new Date().toISOString()
            };

            if (isEditing && currentId) {
                await updateDoc(doc(db, 'content_links', currentId), linkData);
            } else {
                linkData.createdAt = new Date().toISOString();
                await addDoc(collection(db, 'content_links'), linkData);
            }

            // Reset Form and Refresh
            resetForm();
            fetchLinks();
        } catch (error) {
            console.error("Error saving link:", error);
            alert("Failed to save link. Please try again.");
        }
    };

    const handleDelete = async (id) => {
        if (window.confirm('Are you sure you want to delete this link?')) {
            try {
                await deleteDoc(doc(db, 'content_links', id));
                fetchLinks();
            } catch (error) {
                console.error("Error deleting link:", error);
            }
        }
    };

    const handleEdit = (link) => {
        setFormData({
            title: link.title,
            url: link.url,
            category: link.category || 'General',
            description: link.description || ''
        });
        setCurrentId(link.id);
        setIsEditing(true);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const resetForm = () => {
        setFormData({
            title: '',
            url: '',
            category: 'General',
            description: ''
        });
        setIsEditing(false);
        setCurrentId(null);
    };

    return (
        <div className="admin-container">
            <div className="page-header-v2">
                <div className="header-accent-bar"></div>
                <div className="header-content-v2">
                    <h1 className="page-title-v2">Resource Management</h1>
                    <p className="page-subtitle-v2">Manage quick links and external resources for student access.</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Form Section */}
                <div className="lg:col-span-1">
                    <div className="section-card p-6 bg-[var(--color-surface)] rounded-2xl border border-[var(--color-border)] sticky top-6">
                        <h2 className="text-lg font-semibold mb-4 text-[var(--color-text)]">
                            {isEditing ? 'Edit Link' : 'Add New Link'}
                        </h2>

                        <form onSubmit={handleSubmit} className="space-y-4" noValidate>
                            <div>
                                <label className="block text-sm font-medium text-[var(--color-text-muted)] mb-1">Title</label>
                                <input
                                    type="text"
                                    className="w-full p-2 rounded-lg border border-[var(--color-border)] bg-[var(--color-background)] text-[var(--color-text)]"
                                    placeholder="e.g. Exam Schedule"
                                    value={formData.title}
                                    onChange={e => setFormData({ ...formData, title: e.target.value })}
                                    required
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--color-text-muted)] mb-1">URL</label>
                                <input
                                    type="url"
                                    className="w-full p-2 rounded-lg border border-[var(--color-border)] bg-[var(--color-background)] text-[var(--color-text)]"
                                    placeholder="https://"
                                    value={formData.url}
                                    onChange={e => setFormData({ ...formData, url: e.target.value })}
                                    required
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--color-text-muted)] mb-1">Category</label>
                                <select
                                    className="w-full p-2 rounded-lg border border-[var(--color-border)] bg-[var(--color-background)] text-[var(--color-text)]"
                                    value={formData.category}
                                    onChange={e => setFormData({ ...formData, category: e.target.value })}
                                >
                                    {categories.map(cat => (
                                        <option key={cat} value={cat}>{cat}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--color-text-muted)] mb-1">Description (Optional)</label>
                                <textarea
                                    className="w-full p-2 rounded-lg border border-[var(--color-border)] bg-[var(--color-background)] text-[var(--color-text)]"
                                    rows="3"
                                    placeholder="Short description..."
                                    value={formData.description}
                                    onChange={e => setFormData({ ...formData, description: e.target.value })}
                                />
                            </div>

                            <div className="flex gap-2 pt-2">
                                <button
                                    type="submit"
                                    className="flex-1 bg-primary-600 hover:bg-primary-700 text-white py-2 px-4 rounded-lg flex items-center justify-center gap-2 transition-colors"
                                >
                                    {isEditing ? <Save size={18} /> : <Plus size={18} />}
                                    {isEditing ? 'Update Link' : 'Add Link'}
                                </button>
                                {isEditing && (
                                    <button
                                        type="button"
                                        onClick={resetForm}
                                        className="px-4 py-2 rounded-lg border border-red-200 text-red-600 hover:bg-red-50"
                                    >
                                        <X size={18} />
                                    </button>
                                )}
                            </div>
                        </form>
                    </div>
                </div>

                {/* List Section */}
                <div className="lg:col-span-2">
                    <div className="section-card p-6 bg-[var(--color-surface)] rounded-2xl border border-[var(--color-border)]">
                        <h2 className="text-lg font-semibold mb-4 text-[var(--color-text)]">Existing Links</h2>

                        {loading ? (
                            <LoadingTransition message="System Content Loading" persistent />
                        ) : links.length === 0 ? (
                            <div className="text-center py-8 text-[var(--color-text-muted)]">No links found. Add one to get started.</div>
                        ) : (
                            <div className="space-y-4">
                                {links.map(link => (
                                    <div
                                        key={link.id}
                                        className="flex items-start justify-between p-4 rounded-xl border border-[var(--color-border)] bg-[var(--color-background)] hover:shadow-sm transition-shadow"
                                    >
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2 mb-1">
                                                <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${link.category === 'Academic' ? 'bg-blue-100 text-blue-700' :
                                                    link.category === 'Exam' ? 'bg-red-100 text-red-700' :
                                                        link.category === 'Utility' ? 'bg-purple-100 text-purple-700' :
                                                            'bg-gray-100 text-gray-700'
                                                    }`}>
                                                    {link.category}
                                                </span>
                                                <h3 className="font-semibold text-[var(--color-text)]">{link.title}</h3>
                                            </div>
                                            <p className="text-sm text-[var(--color-text-muted)] mb-2">{link.description}</p>
                                            <a
                                                href={link.url}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="text-xs text-primary-600 hover:underline flex items-center gap-1"
                                            >
                                                {link.url}
                                                <ExternalLink size={12} />
                                            </a>
                                        </div>

                                        <div className="flex gap-2 ml-4">
                                            <button
                                                onClick={() => handleEdit(link)}
                                                className="action-btn text-blue-600"
                                                title="Edit"
                                            >
                                                <Edit2 size={18} />
                                            </button>
                                            <button
                                                onClick={() => handleDelete(link.id)}
                                                className="action-btn delete"
                                                title="Delete"
                                            >
                                                <Trash2 size={18} />
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ContentManagement;

import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { useAuth } from '../../context/AuthContext';
import { db } from '../../config/firebase';
import { collection, getDocs, doc, getDoc, deleteDoc } from 'firebase/firestore';
import { PROGRAMS } from '../../config/academics';
import {
    fetchDynamicSubjects, createSubject, updateSubject, deleteSubject,
    fetchDynamicUnits, createUnit, updateUnit, deleteUnit,
    fetchDynamicModules, createModule, updateModule, deleteModule,
    duplicateSubject, duplicateUnit, duplicateModule
} from '../../utils/academicsUtils';
import { pdfService } from '../../services/pdfService';
import { resolveBackendUrl } from '../../config/driveBackends';
import ImageUpload from '../../components/Common/ImageUpload';
import { Plus, Trash2, Folder, FileText, BookOpen, Video, ChevronRight, ChevronDown, Edit2, AlertCircle, CheckCircle, XCircle, X, HelpCircle, UploadCloud, Loader2, ShieldAlert, Copy, ClipboardPaste, Scissors } from 'lucide-react';
import LoadingTransition from '../../components/Common/LoadingTransition';
import CustomSelect from '../../components/Common/CustomSelect';
import UnitQuizManager from '../../components/Admin/UnitQuizManager';
import FileUploadWidget from '../../components/Admin/FileUploadWidget';
import './Admin.css';

const convertDriveLink = (url) => {
    if (!url) return url;
    // Check if it's a Google Drive link that isn't already a direct download link
    if (url.includes('drive.google.com') && !url.includes('export=download')) {
        const match = url.match(/(?:\/d\/|id=)([-\w]{25,})/);
        if (match && match[1]) {
            return `https://drive.google.com/uc?export=download&id=${match[1]}`;
        }
    }
    return url;
};

const CourseContentManagement = () => {
    // Selection State
    const [selectedProgram, setSelectedProgram] = useState(PROGRAMS[0]);
    const [selectedYear, setSelectedYear] = useState(PROGRAMS[0].years[0]);
    const [selectedBranch, setSelectedBranch] = useState(null);
    const [selectedSemester, setSelectedSemester] = useState(PROGRAMS[0].years[0].semesters[0]);

    // Data State
    const [subjects, setSubjects] = useState([]);
    const [selectedSubject, setSelectedSubject] = useState(null);
    const [units, setUnits] = useState([]);
    const [selectedUnit, setSelectedUnit] = useState(null);
    const [modules, setModules] = useState([]);

    // Multi-select State
    const [selectedSubjectIds, setSelectedSubjectIds] = useState(new Set()); // Set of IDs
    const [isBulkMoving, setIsBulkMoving] = useState(false);

    // Loading State
    const [loadingSubjects, setLoadingSubjects] = useState(false);
    const [loadingUnits, setLoadingUnits] = useState(false);
    const [loadingModules, setLoadingModules] = useState(false);

    // Form Modal State
    const [activeModal, setActiveModal] = useState(null); // 'subject', 'unit', 'module'
    const [editingItem, setEditingItem] = useState(null); // Item being edited
    const [newItemLabel, setNewItemLabel] = useState('');
    const [newModuleVideo, setNewModuleVideo] = useState('');
    const [newModulePdf, setNewModulePdf] = useState('');
    const [newModulePdfName, setNewModulePdfName] = useState('');
    const [newModuleHandwrittenNotes, setNewModuleHandwrittenNotes] = useState('');
    const [newModuleHandwrittenNotesName, setNewModuleHandwrittenNotesName] = useState('');
    const [additionalNotes, setAdditionalNotes] = useState([]); // [{ label, url }]

    const [deleteConfirmation, setDeleteConfirmation] = useState({
        isOpen: false,
        type: null, // 'subject', 'unit', 'module'
        id: null,
        title: ''
    });

    const [isDeleting, setIsDeleting] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    // Accordion State
    const [isResourcesExpanded, setIsResourcesExpanded] = useState(true);

    const [deletingFileUrl, setDeletingFileUrl] = useState(null);
    const [fileDeleteModal, setFileDeleteModal] = useState({
        isOpen: false,
        fileIdOrUrl: null,
        onConfirm: null
    });


    // Modal State for Move/Add Subject
    const [targetYear, setTargetYear] = useState('');
    const [targetSemester, setTargetSemester] = useState('');

    // Quiz Manager State
    const [quizManagerTarget, setQuizManagerTarget] = useState(null); // { id, label }

    const { user } = useAuth();
    const [adminUser, setAdminUser] = useState(null);

    // Clipboard State
    const [clipboard, setClipboard] = useState(null); // { type: 'subject' | 'unit' | 'module', id: '...' }

    // Toast State
    const [toast, setToast] = useState({
        visible: false,
        message: '',
        type: 'success' // 'success' or 'error'
    });

    const showToast = (message, type = 'success') => {
        setToast({ visible: true, message, type });
        setTimeout(() => setToast(prev => ({ ...prev, visible: false })), 3000);
    };

    // --- Effects ---

    // Load Subjects when hierarchy changes
    useEffect(() => {
        // If the current year has branches, wait until a branch is selected
        if (selectedYear?.branches && !selectedBranch) {
            setSubjects([]);
            return;
        }
        if (selectedSemester) {
            loadSubjects();
        }
        setSelectedSubject(null);
        setSelectedUnit(null);
        setSelectedSubjectIds(new Set()); // Clear selection on view change
    }, [selectedProgram, selectedYear, selectedBranch, selectedSemester]);

    // Load Units when Subject changes
    useEffect(() => {
        if (selectedSubject) {
            loadUnits();
            setSelectedUnit(null);
        } else {
            setUnits([]);
        }
    }, [selectedSubject]);

    // Load Modules when Unit changes
    useEffect(() => {
        if (selectedUnit) {
            loadModules();
        } else {
            setModules([]);
        }
    }, [selectedUnit]);

    // --- Loading & Utility Functions ---

    const promptFileDelete = (fileIdOrUrl, setUrlState) => {
        if (!fileIdOrUrl) return;
        if (fileIdOrUrl.startsWith('http')) {
            setUrlState('');
            return;
        }
        setFileDeleteModal({
            isOpen: true,
            fileIdOrUrl,
            onConfirm: setUrlState
        });
    };

    const confirmFileDelete = async () => {
        const { fileIdOrUrl, onConfirm } = fileDeleteModal;
        if (!fileIdOrUrl || !onConfirm) return;

        setDeletingFileUrl(fileIdOrUrl);
        // We do not close the modal here, we let the button show "Deleting..."

        try {
            const docRef = doc(db, 'pdfs', fileIdOrUrl);
            const docSnap = await getDoc(docRef);
            
            if (docSnap.exists()) {
                const data = docSnap.data();
                if (data.gdFileId && data.backendUrl) {
                    if (typeof pdfService.deleteFileFromDrive === 'function') {
                        try {
                            await pdfService.deleteFileFromDrive(data.gdFileId, data.backendUrl);
                        } catch (e) {
                            console.error("Drive deletion failed", e);
                        }
                    } else {
                        console.warn("deleteFileFromDrive not implemented in pdfService");
                    }
                }
                await deleteDoc(docRef);
            }
            
            onConfirm('');
            if (window.showToast) window.showToast('File completely deleted', 'success');
        } catch (error) {
            console.error('Delete error:', error);
            if (window.showToast) window.showToast('Failed to delete from server, but removed from module', 'error');
            onConfirm('');
        } finally {
            setDeletingFileUrl(null);
            setFileDeleteModal({ isOpen: false, fileIdOrUrl: null, onConfirm: null });
        }
    };

    const loadSubjects = async () => {
        if (!selectedSemester) return;
        setLoadingSubjects(true);
        // Combine static and dynamic
        const staticSubjects = selectedSemester.subjects || [];
        const dynamic = await fetchDynamicSubjects(selectedProgram.id, selectedYear.id, selectedBranch?.id || null, selectedSemester.id);
        setSubjects([...staticSubjects, ...dynamic]);

        setTimeout(() => {
            setLoadingSubjects(false);
        }, 2000);
    };

    const loadUnits = async () => {
        setLoadingUnits(true);
        const staticUnits = selectedSubject.units || [];
        // Even if subject is static, we can check for dynamic units added to it (using its ID)
        const dynamic = await fetchDynamicUnits(selectedSubject.id);
        setUnits([...staticUnits, ...dynamic]);
        setLoadingUnits(false);
    };

    const loadModules = async () => {
        setLoadingModules(true);
        const staticModules = selectedUnit.modules || [];
        const dynamic = await fetchDynamicModules(selectedUnit.id);
        setModules([...staticModules, ...dynamic]);
        setLoadingModules(false);
    };

    // --- Security ---
    useEffect(() => {
        const fetchAdminData = async () => {
            if (!user?.uid) return;
            const snapshot = await getDocs(collection(db, 'users'));
            const data = snapshot.docs.find(doc => doc.id === user.uid)?.data();
            setAdminUser(data);
        };
        fetchAdminData();
    }, [user]);


    // --- Actions ---

    const openAddModal = (type) => {
        setEditingItem(null);
        setNewModuleVideo('');
        setNewModulePdf('');
        setNewModulePdfName('');
        setNewModuleHandwrittenNotes('');
        setNewModuleHandwrittenNotesName('');
        setAdditionalNotes([]);

        // Default target to current selection
        if (type === 'subject') {
            setNewItemLabel('');
            setTargetYear(selectedYear.id);
            setTargetSemester(selectedSemester.id);
        } else if (type === 'unit') {
            setNewItemLabel(`unit-${units.length + 1}`);
        } else {
            setNewItemLabel('');
        }

        setActiveModal(type);
    };

    const openEditModal = (item, type) => {
        setEditingItem(item);
        setNewItemLabel(item.label);
        setNewModuleVideo(item.videoUrl || '');
        setNewModulePdf(item.pdfUrl || '');
        setNewModulePdfName(item.pdfName || '');
        setNewModuleHandwrittenNotes(item.handwrittenNotesUrl || '');
        setNewModuleHandwrittenNotesName(item.handwrittenNotesName || '');
        setAdditionalNotes(item.additionalNotes || []);

        if (type === 'subject') {
            setTargetYear(item.yearId || selectedYear.id);
            setTargetSemester(item.semesterId || selectedSemester.id);
        }

        setActiveModal(type);
    };

    const handleSave = async () => {
        if (!newItemLabel.trim()) return;

        setIsSaving(true);
        try {
            if (activeModal === 'subject') {
                if (editingItem) {
                    await updateSubject(editingItem.id, newItemLabel, targetYear, targetSemester, selectedProgram.id, selectedBranch?.id || null);
                    showToast('Subject updated successfully');
                } else {
                    await createSubject(selectedProgram.id, targetYear || selectedYear.id, selectedBranch?.id || null, targetSemester || selectedSemester.id, newItemLabel);
                    showToast('Subject created successfully');
                }
                loadSubjects();
            } else if (activeModal === 'unit') {
                if (editingItem) {
                    await updateUnit(editingItem.id, selectedSubject.id, newItemLabel, newModuleVideo, newModulePdf, newModulePdfName, additionalNotes);
                    showToast('Unit updated successfully');
                } else {
                    await createUnit(selectedSubject.id, newItemLabel, newModuleVideo, newModulePdf, newModulePdfName, additionalNotes);
                    showToast('Unit created successfully');
                }
                loadUnits();
                setSelectedUnit(null); // Reset unit selection to avoid stale state if needed, though mostly safe
            } else if (activeModal === 'module') {
                if (editingItem) {
                    await updateModule(editingItem.id, selectedUnit.id, newItemLabel, newModuleVideo, newModulePdf, newModulePdfName, newModuleHandwrittenNotes, newModuleHandwrittenNotesName, additionalNotes);
                    showToast('Module updated successfully');
                } else {
                    await createModule(selectedUnit.id, newItemLabel, newModuleVideo, newModulePdf, newModulePdfName, newModuleHandwrittenNotes, newModuleHandwrittenNotesName, additionalNotes);
                    showToast('Module created successfully');
                }
                loadModules();
            }

            setActiveModal(null);
            setEditingItem(null);
            setNewItemLabel('');
            setNewModuleVideo('');
            setNewModulePdf('');
            setNewModulePdfName('');
            setNewModuleHandwrittenNotes('');
            setNewModuleHandwrittenNotesName('');
            setAdditionalNotes([]);
        } catch (error) {
            console.error("Save failed:", error);
            showToast('Failed to save item', 'error');
        } finally {
            setIsSaving(false);
        }
    };

    const handleDeleteSubject = (id, isDynamic, label) => {
        if (!isDynamic) {
            alert("Cannot delete static subjects defined in config.");
            return;
        }
        setDeleteConfirmation({
            isOpen: true,
            type: 'subject',
            id,
            title: label
        });
    };

    const handleDeleteUnit = (id, isDynamic, label) => {
        if (!isDynamic) {
            alert("Cannot delete static units defined in config.");
            return;
        }
        setDeleteConfirmation({
            isOpen: true,
            type: 'unit',
            id,
            title: label
        });
    };

    const handleDeleteModule = (id, isDynamic, label) => {
        if (!isDynamic) {
            alert("Cannot delete static modules defined in config.");
            return;
        }
        setDeleteConfirmation({
            isOpen: true,
            type: 'module',
            id,
            title: label
        });
    };

    // --- Bulk Actions ---

    const toggleSelectAllSubjects = () => {
        if (selectedSubjectIds.size === subjects.filter(s => s.isDynamic).length && subjects.filter(s => s.isDynamic).length > 0) {
            setSelectedSubjectIds(new Set());
        } else {
            const dynamicIds = subjects.filter(s => s.isDynamic).map(s => s.id);
            setSelectedSubjectIds(new Set(dynamicIds));
        }
    };

    const toggleSubjectSelection = (id) => {
        const newSet = new Set(selectedSubjectIds);
        if (newSet.has(id)) {
            newSet.delete(id);
        } else {
            newSet.add(id);
        }
        setSelectedSubjectIds(newSet);
    };

    const handleBulkDelete = () => {
        if (selectedSubjectIds.size === 0) return;
        setDeleteConfirmation({
            isOpen: true,
            type: 'bulk_subjects',
            id: null,
            title: `${selectedSubjectIds.size} subjects`
        });
    };

    const openBulkMoveModal = () => {
        if (selectedSubjectIds.size === 0) return;
        setIsBulkMoving(true);
        setTargetYear(selectedYear.id);
        setTargetSemester(selectedSemester.id);
        setActiveModal('bulk_move_subjects');
    };

    const handleBulkMoveSave = async () => {
        setIsSaving(true);
        try {
            const updatePromises = Array.from(selectedSubjectIds).map(id =>
                updateSubject(id, subjects.find(s => s.id === id)?.label, targetYear, targetSemester, selectedProgram.id, selectedBranch?.id || null)
            );
            await Promise.all(updatePromises);
            showToast(`Moved ${selectedSubjectIds.size} subjects successfully`);
            setSelectedSubjectIds(new Set());
            setActiveModal(null);
            setIsBulkMoving(false);
            loadSubjects();
        } catch (error) {
            console.error("Bulk move failed:", error);
            showToast("Failed to move subjects", "error");
        } finally {
            setIsSaving(false);
        }
    };

    const confirmDelete = async () => {
        setIsDeleting(true);
        const { type, id } = deleteConfirmation;

        try {
            if (type === 'subject') {
                await deleteSubject(id, selectedProgram.id, selectedYear.id, selectedBranch?.id || null, selectedSemester.id);
                if (selectedSubject?.id === id) setSelectedSubject(null);
                loadSubjects();
                showToast('Subject deleted successfully');
            } else if (type === 'bulk_subjects') {
                const deletePromises = Array.from(selectedSubjectIds).map(id => deleteSubject(id, selectedProgram.id, selectedYear.id, selectedBranch?.id || null, selectedSemester.id));
                await Promise.all(deletePromises);
                setSelectedSubjectIds(new Set());
                setSelectedSubject(null);
                loadSubjects();
                showToast('Selected subjects deleted successfully');
            } else if (type === 'unit') {
                await deleteUnit(id, selectedSubject.id);
                if (selectedUnit?.id === id) setSelectedUnit(null);
                loadUnits();
                showToast('Unit deleted successfully');
            } else if (type === 'module') {
                await deleteModule(id, selectedUnit.id);
                loadModules();
                showToast('Module deleted successfully');
            }
            setDeleteConfirmation({ isOpen: false, type: null, id: null, title: '' });
        } catch (error) {
            console.error("Delete failed:", error);
            showToast('Failed to delete item', 'error');
        } finally {
            setIsDeleting(false);
        }
    };

    // --- Paste/Copy ---
    const handleCopy = (type, id) => {
        setClipboard({ type, id });
        showToast(`${type.charAt(0).toUpperCase() + type.slice(1)} copied to clipboard`, 'success');
    };

    const handleBulkClipboard = (operation) => {
        const items = Array.from(selectedSubjectIds).map(id => {
            const subject = subjects.find(s => s.id === id);
            return { id, label: subject?.label };
        });
        setClipboard({ type: 'bulk_subject', items, operation });
        showToast(`Selected subjects ready to ${operation}`, 'success');
        setSelectedSubjectIds(new Set());
    };

    const handlePaste = async (targetType) => {
        if (!clipboard) return;
        setIsSaving(true);
        try {
            if (targetType === 'subject' && clipboard.type === 'bulk_subject') {
                if (clipboard.operation === 'copy') {
                    for (const item of clipboard.items) {
                        await duplicateSubject(item.id, selectedProgram.id, selectedYear.id, selectedBranch?.id || null, selectedSemester.id);
                    }
                    showToast(`Copied ${clipboard.items.length} subjects successfully`);
                } else if (clipboard.operation === 'cut') {
                    for (const item of clipboard.items) {
                        await updateSubject(item.id, item.label, selectedYear.id, selectedSemester.id, selectedProgram.id, selectedBranch?.id || null);
                    }
                    showToast(`Moved ${clipboard.items.length} subjects successfully`);
                }
                loadSubjects();
            } else if (targetType === 'subject' && clipboard.type === 'subject') {
                await duplicateSubject(clipboard.id, selectedProgram.id, selectedYear.id, selectedBranch?.id || null, selectedSemester.id);
                loadSubjects();
                showToast('Subject pasted successfully');
            } else if (targetType === 'unit' && clipboard.type === 'unit') {
                await duplicateUnit(clipboard.id, selectedSubject.id);
                loadUnits();
                showToast('Unit pasted successfully');
            } else if (targetType === 'module' && clipboard.type === 'module') {
                await duplicateModule(clipboard.id, selectedUnit.id);
                loadModules();
                showToast('Module pasted successfully');
            }
            setClipboard(null);
        } catch (error) {
            console.error("Paste failed:", error);
            showToast('Failed to paste item', 'error');
        } finally {
            setIsSaving(false);
        }
    };

    // --- Helpers ---

    const handleProgramChange = (val) => {
        const prog = PROGRAMS.find(p => p.id === val);
        const firstYear = prog.years[0];
        setSelectedProgram(prog);
        setSelectedYear(firstYear);
        if (firstYear.branches) {
            setSelectedBranch(firstYear.branches[0]);
            setSelectedSemester(firstYear.branches[0].semesters[0]);
        } else {
            setSelectedBranch(null);
            setSelectedSemester(firstYear.semesters[0]);
        }
    };

    const handleYearChange = (val) => {
        const yr = selectedProgram.years.find(y => y.id === val);
        setSelectedYear(yr);
        if (yr.branches) {
            setSelectedBranch(yr.branches[0]);
            setSelectedSemester(yr.branches[0].semesters[0]);
        } else {
            setSelectedBranch(null);
            setSelectedSemester(yr.semesters[0]);
        }
    };

    const handleSemesterChange = (val) => {
        const semesters = selectedBranch ? selectedBranch.semesters : selectedYear.semesters;
        const sem = semesters.find(s => s.id === val);
        setSelectedSemester(sem);
    };

    const handleBranchChange = (val) => {
        const branch = selectedYear.branches.find(b => b.id === val);
        setSelectedBranch(branch);
        setSelectedSemester(branch.semesters[0]);
    };

    const handleAddNote = () => {
        setAdditionalNotes([...additionalNotes, { label: '', url: '' }]);
    };

    const handleRemoveNote = (index) => {
        const updated = [...additionalNotes];
        updated.splice(index, 1);
        setAdditionalNotes(updated);
    };

    const handleNoteChange = (index, field, value) => {
        const updated = [...additionalNotes];
        updated[index] = { ...updated[index], [field]: value };
        setAdditionalNotes(updated);
    };

    return (
        <div className="admin-container">
            <div className="page-header-v2">
                <div className="header-accent-bar"></div>
                <div className="header-content-v2">
                    <h1 className="page-title-v2">Course Content Manager</h1>
                    <p className="page-subtitle-v2">Manage subjects, units, and learning materials effectively.</p>
                </div>
            </div>

            {/* Hierarchy Selectors */}
            <div className="section-card selectors-wrapper bg-[var(--color-surface)] rounded-2xl border border-[var(--color-border)] mb-8 flex flex-col md:flex-row gap-4 p-4 z-20 items-center justify-between">
                <div className="flex flex-col md:flex-row gap-4 w-full md:w-auto">
                    <CustomSelect 
                        label="Degree Program"
                        options={PROGRAMS.map(p => ({ value: p.id, label: p.label }))} 
                        value={selectedProgram.id} 
                        onChange={handleProgramChange} 
                    />
                    <CustomSelect 
                        label="Academic Year"
                        options={selectedProgram.years.map(y => ({ value: y.id, label: y.label }))} 
                        value={selectedYear.id} 
                        onChange={handleYearChange} 
                    />
                    {selectedYear.branches && (
                        <CustomSelect 
                            label="Branch"
                            options={selectedYear.branches.map(b => ({ value: b.id, label: b.label }))} 
                            value={selectedBranch?.id || ''} 
                            onChange={handleBranchChange} 
                        />
                    )}
                    {(!selectedYear.branches || selectedBranch) && (
                        <CustomSelect 
                            label="Active Semester"
                            options={(selectedBranch ? selectedBranch.semesters : selectedYear.semesters).map(s => ({ value: s.id, label: s.label }))} 
                            value={selectedSemester?.id || ''} 
                            onChange={handleSemesterChange} 
                        />
                    )}
                </div>
            </div>

            {(!selectedYear.branches || selectedBranch) && (
                <div className="course-manager-grid">

                {/* Column 1: Subjects */}
                <div className="manager-column">
                    <div className="column-header flex-wrap" style={{ gap: '8px', rowGap: '12px' }}>
                        <div className="flex items-start gap-2 min-w-max">
                            <input
                                type="checkbox"
                                className="custom-checkbox mt-1"
                                checked={subjects.length > 0 && subjects.filter(s => s.isDynamic).length > 0 && selectedSubjectIds.size === subjects.filter(s => s.isDynamic).length}
                                onChange={toggleSelectAllSubjects}
                                disabled={subjects.filter(s => s.isDynamic).length === 0}
                            />
                            <div className="flex flex-col">
                                <h3 className="whitespace-nowrap m-0 leading-tight text-[1.1rem]">Subjects</h3>
                                {selectedSubjectIds.size > 0 && <span className="text-[10px] text-slate-400 mt-0.5 whitespace-nowrap">selected {selectedSubjectIds.size}</span>}
                            </div>
                        </div>
                        <div className="flex flex-wrap justify-end ml-auto items-center" style={{ gap: '10px' }}>
                            {(clipboard?.type === 'subject' || clipboard?.type === 'bulk_subject') && (
                                <button onClick={() => handlePaste('subject')} className="action-btn !w-7 !h-7 text-blue-600 bg-blue-50 hover:bg-blue-100" title="Paste Subject">
                                    <ClipboardPaste size={14} />
                                </button>
                            )}
                            {selectedSubjectIds.size > 0 && (
                                <>
                                    <button onClick={() => handleBulkClipboard('copy')} className="action-btn !w-7 !h-7 text-green-600 bg-green-50 hover:bg-green-100" title="Copy Selected">
                                        <Copy size={14} />
                                    </button>
                                    <button onClick={() => handleBulkClipboard('cut')} className="action-btn !w-7 !h-7 text-orange-600 bg-orange-50 hover:bg-orange-100" title="Cut Selected">
                                        <Scissors size={14} />
                                    </button>
                                    <button onClick={openBulkMoveModal} className="action-btn !w-7 !h-7 text-blue-600 bg-blue-50 hover:bg-blue-100" title="Move Selected">
                                        <ChevronRight size={14} />
                                    </button>
                                    <button onClick={handleBulkDelete} className="action-btn !w-7 !h-7 text-red-600 bg-red-50 hover:bg-red-100" title="Delete Selected">
                                        <Trash2 size={14} />
                                    </button>
                                </>
                            )}
                            <button onClick={() => openAddModal('subject')} className="add-btn flex items-center justify-center !w-7 !h-7"><Plus size={14} /></button>
                        </div>
                    </div>
                    <div className="column-content">
                        {loadingSubjects ? (
                            <div className="space-y-2">
                                {[1, 2, 3, 4].map(i => (
                                    <div key={i} className="manager-item" style={{ pointerEvents: 'none' }}>
                                        <div className="skeleton" style={{ width: i % 2 === 0 ? '60%' : '80%', height: '20px', borderRadius: '4px' }}></div>
                                    </div>
                                ))}
                            </div>
                        ) :
                            subjects.length === 0 ? <div className="empty-state">No subjects</div> :
                                subjects.map(sub => (
                                    <div
                                        key={sub.id}
                                        className={`manager-item ${selectedSubject?.id === sub.id ? 'active' : ''}`}
                                        onClick={() => setSelectedSubject(sub)}
                                    >
                                        {sub.isDynamic && (
                                            <div onClick={e => e.stopPropagation()} className="mr-6 flex items-center">
                                                <input
                                                    type="checkbox"
                                                    className="custom-checkbox"
                                                    checked={selectedSubjectIds.has(sub.id)}
                                                    onChange={() => toggleSubjectSelection(sub.id)}
                                                />
                                            </div>
                                        )}
                                        <span className="flex-1 truncate">{sub.label}</span>
                                        {sub.isDynamic && (
                                            <div className="flex gap-2">
                                                <button onClick={(e) => { e.stopPropagation(); handleCopy('subject', sub.id); }} className="action-btn text-green-500" title="Copy Subject">
                                                    <Copy size={14} />
                                                </button>
                                                <button onClick={(e) => { e.stopPropagation(); openEditModal(sub, 'subject'); }} className="action-btn text-blue-500">
                                                    <Edit2 size={14} />
                                                </button>
                                                <button onClick={(e) => { e.stopPropagation(); handleDeleteSubject(sub.id, true, sub.label) }} className="action-btn delete">
                                                    <Trash2 size={14} />
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                ))
                        }
                    </div>
                </div>

                {/* Column 2: Units */}
                <div className="manager-column">
                    <div className="column-header">
                        <h3>Units</h3>
                        <div className="flex gap-3">
                            {selectedSubject && clipboard?.type === 'unit' && (
                                <button onClick={() => handlePaste('unit')} className="action-btn text-blue-600 bg-blue-50 hover:bg-blue-100" title="Paste Unit">
                                    <ClipboardPaste size={16} />
                                </button>
                            )}
                            {selectedSubject && <button onClick={() => openAddModal('unit')} className="add-btn"><Plus size={16} /></button>}
                        </div>
                    </div>
                    <div className="column-content">
                        {!selectedSubject ? <div className="empty-state">Select a Subject</div> :
                            loadingUnits ? (
                                <div className="space-y-2">
                                    {[1, 2, 3, 4].map(i => (
                                        <div key={i} className="manager-item" style={{ pointerEvents: 'none' }}>
                                            <div className="skeleton" style={{ width: i % 2 === 0 ? '70%' : '50%', height: '20px', borderRadius: '4px' }}></div>
                                        </div>
                                    ))}
                                </div>
                            ) :
                                units.length === 0 ? <div className="empty-state">No units found</div> :
                                    units.map(unit => (
                                        <div
                                            key={unit.id}
                                            className={`manager-item ${selectedUnit?.id === unit.id ? 'active' : ''}`}
                                            onClick={() => setSelectedUnit(unit)}
                                        >
                                            <span className="flex-1 truncate">{unit.label}</span>
                                            {unit.isDynamic && (
                                                <div className="flex gap-2">
                                                    <button onClick={(e) => { e.stopPropagation(); handleCopy('unit', unit.id); }} className="action-btn text-green-500" title="Copy Unit">
                                                        <Copy size={14} />
                                                    </button>
                                                    <button onClick={(e) => { e.stopPropagation(); setQuizManagerTarget({ id: unit.id, label: unit.label, path: [selectedBranch?.label, selectedSemester?.label, selectedSubject?.label, unit.label].filter(Boolean).join(' / ') }); }} className="action-btn quiz" title="Manage Unit Quiz">
                                                        <HelpCircle size={14} />
                                                    </button>
                                                    <button onClick={(e) => { e.stopPropagation(); openEditModal(unit, 'unit'); }} className="action-btn edit">
                                                        <Edit2 size={14} />
                                                    </button>
                                                    <button onClick={(e) => { e.stopPropagation(); handleDeleteUnit(unit.id, true, unit.label) }} className="action-btn delete">
                                                        <Trash2 size={14} />
                                                    </button>
                                                </div>
                                            )}
                                        </div>
                                    ))
                        }
                    </div>
                </div>

                {/* Column 3: Modules */}
                <div className="manager-column expanded">
                    <div className="column-header">
                        <h3>Modules</h3>
                        <div className="flex gap-3">
                            {selectedUnit && clipboard?.type === 'module' && (
                                <button onClick={() => handlePaste('module')} className="action-btn text-blue-600 bg-blue-50 hover:bg-blue-100" title="Paste Module">
                                    <ClipboardPaste size={16} />
                                </button>
                            )}
                            {selectedUnit && <button onClick={() => openAddModal('module')} className="add-btn"><Plus size={16} /></button>}
                        </div>
                    </div>
                    <div className="column-content">
                        {!selectedUnit ? <div className="empty-state">Select a Unit</div> :
                            loadingModules ? (
                                <div className="space-y-3">
                                    {[1, 2, 3].map(i => (
                                        <div key={i} className="module-item" style={{ pointerEvents: 'none' }}>
                                            <div className="module-header mb-3">
                                                <div className="skeleton" style={{ width: i === 2 ? '40%' : '70%', height: '20px', borderRadius: '4px' }}></div>
                                            </div>
                                            <div className="flex gap-2">
                                                <div className="skeleton" style={{ width: '70px', height: '24px', borderRadius: '12px' }}></div>
                                                <div className="skeleton" style={{ width: '80px', height: '24px', borderRadius: '12px' }}></div>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) :
                                modules.length === 0 ? <div className="empty-state">No modules found</div> :
                                    modules.map(mod => (
                                        <div key={mod.id} className="module-item">
                                            <div className="module-header">
                                                <span className="font-medium">{mod.label}</span>
                                                {mod.isDynamic && (
                                                    <div className="flex gap-2">
                                                        <button onClick={(e) => { e.stopPropagation(); handleCopy('module', mod.id); }} className="action-btn text-green-500" title="Copy Module">
                                                            <Copy size={14} />
                                                        </button>
                                                        <button onClick={(e) => { e.stopPropagation(); setQuizManagerTarget({ id: mod.id, label: mod.label, path: [selectedBranch?.label, selectedSemester?.label, selectedSubject?.label, selectedUnit?.label, mod.label].filter(Boolean).join(' / ') }); }} className="action-btn quiz" title="Manage Module Quiz">
                                                            <HelpCircle size={14} />
                                                        </button>
                                                        <button onClick={(e) => { e.stopPropagation(); openEditModal(mod, 'module'); }} className="action-btn edit">
                                                            <Edit2 size={14} />
                                                        </button>
                                                        <button onClick={() => handleDeleteModule(mod.id, true, mod.label)} className="action-btn delete">
                                                            <Trash2 size={14} />
                                                        </button>
                                                    </div>
                                                )}
                                            </div>
                                            <div className="module-links">
                                                {mod.videoUrl && (
                                                    <a href={mod.videoUrl} target="_blank" rel="noopener noreferrer" className="link-badge video">
                                                        <Video size={12} /> Video
                                                    </a>
                                                )}
                                                {mod.pdfUrl && (
                                                    <a href={mod.pdfUrl} target="_blank" rel="noopener noreferrer" className="link-badge pdf">
                                                        <FileText size={12} /> Notes
                                                    </a>
                                                )}
                                                {mod.handwrittenNotesUrl && (
                                                    <a href={mod.handwrittenNotesUrl} target="_blank" rel="noopener noreferrer" className="link-badge pdf">
                                                        <FileText size={12} /> Handwritten
                                                    </a>
                                                )}
                                            </div>
                                        </div>
                                    ))
                        }
                    </div>
                </div>
            </div>
            )}

            {/* Modals */}
            {activeModal && createPortal(
                <div className={`modal-overlay ${(activeModal === 'unit' || activeModal === 'module') ? 'full-screen-overlay' : ''}`}>
                    <div className={`modal-content ${(activeModal === 'unit' || activeModal === 'module') ? 'full-screen' : ''}`}>
                        <div className="modal-header">
                            <h3>
                                {activeModal === 'bulk_move_subjects'
                                    ? 'Move Subjects'
                                    : (editingItem ? 'Edit' : 'Add') + ' ' + (activeModal === 'subject' ? 'Subject' : activeModal === 'unit' ? 'Unit' : 'Module')}
                            </h3>
                            <button 
                                onClick={() => setActiveModal(null)} 
                                className="modal-close-btn"
                            >
                                <X size={20} />
                            </button>
                        </div>
                        <div className="modal-body space-y-4">
                            {activeModal === 'bulk_move_subjects' ? (
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="admin-form-label">Year</label>
                                        <select
                                            className="admin-form-input"
                                            value={targetYear}
                                            onChange={(e) => {
                                                setTargetYear(e.target.value);
                                                const yr = selectedProgram.years.find(y => y.id === e.target.value);
                                                if (yr) setTargetSemester(yr.semesters[0].id);
                                            }}
                                        >
                                            {selectedProgram.years.map(y => (
                                                <option key={y.id} value={y.id}>{y.label}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div>
                                        <label className="admin-form-label">Semester</label>
                                        <select
                                            className="admin-form-input"
                                            value={targetSemester}
                                            onChange={(e) => setTargetSemester(e.target.value)}
                                        >
                                            {selectedProgram.years.find(y => y.id === targetYear)?.semesters.map(s => (
                                                <option key={s.id} value={s.id}>{s.label}</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>
                            ) : activeModal === 'subject' ? (
                                <div className="space-y-4">
                                    <div className="admin-form-group">
                                        <label className="admin-form-label">Name/Title</label>
                                        <input
                                            type="text"
                                            className="admin-form-input"
                                            value={newItemLabel}
                                            onChange={e => setNewItemLabel(e.target.value)}
                                            placeholder="Enter subject name"
                                            autoFocus
                                        />
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="admin-form-label">Year</label>
                                            <select
                                                className="admin-form-input"
                                                value={targetYear}
                                                onChange={(e) => {
                                                    setTargetYear(e.target.value);
                                                    const yr = selectedProgram.years.find(y => y.id === e.target.value);
                                                    if (yr) setTargetSemester(yr.semesters[0].id);
                                                }}
                                            >
                                                {selectedProgram.years.map(y => (
                                                    <option key={y.id} value={y.id}>{y.label}</option>
                                                ))}
                                            </select>
                                        </div>
                                        <div>
                                            <label className="admin-form-label">Semester</label>
                                            <select
                                                className="admin-form-input"
                                                value={targetSemester}
                                                onChange={(e) => setTargetSemester(e.target.value)}
                                            >
                                                {selectedProgram.years.find(y => y.id === targetYear)?.semesters.map(s => (
                                                    <option key={s.id} value={s.id}>{s.label}</option>
                                                ))}
                                            </select>
                                        </div>
                                    </div>
                                </div>
                            ) : (activeModal === 'module' || activeModal === 'unit') && (
                                <div className="space-y-6">
                                    {/* Primary Info Section */}
                                    <div className="premium-card">
                                        <div className="admin-section-header mb-6">
                                            <BookOpen size={20} className="text-purple-500 mr-2" />
                                            <h4 className="text-lg font-bold">Core Materials</h4>
                                        </div>
                                        <div className="space-y-6">
                                            <div className="admin-form-group">
                                                <label className="admin-form-label">Name/Title</label>
                                                <input
                                                    type="text"
                                                    className="premium-input"
                                                    value={newItemLabel}
                                                    onChange={e => setNewItemLabel(e.target.value)}
                                                    placeholder={`Enter ${activeModal} name`}
                                                    autoFocus
                                                />
                                            </div>
                                            <div className="admin-form-group">
                                                <label className="admin-form-label flex items-center gap-2">
                                                    <Video size={14} /> Video URL (YouTube/MP4)
                                                </label>
                                                <input
                                                    type="url"
                                                    className="premium-input"
                                                    value={newModuleVideo}
                                                    onChange={e => setNewModuleVideo(e.target.value)}
                                                    placeholder="https://youtube.com/..."
                                                />
                                                {newModuleVideo && !newModuleVideo.startsWith('http') && (
                                                    <div className="url-validation-hint invalid">
                                                        <AlertCircle size={10} /> Enter a valid URL starting with http
                                                    </div>
                                                )}
                                            </div>
                                            <div className="admin-form-group">
                                                <label className="admin-form-label flex items-center gap-2 mb-2">
                                                    <FileText size={14} /> Main Lecture Notes (PDF/Drive)
                                                </label>
                                                <input
                                                    type="text"
                                                    className="premium-input w-full mb-3"
                                                    value={newModulePdfName}
                                                    onChange={e => setNewModulePdfName(e.target.value)}
                                                    placeholder="Custom Document Name (e.g., Chapter 1 Notes)"
                                                />
                                                {newModulePdf ? (
                                                    <div className="uploaded-doc-card">
                                                        <div className="flex items-center gap-3 overflow-hidden">
                                                            <div className="w-10 h-10 rounded-lg bg-purple-500/20 text-purple-400 flex items-center justify-center shrink-0">
                                                                <FileText size={20} />
                                                            </div>
                                                            <div className="overflow-hidden">
                                                                <p className="text-sm font-semibold text-slate-200">Uploaded Document</p>
                                                                {newModulePdf.startsWith('http') ? (
                                                                    <a href={newModulePdf} target="_blank" rel="noreferrer" className="text-xs text-purple-400 hover:text-purple-300 hover:underline truncate block max-w-[200px] md:max-w-[300px]">
                                                                        {newModulePdf}
                                                                    </a>
                                                                ) : (
                                                                    <span className="text-xs text-slate-400 truncate block max-w-[200px] md:max-w-[300px]" title={newModulePdf}>
                                                                        ID: {newModulePdf}
                                                                    </span>
                                                                )}
                                                            </div>
                                                        </div>
                                                        <button 
                                                            type="button" 
                                                            onClick={() => promptFileDelete(newModulePdf, setNewModulePdf)} 
                                                            className={`remove-doc-btn flex items-center justify-center ${deletingFileUrl === newModulePdf ? 'opacity-70 cursor-not-allowed w-24 bg-red-500/20 text-red-400' : ''}`} 
                                                            title="Remove PDF"
                                                            disabled={deletingFileUrl === newModulePdf}
                                                        >
                                                            {deletingFileUrl === newModulePdf ? (
                                                                <>
                                                                    <Loader2 size={14} style={{ animation: 'spin 1s linear infinite' }} className="mr-1" />
                                                                    <span className="text-xs font-semibold">Deleting</span>
                                                                </>
                                                            ) : (
                                                                <Trash2 size={16} />
                                                            )}
                                                        </button>
                                                    </div>
                                                ) : (
                                                    <div className="flex flex-col gap-4 mt-1">
                                                        <input
                                                            type="url"
                                                            className="premium-input w-full"
                                                            value={newModulePdf}
