                                                        />
                                                        <div className="flex items-center gap-4 my-1">
                                                            <div className="flex-1 h-px bg-slate-700/50"></div>
                                                            <span className="text-xs font-semibold text-slate-500 uppercase tracking-wider">OR</span>
                                                            <div className="flex-1 h-px bg-slate-700/50"></div>
