                                                        <FileUploadWidget
                                                            selectedProgramId={selectedProgram?.id}
                                                            metadata={{
                                                                program: selectedProgram?.id,
                                                                year: targetYear || selectedYear?.id,
                                                                branch: selectedBranch?.id || null,
                                                                semester: targetSemester || selectedSemester?.id,
                                                                subject: selectedSubject?.id || null,
                                                                unit: selectedUnit?.id || null,
                                                                moduleName: newItemLabel || 'Untitled Module',
                                                                type: 'lecture_notes'
                                                            }}
                                                            label="Upload PDF Note"
                                                            onUploadSuccess={(id) => setNewModulePdf(id)}
                                                            onSuccess={(msg) => showToast(msg, 'success')}
                                                            onError={(msg) => showToast(msg, 'error')}
                                                        />
                                                    </div>
                                                )}
                                            </div>

                                            {activeModal === 'module' && (
                                                <div className="admin-form-group">
                                                    <label className="admin-form-label flex items-center gap-2 mb-2">
                                                        <Edit2 size={14} /> Handwritten Notes
                                                    </label>
                                                    <input
                                                        type="text"
                                                        className="premium-input w-full mb-3"
                                                        value={newModuleHandwrittenNotesName}
                                                        onChange={e => setNewModuleHandwrittenNotesName(e.target.value)}
                                                        placeholder="Custom Document Name (e.g., Class Notes)"
                                                    />
                                                    {newModuleHandwrittenNotes ? (
                                                        <div className="uploaded-doc-card">
                                                            <div className="flex items-center gap-3 overflow-hidden">
                                                                <div className="w-10 h-10 rounded-lg bg-purple-500/20 text-purple-400 flex items-center justify-center shrink-0">
                                                                    <FileText size={20} />
                                                                </div>
                                                                <div className="overflow-hidden">
                                                                    <p className="text-sm font-semibold text-slate-200">Uploaded Notes</p>
                                                                    {newModuleHandwrittenNotes.startsWith('http') ? (
                                                                        <a href={newModuleHandwrittenNotes} target="_blank" rel="noreferrer" className="text-xs text-purple-400 hover:text-purple-300 hover:underline truncate block max-w-[200px] md:max-w-[300px]">
                                                                            {newModuleHandwrittenNotes}
                                                                        </a>
                                                                    ) : (
                                                                        <span className="text-xs text-slate-400 truncate block max-w-[200px] md:max-w-[300px]" title={newModuleHandwrittenNotes}>
                                                                            ID: {newModuleHandwrittenNotes}
                                                                        </span>
                                                                    )}
                                                                </div>
                                                            </div>
                                                            <button 
                                                                type="button" 
                                                                onClick={() => promptFileDelete(newModuleHandwrittenNotes, setNewModuleHandwrittenNotes)} 
                                                                className={`remove-doc-btn flex items-center justify-center ${deletingFileUrl === newModuleHandwrittenNotes ? 'opacity-70 cursor-not-allowed w-24 bg-red-500/20 text-red-400' : ''}`} 
                                                                title="Remove Notes"
                                                                disabled={deletingFileUrl === newModuleHandwrittenNotes}
                                                            >
                                                                {deletingFileUrl === newModuleHandwrittenNotes ? (
                                                                    <>
                                                                        <Loader2 size={14} style={{ animation: 'spin 1s linear infinite' }} className="mr-1" />
                                                                        <span className="text-xs font-semibold">Deleting</span>
                                                                    </>
                                                                ) : (
                                                                    <Trash2 size={16} />
                                                                )}
                                                            </button>
                                                        </div>
                                                    ) : (
                                                        <div className="flex flex-col gap-4 mt-1">
                                                            <input
                                                                type="url"
                                                                className="premium-input w-full"
                                                                value={newModuleHandwrittenNotes}
                                                                onChange={e => setNewModuleHandwrittenNotes(convertDriveLink(e.target.value))}
                                                                placeholder="Paste URL..."
                                                            />
                                                            <div className="flex items-center gap-4 my-1">
                                                                <div className="flex-1 h-px bg-slate-700/50"></div>
                                                                <span className="text-xs font-semibold text-slate-500 uppercase tracking-wider">OR</span>
                                                                <div className="flex-1 h-px bg-slate-700/50"></div>
                                                            </div>
                                                            <FileUploadWidget
                                                                selectedProgramId={selectedProgram?.id}
                                                                metadata={{
                                                                    program: selectedProgram?.id,
                                                                    year: targetYear || selectedYear?.id,
                                                                    branch: selectedBranch?.id || null,
                                                                    semester: targetSemester || selectedSemester?.id,
                                                                    subject: selectedSubject?.id || null,
                                                                    unit: selectedUnit?.id || null,
                                                                    moduleName: newItemLabel || 'Untitled Module',
                                                                    type: 'handwritten_notes'
                                                                }}
                                                                label="Upload Handwritten Note"
                                                                onUploadSuccess={(id) => setNewModuleHandwrittenNotes(id)}
                                                                onSuccess={(msg) => showToast(msg, 'success')}
                                                                onError={(msg) => showToast(msg, 'error')}
                                                            />
                                                        </div>
                                                    )}
                                                </div>
                                            )}
                                        </div>
                                    </div>

                                    {/* Additional Notes Section */}
                                    <div className="premium-accordion">
                                        <div 
                                            className="premium-accordion-header"
                                            onClick={() => setIsResourcesExpanded(!isResourcesExpanded)}
                                        >
                                            <div className="flex items-center gap-3">
                                                <Plus size={20} className="text-purple-500" />
                                                <h4 className="text-lg font-bold text-slate-200">Additional Resources</h4>
                                                <span className="bg-purple-500/20 text-purple-400 text-xs px-2 py-1 rounded-full">{additionalNotes.length}</span>
                                            </div>
                                            <ChevronDown size={20} className={`text-slate-400 transition-transform ${isResourcesExpanded ? 'rotate-180' : ''}`} />
                                        </div>

                                        {isResourcesExpanded && (
                                            <div className="premium-accordion-content space-y-6">
                                                {additionalNotes.map((note, index) => (
                                                    <React.Fragment key={index}>
                                                        <div className="premium-card !mb-0 relative group">
                                                            <button
                                                                onClick={(e) => {
                                                                    e.preventDefault();
                                                                    if (window.confirm('Remove this note?')) {
                                                                        handleRemoveNote(index);
                                                                    }
                                                                }}
                                                                className="btn-remove-card"
                                                                title="Remove Note"
                                                            >
                                                                <Trash2 size={16} />
                                                            </button>
                                                            
                                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4">
                                                                <div className="admin-form-group !mb-0">
                                                                    <label className="admin-form-label">Resource Label</label>
                                                                    <input
                                                                        type="text"
                                                                        className="premium-input"
                                                                        value={note.label}
                                                                        onChange={e => handleNoteChange(index, 'label', e.target.value)}
                                                                        placeholder="e.g. Worksheet, Reference"
                                                                    />
                                                                </div>
                                                                <div className="admin-form-group !mb-0">
                                                                    <label className="admin-form-label">Resource File / URL</label>
                                                                    {note.url ? (
                                                                        <div className="flex items-center gap-3 p-4 bg-slate-800/50 border border-slate-700/50 rounded-xl relative group">
                                                                            <FileText size={24} className="text-red-400" />
                                                                            <div className="flex-1 min-w-0">
                                                                                <p className="text-sm font-medium text-slate-200 truncate">Resource Linked</p>
                                                                                <p className="text-xs text-slate-500 truncate">{note.url}</p>
                                                                            </div>
                                                                            <button
                                                                                type="button"
                                                                                onClick={() => promptFileDelete(note.url, (newVal) => handleNoteChange(index, 'url', newVal))}
                                                                                className="btn-remove-file"
                                                                                style={{
                                                                                    display: 'flex',
                                                                                    alignItems: 'center',
                                                                                    justifyContent: 'center',
                                                                                    flexShrink: 0,
                                                                                    width: '32px',
                                                                                    height: '32px',
                                                                                    borderRadius: '50%',
                                                                                    background: 'transparent',
                                                                                    color: '#ef4444',
                                                                                    border: 'none',
                                                                                    cursor: deletingFileUrl === note.url ? 'not-allowed' : 'pointer',
                                                                                    opacity: deletingFileUrl === note.url ? 0.7 : 1,
                                                                                    transition: 'all 0.2s ease',
                                                                                }}
                                                                                onMouseEnter={(e) => {
                                                                                    if (deletingFileUrl !== note.url) {
                                                                                        e.currentTarget.style.background = 'rgba(239, 68, 68, 0.1)';
                                                                                        e.currentTarget.style.transform = 'scale(1.1)';
                                                                                    }
                                                                                }}
                                                                                onMouseLeave={(e) => {
                                                                                    if (deletingFileUrl !== note.url) {
                                                                                        e.currentTarget.style.background = 'transparent';
                                                                                        e.currentTarget.style.transform = 'scale(1)';
                                                                                    }
                                                                                }}
                                                                                disabled={deletingFileUrl === note.url}
                                                                                title="Delete File"
                                                                            >
                                                                                {deletingFileUrl === note.url ? (
                                                                                    <Loader2 size={16} className="animate-spin" />
                                                                                ) : (
                                                                                    <Trash2 size={18} />
                                                                                )}
                                                                            </button>
                                                                        </div>
                                                                    ) : (
                                                                            <div className="space-y-4">
                                                                                <input
                                                                                    type="url"
                                                                                    className="premium-input w-full"
                                                                                    value={note.url}
                                                                                    onChange={e => handleNoteChange(index, 'url', convertDriveLink(e.target.value))}
                                                                                    placeholder="Paste External Link..."
                                                                                />
                                                                                <div className="flex items-center gap-4 my-1">
                                                                                    <div className="flex-1 h-px bg-slate-700/50"></div>
                                                                                    <span className="text-xs font-semibold text-slate-500 uppercase tracking-wider">OR</span>
                                                                                    <div className="flex-1 h-px bg-slate-700/50"></div>
                                                                                </div>
                                                                                <FileUploadWidget
                                                                                    selectedProgramId={selectedProgram?.id}
                                                                                    metadata={{
                                                                                        program: selectedProgram?.id,
                                                                                        year: targetYear || selectedYear?.id,
                                                                                        branch: selectedBranch?.id || null,
                                                                                        semester: targetSemester || selectedSemester?.id,
                                                                                        subject: selectedSubject?.id || null,
                                                                                        unit: selectedUnit?.id || null,
                                                                                        moduleName: newItemLabel || 'Untitled Module',
                                                                                        type: 'additional_resource'
                                                                                    }}
                                                                                    label="Upload Resource"
                                                                                    onUploadSuccess={(id) => handleNoteChange(index, 'url', id)}
                                                                                    onSuccess={(msg) => showToast(msg, 'success')}
                                                                                    onError={(msg) => showToast(msg, 'error')}
                                                                                />
                                                                            </div>
                                                                    )}
                                                                </div>
                                                            </div>
                                                        </div>
                                                        
                                                        {/* Inline Add Button only below the LAST note */}
                                                        {index === additionalNotes.length - 1 && (
                                                            <div className="flex justify-center -mt-2">
                                                                <button
                                                                    type="button"
                                                                    onClick={handleAddNote}
                                                                    className="btn-add-colorful"
                                                                    title="Add another note below"
                                                                >
                                                                    <Plus size={14} /> Add Resource
                                                                </button>
                                                            </div>
                                                        )}
                                                    </React.Fragment>
                                                ))}

                                                {additionalNotes.length === 0 && (
                                                    <div className="py-12 border-2 border-dashed border-white/10 rounded-2xl bg-black/20" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                                                        <p className="text-sm text-slate-400 font-bold uppercase tracking-wider mb-6">No additional resources added yet.</p>
                                                        <button 
                                                            type="button"
                                                            onClick={handleAddNote}
                                                            className="btn-primary"
                                                        >
                                                            <Plus size={16} /> Add Your First Resource
                                                        </button>
                                                    </div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                        <div className={`modal-footer ${(activeModal === 'unit' || activeModal === 'module') ? 'full-screen-footer' : ''}`}>
                            <button onClick={() => setActiveModal(null)} className="btn-secondary" disabled={isSaving}>Cancel</button>
                            <button
                                onClick={activeModal === 'bulk_move_subjects' ? handleBulkMoveSave : handleSave}
                                className="btn-primary"
                                disabled={isSaving}
                            >
                                {isSaving ? (
                                    <div className="flex items-center gap-2 justify-center">
                                        <Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} />
                                        <span>Saving...</span>
                                    </div>
                                ) : (
                                    activeModal === 'bulk_move_subjects' ? `Move ${selectedSubjectIds.size} Subjects` : 'Save Changes'
                                )}
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* Delete Confirmation Modal */}
            {deleteConfirmation.isOpen && createPortal(
                <div className="modal-overlay">
                    <div className="modal-content" style={{ maxWidth: '400px' }}>
                        <div className="modal-header text-red-600">
                            <h3 className="flex items-center gap-2">
                                <AlertCircle size={24} />
                                Delete {deleteConfirmation.type.charAt(0).toUpperCase() + deleteConfirmation.type.slice(1)}
                            </h3>
                        </div>
                        <div className="modal-body">
                            <p className="text-[var(--color-text)] mb-2">
                                Are you sure you want to delete <span className="font-bold">{deleteConfirmation.title}</span>?
                            </p>
                            <p className="text-sm text-[var(--color-text-muted)]">
                                This action cannot be undone. All associated content will be permanently removed.
                            </p>
                        </div>
                        <div className="modal-footer">
                            <button
                                onClick={() => setDeleteConfirmation({ isOpen: false, type: null, id: null, title: '' })}
                                className="btn-secondary"
                                disabled={isDeleting}
                            >
                                Cancel
                            </button>
                            <button
                                onClick={confirmDelete}
                                className="btn-destructive"
                                disabled={isDeleting}
                            >
                                {isDeleting ? (
                                    <>
                                        <Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} />
                                        Deleting...
                                    </>
                                ) : (
                                    'Delete'
                                )}
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* Toast Notification */}
            {createPortal(
                <div className={`toast-container ${toast.visible ? 'visible' : ''}`}>
                <div className={`toast ${toast.visible ? 'visible' : ''} ${toast.type}`}>
                    <div className="toast-icon-wrapper">
                        <div className="toast-icon">
                            {toast.type === 'success' ? <CheckCircle size={40} strokeWidth={3} /> : <XCircle size={40} strokeWidth={3} />}
                        </div>
                    </div>
                    <div className="toast-content">
                        <h4>{toast.type === 'success' ? 'Success!' : 'Error'}</h4>
                        <p>{toast.message}</p>
                    </div>
                </div>
                </div>,
                document.body
            )}


            {/* File Delete Confirmation */}
            {fileDeleteModal.isOpen && createPortal(
                <div className="modal-overlay" style={{ zIndex: 999999 }}>
                    <div className="modal-content" style={{ maxWidth: '400px' }}>
                        <div className="modal-header">
                            <div className="flex items-center gap-3 text-red-400">
                                <Trash2 size={24} />
                                <h3>Permanently Delete File?</h3>
                            </div>
                        </div>
                        <div className="modal-body">
                            <p className="text-slate-300 mb-2">Are you sure you want to delete this file from Google Drive and Firebase? This action cannot be undone.</p>
                        </div>
                        <div className="modal-footer">
                            <button 
                                onClick={() => setFileDeleteModal({ isOpen: false, fileIdOrUrl: null, onConfirm: null })} 
                                className="btn-secondary"
                                disabled={deletingFileUrl !== null}
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={confirmFileDelete} 
                                disabled={deletingFileUrl !== null} 
                                className="btn-destructive"
                            >
                                {deletingFileUrl !== null ? (
                                    <>
                                        <Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} />
                                        Deleting...
                                    </>
                                ) : (
                                    'Delete File'
                                )}
                            </button>
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* Quiz Manager Overlay */}
            {quizManagerTarget && createPortal(
                <UnitQuizManager
                    targetId={quizManagerTarget.id}
                    targetLabel={quizManagerTarget.label}
                    targetPath={quizManagerTarget.path}
                    onClose={() => setQuizManagerTarget(null)}
                />,
                document.body
            )}
        </div>
    );
};

export default CourseContentManagement;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, UserPlus, Shield, Check } from 'lucide-react';
import { auth, db } from '../../config/firebase';
import { createUserWithEmailAndPassword, updateProfile, getAuth } from 'firebase/auth';
import { initializeApp, deleteApp } from 'firebase/app';
import { firebaseConfig } from '../../config/firebase';
import { doc, setDoc, serverTimestamp } from 'firebase/firestore';
import { useAuth } from '../../context/AuthContext';
import { NAV_ITEMS } from '../../config/navigation';
import './CreateAdminAccount.css';

const CreateAdminAccount = () => {
    const navigate = useNavigate();
    const { user: currentUser } = useAuth();
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(false);

    const [formData, setFormData] = useState({
        fullName: '',
        email: '',
        password: '',
        adminId: ''
    });

    // We get all admin specific nav items from configuration
    const availablePermissions = NAV_ITEMS.filter(item => item.adminOnly && item.id !== 'admin-dashboard');

    const [selectedPermissions, setSelectedPermissions] = useState([]);
    const [isSuperAdmin, setIsSuperAdmin] = useState(true);

    const handlePermissionToggle = (id) => {
        setSelectedPermissions(prev => {
            if (prev.includes(id)) {
                return prev.filter(p => p !== id);
            } else {
                return [...prev, id];
            }
        });
    };

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setError(null);
        setSuccess(false);

        if (!formData.fullName || !formData.email || !formData.password) {
            setError("Please fill in all required fields.");
            return;
        }

        if (!isSuperAdmin && selectedPermissions.length === 0) {
            setError("Please select at least one permission for the semi-admin.");
            return;
        }

        setIsLoading(true);
        try {
            // 1. Initialize Secondary App to prevent logging out the current admin
            const secondaryApp = initializeApp(firebaseConfig, "SecondaryApp" + Date.now());
            const secondaryAuth = getAuth(secondaryApp);

            // 2. Create auth user on secondary app
            const userCredential = await createUserWithEmailAndPassword(secondaryAuth, formData.email, formData.password);
            const user = userCredential.user;

            // 3. Update profile
            await updateProfile(user, {
                displayName: formData.fullName
            });

            // 4. Sign out and delete secondary app
            await secondaryAuth.signOut();
            await deleteApp(secondaryApp);

            // 3. Save to Firestore
            const permissionsToSave = isSuperAdmin ? ['all'] : selectedPermissions;

            await setDoc(doc(db, 'users', user.uid), {
                fullName: formData.fullName,
                email: formData.email,
                role: 'admin',
                adminId: formData.adminId || '',
                permissions: permissionsToSave,
                createdAt: serverTimestamp(),
                createdBy: currentUser?.uid,
                status: 'active'
            });

            setSuccess(true);
            setFormData({ fullName: '', email: '', password: '', adminId: '' });
            setSelectedPermissions([]);
            setIsSuperAdmin(true);

            setTimeout(() => {
                navigate('/admin/users');
            }, 2000);

        } catch (err) {
            console.error("Error creating admin account:", err);
            // Translate Firebase Auth errors to readable messages
            if (err.code === 'auth/email-already-in-use') {
                setError("An account with this email already exists.");
            } else if (err.code === 'auth/weak-password') {
                setError("Password should be at least 6 characters.");
            } else {
                setError(err.message || "Failed to create admin account. Please try again.");
            }
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="admin-container create-admin-page">
            <div className="page-header-v2">
                <div className="header-accent-bar"></div>
                <div className="header-content-v2">

                    <h1 className="page-title-v2">Create Admin Account</h1>
                    <p className="page-subtitle-v2">Add a new administrator with specific access permissions.</p>
                </div>
            </div>

            <div className="create-admin-content">
                <form className="create-admin-form" onSubmit={handleSubmit}>

                    {error && <div className="admin-alert error">{error}</div>}
                    {success && <div className="admin-alert success">Admin account created successfully! Redirecting...</div>}

                    <div className="form-section">
                        <h3 className="section-title">
                            <UserPlus size={18} />
                            Basic Information
                        </h3>
                        <div className="form-grid">
                            <div className="admin-form-group">
                                <label className="admin-form-label">Full Name *</label>
                                <input
                                    type="text"
                                    name="fullName"
                                    className="admin-form-input"
                                    value={formData.fullName}
                                    onChange={handleChange}
                                    placeholder="Enter full name"
                                    required
                                />
                            </div>
                            <div className="admin-form-group">
                                <label className="admin-form-label">Email Address *</label>
                                <input
                                    type="email"
                                    name="email"
                                    className="admin-form-input"
                                    value={formData.email}
                                    onChange={handleChange}
                                    placeholder="admin@rgukt.ac.in"
                                    required
                                />
                            </div>
                            <div className="admin-form-group">
                                <label className="admin-form-label">Admin ID (Optional)</label>
                                <input
                                    type="text"
                                    name="adminId"
                                    className="admin-form-input"
                                    value={formData.adminId}
                                    onChange={handleChange}
                                    placeholder="e.g. ADM-001"
                                />
                            </div>
                            <div className="admin-form-group">
                                <label className="admin-form-label">Temporary Password *</label>
                                <input
                                    type="password"
                                    name="password"
                                    className="admin-form-input"
                                    value={formData.password}
                                    onChange={handleChange}
                                    placeholder="Set a strong password"
                                    required
                                    minLength={6}
                                />
                            </div>
                        </div>
                    </div>

                    <div className="form-section">
                        <h3 className="section-title">
                            <Shield size={18} />
                            Access Permissions
                        </h3>

                        <div className="permission-type-selector">
                            <label className={`perm-type-card ${isSuperAdmin ? 'active' : ''}`}>
                                <input 
                                    type="radio" 
                                    name="adminType"
                                    checked={isSuperAdmin}
                                    onChange={() => setIsSuperAdmin(true)}
                                    className="hidden-radio"
                                />
                                <div className="perm-card-content">
                                    <div className="perm-card-header">
                                        <div className="radio-circle"></div>
                                        <h4>Super Admin</h4>
                                    </div>
                                    <p>Has unrestricted access to all features and modules in the admin panel.</p>
                                </div>
                            </label>

                            <label className={`perm-type-card ${!isSuperAdmin ? 'active' : ''}`}>
                                <input 
                                    type="radio" 
                                    name="adminType"
                                    checked={!isSuperAdmin}
                                    onChange={() => setIsSuperAdmin(false)}
                                    className="hidden-radio"
                                />
                                <div className="perm-card-content">
                                    <div className="perm-card-header">
                                        <div className="radio-circle"></div>
                                        <h4>Semi-Admin (Custom Access)</h4>
                                    </div>
                                    <p>Select specific modules this administrator is allowed to access.</p>
                                </div>
                            </label>
                        </div>

                        {!isSuperAdmin && (
                            <div className="permissions-grid">
                                {availablePermissions.map(item => (
                                    <label key={item.id} className={`permission-item ${selectedPermissions.includes(item.id) ? 'selected' : ''}`}>
                                        <input 
                                            type="checkbox"
                                            className="hidden-checkbox"
                                            checked={selectedPermissions.includes(item.id)}
                                            onChange={() => handlePermissionToggle(item.id)}
                                        />
                                        <div className="perm-item-icon">
                                            <item.icon size={20} />
                                        </div>
                                        <div className="perm-item-details">
                                            <span className="perm-name">{item.label}</span>
                                        </div>
                                        <div className="perm-checkbox-indicator">
                                            <Check size={14} />
                                        </div>
                                    </label>
                                ))}
                            </div>
                        )}
                    </div>

                    <div className="form-actions">
                        <button 
                            type="button" 
                            className="btn-secondary" 
                            onClick={() => navigate(-1)}
                            disabled={isLoading}
                        >
                            Cancel
                        </button>
                        <button 
                            type="submit" 
                            className="btn-primary" 
                            disabled={isLoading}
                        >
                            {isLoading ? 'Creating Account...' : 'Create Admin Account'}
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
};

export default CreateAdminAccount;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { db } from '../../config/firebase';
import { collection, addDoc, doc, setDoc } from 'firebase/firestore';
import { 
    User, Briefcase, BookOpen, Key, Shield, 
    ArrowRight, ArrowLeft, Check, Camera, 
    AlertCircle, Copy, CheckCircle2
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import './CreateFacultyAccount.css';

const steps = [
    { id: 1, title: 'Personal', icon: <User size={24} /> },
    { id: 2, title: 'Professional', icon: <Briefcase size={24} /> },
    { id: 3, title: 'Academic', icon: <BookOpen size={24} /> },
    { id: 4, title: 'Credentials', icon: <Key size={24} /> },
    { id: 5, title: 'Permissions', icon: <Shield size={24} /> }
];

const availablePermissions = [
    { id: 'manage_subjects', label: 'Manage Assigned Subjects', desc: 'Can upload and edit subject materials' },
    { id: 'upload_materials', label: 'Upload Study Materials', desc: 'Upload PDFs, notes, and resources' },
    { id: 'manage_quizzes', label: 'Manage Quizzes', desc: 'Create, edit, and delete quizzes' },
    { id: 'view_analytics', label: 'View Quiz Analytics', desc: 'Access detailed performance reports' },
    { id: 'create_assignments', label: 'Create Assignments', desc: 'Distribute new assignments to students' },
    { id: 'evaluate_assignments', label: 'Evaluate Assignments', desc: 'Grade submissions and provide feedback' },
    { id: 'mark_attendance', label: 'Mark Attendance', desc: 'Record daily student attendance' },
    { id: 'view_performance', label: 'View Student Performance', desc: 'Access comprehensive student records' },
    { id: 'create_notices', label: 'Create Notices', desc: 'Post announcements to assigned classes' },
    { id: 'send_messages', label: 'Send Messages', desc: 'Communicate directly with students' }
];

const restrictedPermissions = [
    { id: 'admin_settings', label: 'Cannot Access Admin Settings', desc: 'System configuration locked' },
    { id: 'manage_faculty', label: 'Cannot Manage Other Faculty Accounts', desc: 'User management restricted' },
    { id: 'delete_students', label: 'Cannot Delete Student Records', desc: 'Destructive actions disabled' }
];

const CreateFacultyAccount = () => {
    const navigate = useNavigate();
    const [currentStep, setCurrentStep] = useState(1);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isSuccess, setIsSuccess] = useState(false);
    const [copied, setCopied] = useState(false);

    const [formData, setFormData] = useState({
        // Personal
        fullName: '',
        facultyId: '',
        gender: '',
        dob: '',
        mobile: '',
        email: '',
        // Professional
        department: '',
        designation: '',
        qualification: '',
        experience: '',
        employeeType: 'Permanent',
        // Academic
        assignedCourse: '',
        assignedSemester: '',
        assignedSubject: '',
        // Credentials
        username: '',
        password: '',
        // Settings & Perms
        accountStatus: 'active',
        forcePasswordChange: true,
        permissions: availablePermissions.map(p => p.id) // all checked by default
    });

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const handlePermissionToggle = (permId) => {
        setFormData(prev => {
            const perms = prev.permissions.includes(permId)
                ? prev.permissions.filter(id => id !== permId)
                : [...prev.permissions, permId];
            return { ...prev, permissions: perms };
        });
    };

    const generateId = () => {
        const randomNum = Math.floor(1000 + Math.random() * 9000);
        setFormData(prev => ({ ...prev, facultyId: `FAC-${randomNum}` }));
    };

    const generateUsername = () => {
        setFormData(prev => {
            if (!prev.fullName) {
                alert("Please enter the Full Name first to generate a username based on it.");
                return prev;
            }
            const cleanName = prev.fullName.replace(/[^a-zA-Z]/g, '').toLowerCase();
            const randomNum = Math.floor(Math.random() * 900) + 100;
            return { ...prev, username: `${cleanName}${randomNum}` };
        });
    };

    const generatePassword = () => {
        const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";
        let pass = "";
        for (let i = 0; i < 12; i++) {
            pass += chars.charAt(Math.floor(Math.random() * chars.length));
        }
        setFormData(prev => ({ 
            ...prev, 
            password: pass,
            username: prev.email || `${prev.fullName.split(' ')[0].toLowerCase()}${Math.floor(Math.random() * 100)}`
        }));
    };

    const copyCreds = () => {
        const text = `Welcome to RGUKT Faculty Portal!\n\nLogin URL: https://rgukt-connect.web.app\nUsername: ${formData.username}\nPassword: ${formData.password}\n\nPlease change your password upon first login.`;
        navigator.clipboard.writeText(text);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    const nextStep = () => {
        // Basic validation before moving next
        if (currentStep === 1 && (!formData.fullName || !formData.email || !formData.facultyId)) {
            alert("Please fill in required fields (Name, Email, ID)");
            return;
        }
        if (currentStep === 2 && (!formData.department || !formData.designation)) {
            alert("Please fill in required fields (Department, Designation)");
            return;
        }
        setCurrentStep(prev => Math.min(prev + 1, 5));
    };

    const prevStep = () => setCurrentStep(prev => Math.max(prev - 1, 1));

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            // Save detailed record to `faculties` collection
            const facultyRef = collection(db, 'faculties');
            await addDoc(facultyRef, {
                ...formData,
                createdAt: new Date().toISOString()
            });

            // Save basic stub to `users` collection for core routing
            const userRef = collection(db, 'users');
            await addDoc(userRef, {
                fullName: formData.fullName,
                email: formData.email,
                username: formData.username.toLowerCase(),
                password: formData.password,
                role: 'faculty',
                studentId: formData.facultyId, // using studentId field for generic ID
                department: formData.department,
                designation: formData.designation,
                createdAt: new Date().toISOString(),
                status: formData.accountStatus
            });

            setIsSuccess(true);

            // Wait 3 seconds then redirect
            setTimeout(() => {
                navigate('/admin');
            }, 3000);

        } catch (error) {
            console.error("Error creating faculty:", error);
            alert("Failed to create faculty account.");
        } finally {
            setIsSubmitting(false);
        }
    };

    // Render Steps
    const renderStepContent = () => {
        switch (currentStep) {
            case 1:
                return (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}>
                        <h2 className="form-card-title">Personal Information</h2>
                        <p className="form-card-subtitle mb-6">Enter the basic personal details of the faculty member.</p>

                        <div className="photo-upload-container">
                            <div className="photo-preview">
                                <Camera size={32} className="text-[var(--color-text-muted)]" />
                            </div>
                            <div className="photo-upload-actions">
                                <span className="font-semibold text-sm">Profile Photo (Optional)</span>
                                <span className="text-xs text-[var(--color-text-muted)] mb-2">JPG, PNG or GIF up to 2MB</span>
                                <button type="button" className="btn-secondary py-1 text-sm w-fit">Upload Photo</button>
                            </div>
                        </div>

                        <div className="form-grid-2">
                            <div className="form-group">
                                <label className="form-label required">Full Name</label>
                                <input type="text" name="fullName" value={formData.fullName} onChange={handleChange} className="form-input" placeholder="e.g. Dr. Ramesh Kumar" required />
                            </div>
                            <div className="form-group">
                                <label className="form-label required">Faculty ID</label>
                                <div className="input-with-button">
                                    <input type="text" name="facultyId" value={formData.facultyId} onChange={handleChange} className="form-input" placeholder="e.g. FAC-1234" required />
                                    <button type="button" onClick={generateId} className="btn-secondary">Auto Generate</button>
                                </div>
                            </div>
                            <div className="form-group">
                                <label className="form-label required">Email Address</label>
                                <input type="email" name="email" value={formData.email} onChange={handleChange} className="form-input" placeholder="e.g. ramesh@rgukt.ac.in" required />
                            </div>
                            <div className="form-group">
                                <label className="form-label required">Mobile Number</label>
                                <input type="tel" name="mobile" value={formData.mobile} onChange={handleChange} className="form-input" placeholder="+91 XXXXX XXXXX" required />
                            </div>
                            <div className="form-group">
                                <label className="form-label">Gender</label>
                                <select name="gender" value={formData.gender} onChange={handleChange} className="form-input">
                                    <option value="">Select Gender</option>
                                    <option value="Male">Male</option>
                                    <option value="Female">Female</option>
                                    <option value="Other">Other</option>
                                </select>
                            </div>
                            <div className="form-group">
                                <label className="form-label">Date of Birth</label>
                                <input type="date" name="dob" value={formData.dob} onChange={handleChange} className="form-input" />
                            </div>
                        </div>
                    </motion.div>
                );
            case 2:
                return (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}>
                        <h2 className="form-card-title">Professional Information</h2>
                        <p className="form-card-subtitle mb-6">Specify the faculty's role and experience.</p>

                        <div className="form-grid-2">
                            <div className="form-group">
                                <label className="form-label required">Department</label>
                                <select name="department" value={formData.department} onChange={handleChange} className="form-input" required>
                                    <option value="">Select Department</option>
                                    <option value="Computer Science & Engineering">Computer Science & Engineering</option>
                                    <option value="Electronics & Communication">Electronics & Communication</option>
                                    <option value="Mechanical Engineering">Mechanical Engineering</option>
                                    <option value="Civil Engineering">Civil Engineering</option>
                                    <option value="Electrical Engineering">Electrical Engineering</option>
                                    <option value="Mathematics">Mathematics</option>
                                    <option value="Physics">Physics</option>
                                    <option value="Chemistry">Chemistry</option>
                                </select>
                            </div>
                            <div className="form-group">
                                <label className="form-label required">Designation</label>
                                <input type="text" name="designation" value={formData.designation} onChange={handleChange} className="form-input" placeholder="e.g. Assistant Professor, HOD" required />
                            </div>
                            <div className="form-group">
                                <label className="form-label">Employee Type</label>
                                <select name="employeeType" value={formData.employeeType} onChange={handleChange} className="form-input">
                                    <option value="Permanent">Permanent</option>
                                    <option value="Contract">Contract</option>
                                    <option value="Guest Faculty">Guest Faculty</option>
                                    <option value="Teaching Assistant">Teaching Assistant</option>
                                </select>
                            </div>
                            <div className="form-group">
                                <label className="form-label">Experience (Years)</label>
                                <input type="number" name="experience" value={formData.experience} onChange={handleChange} className="form-input" placeholder="e.g. 5" min="0" />
                            </div>
                            <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                                <label className="form-label">Highest Qualification</label>
                                <input type="text" name="qualification" value={formData.qualification} onChange={handleChange} className="form-input" placeholder="e.g. Ph.D. in Computer Science" />
                            </div>
                        </div>
                    </motion.div>
                );
            case 3:
                return (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}>
                        <h2 className="form-card-title">Academic Assignment</h2>
                        <p className="form-card-subtitle mb-6">Assign courses and subjects to the faculty member.</p>

                        <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 mb-6 flex gap-3 text-blue-800">
                            <AlertCircle size={20} className="flex-shrink-0 mt-0.5" />
                            <p className="text-sm">Assignments can be modified later in the Faculty Management dashboard. You can skip this step if subjects are not yet finalized.</p>
                        </div>

                        <div className="form-grid-3">
                            <div className="form-group">
                                <label className="form-label">Assign Course</label>
                                <select name="assignedCourse" value={formData.assignedCourse} onChange={handleChange} className="form-input">
                                    <option value="">Select Course</option>
                                    <option value="B.Tech">B.Tech</option>
                                    <option value="PUC">PUC</option>
                                </select>
                            </div>
                            <div className="form-group">
                                <label className="form-label">Assign Semester</label>
                                <select name="assignedSemester" value={formData.assignedSemester} onChange={handleChange} className="form-input">
                                    <option value="">Select Semester</option>
                                    <option value="Semester 1">Semester 1</option>
                                    <option value="Semester 2">Semester 2</option>
                                    <option value="Semester 3">Semester 3</option>
                                    <option value="Semester 4">Semester 4</option>
                                </select>
                            </div>
                            <div className="form-group">
                                <label className="form-label">Assign Subject</label>
                                <select name="assignedSubject" value={formData.assignedSubject} onChange={handleChange} className="form-input">
                                    <option value="">Select Subject</option>
                                    <option value="Data Structures">Data Structures</option>
                                    <option value="Operating Systems">Operating Systems</option>
                                    <option value="Engineering Mathematics">Engineering Mathematics</option>
                                    <option value="Physics">Physics</option>
                                </select>
                            </div>
                        </div>
                    </motion.div>
                );
            case 4:
                return (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}>
                        <h2 className="form-card-title">Login Credentials</h2>
                        <p className="form-card-subtitle mb-6">Generate credentials for the faculty portal access.</p>

                        <div className="form-grid-2">
                            <div className="form-group">
                                <label className="form-label required">Username</label>
                                <div className="input-with-button">
                                    <input type="text" name="username" value={formData.username} onChange={handleChange} className="form-input" placeholder="Usually email address" required />
                                    <button type="button" onClick={generateUsername} className="btn-secondary">Auto Generate</button>
                                </div>
                            </div>
                            <div className="form-group">
                                <label className="form-label required">Password</label>
                                <div className="input-with-button">
                                    <input type="text" name="password" value={formData.password} onChange={handleChange} className="form-input font-mono" required />
                                    <button type="button" onClick={generatePassword} className="btn-secondary">Generate Secure</button>
                                </div>
                            </div>
                        </div>

                        {formData.password && (
                            <div className="creds-box mt-8">
                                <h4 className="font-bold text-[var(--color-text)] mb-2">Credentials Generated!</h4>
                                <p className="text-sm text-[var(--color-text-muted)]">Copy these credentials to send to the faculty member. Note: Using Firebase client auth means they will need to 'Reset Password' if we don't have an admin function.</p>

                                <div className="creds-code">
                                    Username: {formData.username}<br/>
                                    Password: {formData.password}
                                </div>

                                <button type="button" onClick={copyCreds} className="btn-secondary flex items-center gap-2">
                                    {copied ? <Check size={16} className="text-green-600"/> : <Copy size={16} />}
                                    {copied ? 'Copied!' : 'Copy to Clipboard'}
                                </button>
                            </div>
                        )}
                    </motion.div>
                );
            case 5:
                return (
                    <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }}>
                        <h2 className="form-card-title">Account Settings & Permissions</h2>
                        <p className="form-card-subtitle mb-6">Configure access levels and account status.</p>

                        <div className="flex gap-6 mb-8 pb-8 border-b border-[var(--color-border)]">
                            <label className="flex items-center gap-2 cursor-pointer">
                                <input type="checkbox" name="accountStatus" checked={formData.accountStatus === 'active'} onChange={(e) => setFormData({...formData, accountStatus: e.target.checked ? 'active' : 'inactive'})} className="w-5 h-5 accent-[var(--color-primary)]" />
                                <span className="font-medium">Active Account</span>
                            </label>
                            <label className="flex items-center gap-2 cursor-pointer">
                                <input type="checkbox" name="forcePasswordChange" checked={formData.forcePasswordChange} onChange={handleChange} className="w-5 h-5 accent-[var(--color-primary)]" />
                                <span className="font-medium">Force Password Change on First Login</span>
                            </label>
                        </div>

                        <h3 className="text-lg font-bold mb-4">Faculty Permissions</h3>
                        <div className="permissions-grid mb-8">
                            {availablePermissions.map(perm => (
                                <div 
                                    key={perm.id} 
                                    className={`permission-checkbox ${formData.permissions.includes(perm.id) ? 'checked' : ''}`}
                                    onClick={() => handlePermissionToggle(perm.id)}
                                >
                                    <input type="checkbox" checked={formData.permissions.includes(perm.id)} readOnly />
                                    <div className="permission-info">
                                        <span className="permission-title">{perm.label}</span>
                                        <span className="permission-desc">{perm.desc}</span>
                                    </div>
                                </div>
                            ))}
                        </div>

                        <h3 className="text-lg font-bold mb-4 text-red-600">Restricted Permissions</h3>
                        <div className="permissions-grid">
                            {restrictedPermissions.map(perm => (
                                <div key={perm.id} className="permission-checkbox restricted-permission">
                                    <input type="checkbox" checked={false} disabled />
                                    <div className="permission-info">
                                        <span className="permission-title line-through">{perm.label}</span>
                                        <span className="permission-desc">{perm.desc}</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </motion.div>
                );
            default:
                return null;
        }
    };

    if (isSuccess) {
        return (
            <div className="create-faculty-container flex flex-col items-center justify-center min-h-[60vh]">
                <motion.div 
                    initial={{ scale: 0.8, opacity: 0 }} 
                    animate={{ scale: 1, opacity: 1 }}
                    className="success-card max-w-md w-full"
                >
                    <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 shadow-inner">
                        <CheckCircle2 size={48} className="text-green-600" />
                    </div>
                    <h2 className="text-3xl font-extrabold mb-2 text-slate-800">Account Created!</h2>
                    <p className="text-[var(--color-text-muted)] mb-8 text-lg">
                        <strong className="text-slate-700">{formData.fullName}</strong>'s faculty account has been successfully created.
                    </p>
                    <p className="text-sm font-semibold mb-8 bg-slate-50 p-4 rounded-xl border border-slate-200 text-slate-600">
                        Redirecting to Admin Dashboard...
                    </p>
                    <button onClick={() => navigate('/admin')} className="btn-primary w-full justify-center text-lg py-3 rounded-xl shadow-lg">
                        Return to Dashboard Now
                    </button>
                </motion.div>
            </div>
        );
    }

    return (
        <div className="create-faculty-container">
            <div className="flex items-center gap-4 mb-8">
                <button onClick={() => navigate('/admin')} className="btn-ghost p-2 hover:bg-[var(--color-surface)] rounded-full transition-colors">
                    <ArrowLeft size={24} />
                </button>
                <div>
                    <h1 className="text-3xl font-bold">Create Faculty Account</h1>
                    <p className="text-[var(--color-text-muted)] mt-1">Onboard new faculty members and assign permissions.</p>
                </div>
            </div>

            {/* Stepper */}
            <div className="stepper-container">
                <div 
                    className="stepper-progress-bar" 
                    style={{ width: `${((currentStep - 1) / (steps.length - 1)) * 100}%` }}
                ></div>
                {steps.map((step, index) => (
                    <div key={step.id} className={`step-item ${currentStep === step.id ? 'active' : ''} ${currentStep > step.id ? 'completed' : ''}`}>
                        <div className="step-circle">
                            {currentStep > step.id ? <Check size={20} /> : step.icon}
                        </div>
                        <div className="step-label">{step.title}</div>
                    </div>
                ))}
            </div>

            {/* Form */}
            <form onSubmit={handleSubmit} className="form-card">
                <AnimatePresence mode="wait">
                    {renderStepContent()}
                </AnimatePresence>

                <div className="form-actions">
                    <button 
                        type="button" 
                        onClick={prevStep} 
                        className={`btn-navigation btn-ghost ${currentStep === 1 ? 'invisible' : ''}`}
                    >
                        <ArrowLeft size={18} /> Back
                    </button>

                    {currentStep < 5 ? (
                        <button type="button" onClick={nextStep} className="btn-navigation btn-primary">
                            Next Step <ArrowRight size={18} />
                        </button>
                    ) : (
                        <button type="submit" disabled={isSubmitting} className="btn-navigation btn-success">
                            {isSubmitting ? 'Creating...' : 'Create Account'} <Check size={18} />
                        </button>
                    )}
                </div>
            </form>
        </div>
    );
};

export default CreateFacultyAccount;

