import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { ArrowLeft, ArrowRight, CheckCircle2, ShieldCheck, AlertCircle, User, Fingerprint } from 'lucide-react';
import { sendPasswordResetEmail } from 'firebase/auth';
import { auth } from '../config/firebase';
import Branding from '../components/Branding';
import AppFooter from '../components/Common/AppFooter';
import { useAuth } from '../context/AuthContext';
import './ForgetPassword.css';

const ForgetPassword = () => {
    const [step, setStep] = useState(1); // 1: IDs, 2: Verifying, 3: Success (Email Sent)
    const [rcId, setRcId] = useState('');
    const [studentId, setStudentId] = useState('');
    const [targetUser, setTargetUser] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [isMismatch, setIsMismatch] = useState(false);

    const { verifyIdentifiers, recoverRcId } = useAuth();
    const navigate = useNavigate();

    const [showRcIdModal, setShowRcIdModal] = useState(false);
    const [rcIdName, setRcIdName] = useState('');
    const [rcIdCollegeId, setRcIdCollegeId] = useState('');
    const [rcIdMobile, setRcIdMobile] = useState('');
    const [recoveredRcId, setRecoveredRcId] = useState('');
    const [rcIdError, setRcIdError] = useState('');
    const [rcIdLoading, setRcIdLoading] = useState(false);

    // Clear mismatch state when typing
    useEffect(() => {
        if (isMismatch) setIsMismatch(false);
    }, [rcId, studentId]);

    const handleRecoverRcId = async (e) => {
        e.preventDefault();
        setRcIdError('');
        setRecoveredRcId('');

        if (!rcIdName || !rcIdCollegeId || !rcIdMobile) {
            setRcIdError('All fields are required.');
            return;
        }

        setRcIdLoading(true);
        try {
            const result = await recoverRcId(rcIdName, rcIdCollegeId, rcIdMobile);
            setRecoveredRcId(result);
            setRcIdLoading(false);
        } catch (err) {
            setRcIdLoading(false);
            setRcIdError(err.message || 'Failed to recover RC ID.');
        }
    };

    const handleVerifyIdentifiers = async (e) => {
        e.preventDefault();
        setError('');
        setIsMismatch(false);

        const cleanRcId = rcId.trim().toUpperCase();
        const cleanStudentId = studentId.trim().toUpperCase();

        if (!cleanRcId || !cleanStudentId) {
            setError('Please enter both your RGUKT Connect ID and College ID.');
            return;
        }

        setIsLoading(true);

        try {
            // "Perfectly match" verification
            const matchedUser = await verifyIdentifiers(cleanRcId, cleanStudentId);

            if (!matchedUser) {
                setIsMismatch(true);
                setError('Identity mismatch! The provided RC ID and College ID do not match any registered account.');
                setIsLoading(false);
                return;
            }

            // Identification success
            setTargetUser(matchedUser);
            setStep(2); 

            // Verification animation delay
            setTimeout(async () => {
                try {
                    await sendPasswordResetEmail(auth, matchedUser.email);
                    setIsLoading(false);
                    setStep(3); // Move to success step (email sent)
                } catch (emailErr) {
                    setIsLoading(false);
                    setError('Failed to send reset email. Please try again later.');
                }
            }, 1800);

        } catch (err) {
            setIsLoading(false);
            setError('An error occurred during secure verification. Please try again.');
        }
    };

    return (
        <div className={`forget-container ${isMismatch ? 'red-alert-active' : ''}`}>
            <div className="forget-card">
                <div className="forget-branding-wrapper">
                    <Branding size="md" />
                </div>

                {error && (
                    <div className={`forget-error ${isMismatch ? 'error-urgent' : ''}`}>
                        <AlertCircle size={18} />
                        <span>{error}</span>
                    </div>
                )}

                {step === 1 && (
                    <div className="forget-step animate-fade-in">
                        <div className="step-header">
                            <div className="step-icon-wrapper">
                                <ShieldCheck size={28} />
                            </div>
                            <h2>Identity Verification</h2>
                            <p>Verify your account using your unique platform identifiers.</p>
                        </div>

                        <form onSubmit={handleVerifyIdentifiers} className="forget-form" noValidate>
                            <div className="form-group">
                                <label htmlFor="rcId">RGUKT Connect ID</label>
                                <div className="input-wrapper">
                                    <ShieldCheck className="input-icon" size={18} />
                                    <input
                                        type="text"
                                        id="rcId"
                                        name="rc_id_field"
                                        placeholder="RCXXXXXX"
                                        value={rcId}
                                        onChange={(e) => setRcId(e.target.value)}
                                        className={isMismatch ? 'input-error' : ''}
                                        disabled={isLoading}
                                        autoFocus
                                        required
                                        autoComplete="off"
                                    />
                                </div>
                            </div>

                            <div className="form-group">
                                <label htmlFor="studentId">College ID</label>
                                <div className="input-wrapper">
                                    <User className="input-icon" size={18} />
                                    <input
                                        type="text"
                                        id="studentId"
                                        name="student_id_field"
                                        placeholder="RXXXXXX"
                                        value={studentId}
                                        onChange={(e) => setStudentId(e.target.value)}
                                        className={isMismatch ? 'input-error' : ''}
                                        disabled={isLoading}
                                        required
                                        autoComplete="off"
                                    />
                                </div>
                            </div>

                            <button type="submit" className={`forget-btn ${isMismatch ? 'btn-urgent' : ''}`} disabled={isLoading || !rcId || !studentId}>
                                <span>Verify Identity</span>
                                <ArrowRight size={18} />
                            </button>

                            <div className="forget-links" style={{ marginTop: '1rem', display: 'flex', justifyContent: 'center' }}>
                                <button type="button" className="rc-id-recovery-link" onClick={() => setShowRcIdModal(true)}>
                                    Don't know your RC ID?
                                </button>
                            </div>
                        </form>
                    </div>
                )}

                {step === 2 && (
                    <div className="forget-step verifying-step animate-fade-in">
                        <div className="verification-animation">
                            <div className="pulse-ring verify-pulse-1"></div>
                            <div className="pulse-ring verify-pulse-2"></div>
                            <div className="verify-icon">
                                <ShieldCheck size={32} className="text-white" />
                            </div>
                        </div>
                        <h3>Establishing Secure Link</h3>
                        <p>Authenticating credentials for <strong>{targetUser?.fullName}</strong>...</p>
                    </div>
                )}

                {step === 3 && (
                    <div className="forget-step success-step animate-fade-in">
                        <div className="step-icon-wrapper success-icon">
                            <CheckCircle2 size={32} />
                        </div>
                        <h2>Verification Successful</h2>
                        <p style={{ marginTop: '1rem', lineHeight: '1.6' }}>
                            Identity confirmed for <strong>{targetUser?.fullName}</strong>.
                        </p>
                        <div className="forget-success-box" style={{ marginTop: '1.5rem', marginBottom: '1.5rem' }}>
                            <p>We have securely sent a password reset link to your institutional email:</p>
                            <h4 style={{ color: 'var(--color-primary-600)', marginTop: '0.5rem', wordBreak: 'break-all' }}>
                                {targetUser?.email}
                            </h4>
                        </div>
                        <p style={{ fontSize: '0.9rem', color: 'var(--color-text-light)' }}>
                            Please check your inbox and click the link to choose a new password.
                        </p>
                        <button className="forget-btn" onClick={() => navigate('/login')} style={{ marginTop: '2rem' }}>
                            Return to Login
                        </button>
                    </div>
                )}

                {step !== 4 && step !== 2 && (
                    <div className="forget-footer">
                        <Link to="/login" className="back-link">
                            <ArrowLeft size={16} />
                            <span>Back to Login</span>
                        </Link>
                    </div>
                )}
            </div>
            <AppFooter />

            {showRcIdModal && (
                <div className="modal-overlay">
                    <div className="modal-content">
                        <h3>Recover RC ID</h3>
                        <p style={{ fontSize: '0.9rem', color: 'var(--color-text-muted)', marginBottom: '1rem' }}>Enter your details to recover your RGUKT Connect ID.</p>

                        {rcIdError && (
                            <div className="forget-error error-urgent" style={{ marginBottom: '1rem' }}>
                                <AlertCircle size={18} />
                                <span>{rcIdError}</span>
                            </div>
                        )}

                        {recoveredRcId ? (
                            <div className="success-box" style={{ padding: '1rem', background: 'var(--color-success)', color: 'white', borderRadius: 'var(--radius-md)', textAlign: 'center', marginBottom: '1rem' }}>
                                <p>Your RC ID is:</p>
                                <h2 style={{ color: 'white', margin: '0.5rem 0' }}>{recoveredRcId}</h2>
                                <button className="btn btn-secondary" style={{ marginTop: '0.5rem', width: '100%', color: 'var(--color-text-main)' }} onClick={() => {
                                    setRcId(recoveredRcId);
                                    setShowRcIdModal(false);
                                }}>Use this ID</button>
                            </div>
                        ) : (
                            <form onSubmit={handleRecoverRcId}>
                                <div className="form-group" style={{ marginBottom: '1rem' }}>
                                    <label>Student Name</label>
                                    <input type="text" className="input" value={rcIdName} onChange={e => setRcIdName(e.target.value)} required />
                                </div>
                                <div className="form-group" style={{ marginBottom: '1rem' }}>
                                    <label>College ID (RXXXXXX)</label>
                                    <input type="text" className="input" value={rcIdCollegeId} onChange={e => setRcIdCollegeId(e.target.value)} required />
                                </div>
                                <div className="form-group" style={{ marginBottom: '1.5rem' }}>
                                    <label>Mobile Number</label>
                                    <input type="tel" className="input" value={rcIdMobile} onChange={e => setRcIdMobile(e.target.value)} required />
                                </div>
                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                    <button type="button" className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowRcIdModal(false)}>Cancel</button>
                                    <button type="submit" className="btn btn-primary" style={{ flex: 1 }} disabled={rcIdLoading}>
                                        {rcIdLoading ? 'Searching...' : 'Find ID'}
                                    </button>
                                </div>
                            </form>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default ForgetPassword;

import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';
import { useDownload } from '../context/DownloadContext';
import { useNavigate, Navigate, Link } from 'react-router-dom';
import { User, Lock, ArrowRight, ShieldCheck, Mail, AlertCircle, Sun, Moon, Eye, EyeOff, Check, Info, ClipboardList, Sparkle, Sparkles, UserCircle, Trash2, ShieldAlert } from 'lucide-react';
import Branding from '../components/Branding';
import AppFooter from '../components/Common/AppFooter';
import { AutofillService } from '../services/autofillService';
import { nativeAuthService } from '../services/nativeAuthService';
import { Capacitor } from '@capacitor/core';
import './Login.css';

const Login = () => {
    const { login, loginWithGoogle, user, logout } = useAuth();
    const { theme, toggleTheme } = useTheme();
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [isSuccess, setIsSuccess] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState('');
    const [formData, setFormData] = useState({
        email: '',
        password: ''
    });

    // PIN Verification State
    const [showPinModal, setShowPinModal] = useState(false);
    const [pin, setPin] = useState(['', '', '', '', '', '']);
    const [tempUserUid, setTempUserUid] = useState(null);
    const pinInputRefs = React.useRef([]);
    const { verifyPin, verifyFace } = useAuth();

    // Track if admin has verified in this session (local state for now, assuming refresh clears it effectively forces re-login flow on this page)
    // Actually, if we want to force it on every refresh, we just need to NOT redirect if admin until they verify here.
    const [isAdminVerified, setIsAdminVerified] = useState(false);
    const [showAutofillPrompt, setShowAutofillPrompt] = useState(false);
    const [showSavePrompt, setShowSavePrompt] = useState(false);
    const [isSavingSuccess, setIsSavingSuccess] = useState(false);
    const [savedData, setSavedData] = useState([]); // Array of profiles
    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const [profileToDelete, setProfileToDelete] = useState(null);
    const [deletePassword, setDeletePassword] = useState('');
    const [deleteError, setDeleteError] = useState('');
    const [isDeletingSuccess, setIsDeletingSuccess] = useState(false);
    const [isDeletingInProgress, setIsDeletingInProgress] = useState(false);
    const [isDirectLoggingIn, setIsDirectLoggingIn] = useState(false);
    const longPressTimerRef = useRef(null);
    const isLongPressActive = useRef(false);
    const { triggerSuccessFeedback, notify } = useDownload();

    // Force light theme on mobile for login page
    useEffect(() => {
        const isMobile = window.innerWidth < 768;
        if (isMobile) {
            const root = window.document.documentElement;
            const originalTheme = root.getAttribute('data-theme');
            root.setAttribute('data-theme', 'light');
            
            return () => {
                // Restore original theme on unmount
                if (originalTheme) {
                    root.setAttribute('data-theme', originalTheme);
                }
            };
        }
    }, [theme]);

    // Autofill Logic
    useEffect(() => {
        const checkAutofill = async () => {
            const data = await AutofillService.get();
            if (data && data.length > 0) {
                setSavedData(data);
                if (Capacitor.getPlatform() === 'web') {
                    setShowAutofillPrompt(true);
                }
            }
        };
        checkAutofill();
    }, []);

    const applyAutofill = async (profile) => {
        const authenticated = await nativeAuthService.authenticate();
        
        if (authenticated) {
            if (profile && profile.email) {
                // Show dedicated direct login overlay
                setIsDirectLoggingIn(true);
                setShowAutofillPrompt(false);
                
                // Trigger immediate login
                handleLogin(null, profile.email, profile.password, true);
            }
        }
    };

    useEffect(() => {
        // Only auto-redirect if NOT in the middle of a process
        if (user && !showSavePrompt && !isSuccess && !isLoading && !isDirectLoggingIn) {
            // Wait for the full profile to load from Firestore before rejecting
            if (user.loadingProfile) return;

            if (user.role === 'admin') {
                navigate('/admin/dashboard', { replace: true });
            } else {
                logout();
                setError('Access Denied: This portal is exclusively for Administrators.');
            }
        } else if (!user) {
            setShowPinModal(false);
            setIsAdminVerified(false);
        }
    }, [user, navigate, isAdminVerified, showSavePrompt, isSuccess, isLoading, logout]);

    const handleLogin = async (e, directEmail = null, directPassword = null, isAutofill = false) => {
        if (e) e.preventDefault();
        
        const loginEmail = directEmail || formData.email;
        const loginPassword = directPassword || formData.password;

        if (!loginEmail || !loginPassword) return;

        console.log("Login attempt for:", loginEmail);
        setError('');
        setIsLoading(true);

        try {
            const result = await login(loginEmail, loginPassword);
            console.log("Login successful, result user:", result.user.uid);

            // Check if we should show the save prompt BEFORE updating success states
            const profiles = await AutofillService.get();
            // Show prompt if profile doesn't exist OR if password has changed
            const existingProfile = profiles.find(p => p.email.toLowerCase() === loginEmail.toLowerCase());
            const needsSave = !existingProfile || existingProfile.password !== loginPassword;

            if (needsSave) {
                setShowSavePrompt(true);
            }

            setIsLoading(false);
            setIsSuccess(true);

            // Notify user of successful login
            notify('Login Successful ✅', `Welcome back! You are now logged in as ${loginEmail}.`, 'ic_stat_notification');

            if (!needsSave) {
                // Already saved, just clear success delay to let useEffect handle it dynamically based on the fetched user.role
                setTimeout(() => {
                    setIsSuccess(false);
                    if (isAutofill) setIsDirectLoggingIn(false);
                }, 1000);
            }
        } catch (err) {
            console.error("Login catch block error:", err);
            setIsLoading(false);
            if (isAutofill) setIsDirectLoggingIn(false);

            if (isAutofill && (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential')) {
                // Automatically remove the invalid/deleted account from saved data
                const currentProfiles = await AutofillService.get();
                const updatedProfiles = currentProfiles.filter(p => p.email.toLowerCase() !== loginEmail.toLowerCase());
                
                const { Preferences } = await import('@capacitor/preferences');
                await Preferences.set({
                    key: 'rgukt_autofill_data',
                    value: JSON.stringify(updatedProfiles)
                });
                
                setSavedData(updatedProfiles);
                if (updatedProfiles.length === 0) {
                    setShowAutofillPrompt(false);
                }
                
                setError(`Account ${loginEmail} is no longer valid or has been deleted. It has been removed from saved accounts.`);
                return;
            }

            if (loginEmail === 'admin@rguktconnect.ac.in' && (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential')) {
                setError('Admin account not found. Please click "Create Account" below and register as a Student first (you will be auto-elevated to Admin).');
            } else if (err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential') {
                setError('Invalid email or password.');
            } else if (err.code === 'auth/invalid-email') {
                setError('Please provide a valid institutional email.');
            } else {
                setError(`Authentication failed: ${err.code} - ${err.message}`);
            }
        }
    };

    const handleGoogleLogin = async () => {
        setError('');
        setIsLoading(true);
        try {
            await loginWithGoogle();
            setIsLoading(false);
            setIsSuccess(true);
            setTimeout(() => {
                setIsSuccess(false);
            }, 1000);
        } catch (err) {
            console.error("Google login error:", err);
            setError(`Google Sign-In failed: ${err.message || 'Unknown error'}`);
            setIsLoading(false);
        }
    };

    const handlePinChange = (index, value) => {
        if (isNaN(value)) return;
        const newPin = [...pin];
        newPin[index] = value;
        setPin(newPin);

        // Auto-focus next input
        if (value && index < 5) {
            pinInputRefs.current[index + 1].focus();
        }

        // Auto-validate if all digits are filled
        const filledPin = newPin.join('');
        if (filledPin.length === 6) {
            verifyAdminPin(filledPin);
        }
    };

    const handlePinKeyDown = (index, e) => {
        if (e.key === 'Backspace' && !pin[index] && index > 0) {
            pinInputRefs.current[index - 1].focus();
        }
    };

    const verifyAdminPin = async (manualPin = null) => {
        const enteredPin = manualPin || pin.join('');
        if (enteredPin.length < 4) {
            setError('Please enter a valid PIN.');
            return;
        }

        setIsLoading(true);
        const isValid = await verifyPin(tempUserUid, enteredPin);

        if (isValid) {
            setIsLoading(false);
            setIsSuccess(true);
            setTimeout(() => {
                setIsAdminVerified(true);
                navigate('/admin', { replace: true });
            }, 1000);
        } else {
            setError('Incorrect PIN. Please try again.');
            setIsLoading(false);
            setPin(['', '', '', '', '', '']);
            pinInputRefs.current[0]?.focus();
        }
    };



    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
        if (error) setError('');
    };

    const handleSaveConfirm = async () => {
        setIsSavingSuccess(true);
        await AutofillService.save({ 
            email: formData.email,
            password: formData.password, // Save password for full autofill
            avatar: user?.avatar || null // Save profile photo for the selector
        });
        
        // Wait for animation
        setTimeout(() => {
            setShowSavePrompt(false);
            setIsSavingSuccess(false);
            if (isDirectLoggingIn) setIsDirectLoggingIn(false);
            setIsSuccess(false);
        }, 1500);
    };

    const handleSaveDecline = () => {
        setShowSavePrompt(false);
        if (isDirectLoggingIn) setIsDirectLoggingIn(false);
        setIsSuccess(false);
    };

    const handleTouchStart = (e, profile) => {
        isLongPressActive.current = false;
        longPressTimerRef.current = setTimeout(() => {
            isLongPressActive.current = true;
            // Haptic Feedback for long press
            if (window.navigator.vibrate) window.navigator.vibrate(50);
            console.log("Long press detected for:", profile.email);
            handleDeleteRequest(profile);
        }, 600); // 600ms for long press
    };

    const handleTouchEnd = () => {
        if (longPressTimerRef.current) {
            clearTimeout(longPressTimerRef.current);
            longPressTimerRef.current = null;
        }
    };

    const handleDeleteRequest = (profile) => {
        console.log("Showing delete confirmation for:", profile.email);
        setProfileToDelete(profile);
        setShowDeleteConfirm(true);
        setDeletePassword('');
        setDeleteError('');
    };

    const handleConfirmDelete = async () => {
        if (!profileToDelete) return;
        
        if (deletePassword !== profileToDelete.password) {
            setDeleteError('Incorrect password. Please verify your identity.');
            return;
        }

        setIsDeletingInProgress(true);
        
        // Artificial delay for the 2-second deleting animation
        await new Promise(resolve => setTimeout(resolve, 2000));

        setIsDeletingInProgress(false);
        setIsDeletingSuccess(true);
        
        // Remove from storage
        const currentProfiles = await AutofillService.get();
        const updatedProfiles = currentProfiles.filter(p => p.email.toLowerCase() !== profileToDelete.email.toLowerCase());
        
        const { Preferences } = await import('@capacitor/preferences');
        await Preferences.set({
            key: 'rgukt_autofill_data',
            value: JSON.stringify(updatedProfiles)
        });

        // Trigger notification
        notify('Account Removed', `Account ${profileToDelete.email} has been deleted from this device.`, 'ic_stat_notification');

        // Wait for animation
        setTimeout(() => {
            setSavedData(updatedProfiles);
            setIsDeletingSuccess(false);
            setShowDeleteConfirm(false);
            setProfileToDelete(null);
            
            if (updatedProfiles.length === 0) {
                setShowAutofillPrompt(false);
            }
        }, 1500);
    };

    return (
        <div className="login-container">
            {/* Background Pattern & Overlay - Moved logic slightly to CSS for split styling */}

            <div className="login-split-wrapper">
                {/* Visual Banner Side (Desktop Only) */}
                <div className="login-banner-side">
                    <div className="banner-content">
                        <Branding size="xl" className="banner-branding" />
                        <h1 className="banner-title">Welcome back to Your Campus Portal</h1>
                        <p className="banner-subtitle">
                            Access your courses, check grades, and connect with the university community seamlessly through RGUKT CONNECT.
                        </p>
                        
                        <div className="banner-features">
                            <div className="feature-item">
                                <span className="feature-icon"><Check size={16} /></span>
                                <span>Real-time Timetable & Notes</span>
                            </div>
                            <div className="feature-item">
                                <span className="feature-icon"><Check size={16} /></span>
                                <span>Quick Complaint Register</span>
                            </div>
                            <div className="feature-item">
                                <span className="feature-icon"><Check size={16} /></span>
                                <span>Seamless Admin Portal</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Login Form Side */}
                <div className="login-form-side">
                    <div className="login-content">
                        {/* Login Card */}
                        <div className="login-card">
                            <div className="login-card-body">
                                {/* Mobile Branding (Hidden on desktop banner view) */}
                                <div className="mobile-branding-wrapper">
                                    <Branding size="md" variant="auto" />
                                </div>

                                {/* Login Header (Logo removed) */}
                                <div className="login-header" style={{ marginTop: '2rem' }}>
                                    <h1 className="login-title">Welcome Back</h1>
                                    <p className="login-subtitle">Sign in to your institutional account</p>
                                </div>


                        {error && (
                            <div className="animate-fade-in" style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: '0.75rem',
                                padding: '1rem',
                                background: 'rgba(239, 68, 68, 0.1)',
                                border: '1px solid rgba(239, 68, 68, 0.2)',
                                borderRadius: '0.75rem',
                                color: '#ef4444',
                                fontSize: '0.85rem',
                                marginBottom: '1.5rem'
                            }}>
                                <AlertCircle size={18} />
                                <span>{error}</span>
                            </div>
                        )}

                        <form onSubmit={handleLogin} className="space-y-4" noValidate>
                            <div className="login-form-group">
                                <label className="login-label" htmlFor="email">Institutional ID / Email</label>
                                <div className="login-input-wrapper">
                                    <div className="login-input-icon">
                                        <Mail size={18} />
                                    </div>
                                    <input
                                        id="email"
                                        name="email"
                                        type="text"
                                        className="login-input"
                                        placeholder="R240387 or student@rguktrkv.ac.in"
                                        value={formData.email}
                                        onChange={handleChange}
                                        required
                                        style={{ paddingRight: savedData.length > 0 ? '4.5rem' : '12px' }}
                                    />
                                    {savedData.length > 0 && (
                                        <button 
                                            type="button"
                                            className="autofill-trigger-badge"
                                            onClick={() => setShowAutofillPrompt(true)}
                                        >
                                            <UserCircle size={14} />
                                            <span>Saved</span>
                                        </button>
                                    )}
                                </div>
                            </div>

                            <div className="login-form-group">
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                                    <label className="login-label" style={{ marginBottom: 0 }} htmlFor="password">Password</label>
                                    <Link to="/forgot-password" className="login-forgot-link">Forgot password?</Link>
                                </div>
                                <div className="login-input-wrapper" style={{ position: 'relative' }}>
                                    <div className="login-input-icon">
                                        <Lock size={18} />
                                    </div>
                                    <input
                                        id="password"
                                        name="password"
                                        type={showPassword ? "text" : "password"}
                                        className="login-input"
                                        placeholder="••••••••"
                                        value={formData.password}
                                        onChange={handleChange}
                                        style={{ paddingRight: '5rem' }}
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        style={{
                                            position: 'absolute',
                                            right: '10px',
                                            top: '50%',
                                            transform: 'translateY(-50%)',
                                            background: 'none',
                                            border: 'none',
                                            cursor: 'pointer',
                                            color: 'var(--color-slate-400)',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            padding: '4px'
                                        }}
                                        aria-label={showPassword ? "Hide password" : "Show password"}
                                    >
                                        {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                                    </button>
                                </div>
                            </div>

                            <button
                                type="submit"
                                className="login-btn"
                                disabled={isLoading}
                            >
                                {isLoading ? (
                                    <span style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                        <span className="animate-spin" style={{ border: '2px solid white', borderTopColor: 'transparent', borderRadius: '50%', width: '1rem', height: '1rem' }}></span>
                                        Signing in...
                                    </span>
                                ) : (
                                    <>
                                        <span>Sign In securely</span>
                                        <ArrowRight size={18} />
                                    </>
                                )}
                            </button>









                            <div className="login-divider">
                                <span>or continue with</span>
                            </div>

                            <button
                                type="button"
                                className="google-login-btn"
                                onClick={handleGoogleLogin}
                                disabled={isLoading}
                            >
                                <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" />
                                <span>Sign In with Google</span>
                            </button>
                        </form>
                    </div>

                    <div className="login-footer-bar">
                        <span style={{ fontSize: '0.85rem', color: 'var(--color-slate-500)', fontWeight: '500' }}>Don't have an account?</span>
                        <Link to="/register" className="login-footer-btn">Create Account</Link>
                    </div>
                </div>

                {/* Comprehensive Footer */}
                        <AppFooter />
            </div>

            {/* PIN Verification Modal */}
            {showPinModal && (
                <div className="auth-modal-overlay">
                    <div className="auth-modal-content">
                        {isSuccess ? (
                            <div className="success-animation-container">
                                <div className="success-wrapper-horizontal">
                                    <div className="checkmark-circle">
                                        <svg className="w-12 h-12 text-[var(--color-slate-900)]" viewBox="0 0 24 24">
                                            <path className="checkmark-svg" d="M20 6L9 17L4 12" style={{ stroke: 'currentColor' }} />
                                        </svg>
                                    </div>
                                    <div className="sparkles-side-container">
                                        <div className="sparkle-accent ss1"><Sparkle size={14} fill="currentColor" /></div>
                                        <div className="sparkle-accent ss2"><Sparkles size={22} fill="currentColor" /></div>
                                        <div className="sparkle-accent ss3"><Sparkle size={12} fill="currentColor" /></div>
                                    </div>
                                </div>
                                <h3 className="success-text">Verified!</h3>
                                <p className="success-subtext">Redirecting to dashboard...</p>
                            </div>
                        ) : (
                            <>
                                <div className="text-center mb-6">
                                    <div className="auth-modal-icon-wrapper">
                                        <Lock size={32} />
                                    </div>
                                    <h3 className="auth-modal-title">Admin Verification</h3>
                                    <p className="auth-modal-desc">
                                        Please enter your 6-digit PIN to continue.
                                    </p>
                                </div>

                                <div className="pin-input-container">
                                    {pin.map((digit, index) => (
                                        <input
                                            key={index}
                                            ref={el => pinInputRefs.current[index] = el}
                                            type="password"
                                            maxLength={1}
                                            className="pin-input-field"
                                            value={digit}
                                            onChange={(e) => handlePinChange(index, e.target.value)}
                                            onKeyDown={(e) => handlePinKeyDown(index, e)}
                                            autoFocus={index === 0}
                                        />
                                    ))}
                                </div>

                                {error && (
                                    <div className="mb-6 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-red-600 dark:text-red-400 text-sm text-center flex items-center justify-center gap-2">
                                        <AlertCircle size={16} />
                                        {error}
                                    </div>
                                )}

                                <button
                                    onClick={verifyAdminPin}
                                    className="login-btn"
                                    style={{ marginBottom: '1rem' }}
                                    disabled={isLoading}
                                >
                                    {isLoading ? 'Verifying...' : 'Verify Access'}
                                </button>
                            </>
                        )}
                    </div>
                </div>
            )}


        </div>
        </div>

            {/* Direct Login Overlay */}
            {isDirectLoggingIn && (
                <div className="direct-login-overlay animate-fade-in">
                    <div className="direct-login-content">
