                            {[
                                { name: 'Vibrant Red', hex: '#ff0000' },
                                { name: 'Neon Blue', hex: '#00f3ff' },
                                { name: 'Cyber Purple', hex: '#8b5cf6' },
                                { name: 'Emerald Green', hex: '#10b981' },
                                { name: 'Sunset Orange', hex: '#f97316' },
