import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X, Gift } from 'lucide-react';
import './BirthdayPopup.css';

const BirthdayPopup = ({ user }) => {
    const [isVisible, setIsVisible] = useState(false);

    useEffect(() => {
        if (!user || !user.dob) return;

        try {
            const today = new Date();
            const currentYear = today.getFullYear();
            const currentMonth = today.getMonth() + 1; // 1-12
            const currentDay = today.getDate();

            // dob is expected in 'YYYY-MM-DD' format
            const dobParts = user.dob.split('-');
            if (dobParts.length !== 3) return;

            const dobMonth = parseInt(dobParts[1], 10);
            const dobDay = parseInt(dobParts[2], 10);

            // Check if today is the user's birthday
            if (currentMonth === dobMonth && currentDay === dobDay) {
                const sessionKey = `hasShownBirthdaySession_${user.uid || user.id}`;
                if (!sessionStorage.getItem(sessionKey)) {
                    setIsVisible(true);
                    sessionStorage.setItem(sessionKey, 'true');
                }
            }
        } catch (error) {
            console.error("Error checking birthday:", error);
        }
    }, [user]);

    useEffect(() => {
        let audio;
        let playAudioHandler;

        if (isVisible) {
            document.body.classList.add('hide-bottom-nav');

            try {
                audio = new Audio('https://cdn.pixabay.com/download/audio/2022/11/22/audio_d1718ab41b.mp3');
                audio.volume = 0.6;

                let isPlaying = false;

                playAudioHandler = () => {
                    if (!isPlaying && audio) {
                        audio.play().then(() => {
                            isPlaying = true;
                            document.removeEventListener('click', playAudioHandler);
                            document.removeEventListener('touchstart', playAudioHandler);
                        }).catch(e => console.log('Audio blocked:', e));
                    }
                };

                // Try autoplay first
                audio.play().then(() => {
                    isPlaying = true;
                }).catch(() => {
                    // If autoplay is blocked by browser policy, wait for first interaction
                    document.addEventListener('click', playAudioHandler);
                    document.addEventListener('touchstart', playAudioHandler);
                });

            } catch (error) {
                console.error('Error playing audio:', error);
            }

            return () => {
                document.body.classList.remove('hide-bottom-nav');
                if (audio) {
                    audio.pause();
                    audio.currentTime = 0;
                }
                if (playAudioHandler) {
                    document.removeEventListener('click', playAudioHandler);
                    document.removeEventListener('touchstart', playAudioHandler);
                }
            };
        }
    }, [isVisible]);

    if (!isVisible) return null;

    const displayName = user?.fullName || user?.name || 'Student';

    return createPortal(
        <div className="birthday-popup-overlay">
            <div className="birthday-popup-content">
                <button className="birthday-close-btn" onClick={() => setIsVisible(false)}>
                    <X size={18} />
                </button>

                {/* Confetti Elements */}
                <div className="confetti-piece"></div>
                <div className="confetti-piece"></div>
                <div className="confetti-piece"></div>
                <div className="confetti-piece"></div>
                <div className="confetti-piece"></div>

                <div className="birthday-icon-wrapper">
                    <Gift size={40} className="icon" />
                </div>

                <h2 className="birthday-title">Happy Birthday!</h2>
                <p className="birthday-message">
                    Wishing you a fantastic day, <strong>{displayName}</strong>! May this year bring you closer to your goals. Have a great celebration! 🎉
                </p>

                <button className="birthday-btn" onClick={() => setIsVisible(false)}>
                    Thank You!
                </button>
            </div>
        </div>,
        document.body
    );
};

export default BirthdayPopup;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Award, X, Download, Share2, ChevronRight, TrendingUp, BookOpen, GraduationCap, Loader2 } from 'lucide-react';
import { pdfService } from '../../services/pdfService';
import { Filesystem, Directory } from '@capacitor/filesystem';
import { Share as CapacitorShare } from '@capacitor/share';
import { Capacitor } from '@capacitor/core';
import './CgpaModal.css';

const LOGO_DATA_URI = `data:image/svg+xml;base64,   PGxpbmVhckdyYWRpZW50IGlkPSJwYWludDBfbGluZWFyIiB4MT0iMCIgeTE9IjAiIHgyPSI1MTIiIHkyPSI1MTIiIGdyYWRpZW50VW5pdHM9InVzZXJTcGFjZU9uVXNlIj4KICAgICAgPHN0b3Agc3RvcC1jb2xvcj0iIzRmNDZlNSIvPgogICAgICA8c3RvcCBvZmZzZXQ9IjEiIHN0b3AtY29sb3I9IiMzNzMwYTMiLz4KICAgIDwvbGluZWFyR3JhZGllbnQ+CiAgPC9kZWZzPgo8L3N2Zz4=`;

const svgToPng = (svgDataUri) => {
    return new Promise((resolve) => {
        const img = new Image();
        const timeout = setTimeout(() => resolve(null), 3000);
        img.onload = () => {
            clearTimeout(timeout);
            try {
                const canvas = document.createElement('canvas');
                canvas.width = img.width;
                canvas.height = img.height;
                const ctx = canvas.getContext('2d');
                ctx.drawImage(img, 0, 0);
                resolve(canvas.toDataURL('image/png'));
            } catch (e) {
                resolve(null);
            }
        };
        img.onerror = () => {
            clearTimeout(timeout);
            resolve(null);
        };
        img.src = svgDataUri;
    });
};

const createInitialsAvatar = async (name) => {
    const initials = name ? name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase() : 'ST';
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200"><rect width="200" height="200" fill="#3b82f6" /><text x="100" y="100" font-family="Arial, sans-serif" font-size="80" fill="white" font-weight="bold" text-anchor="middle" dominant-baseline="central">${initials}</text></svg>`;
    return await svgToPng(`data:image/svg+xml;base64,${btoa(svg)}`);
};

const urlToBase64 = async (url, fallbackName) => {
    if (!url) {
        if (fallbackName) return await createInitialsAvatar(fallbackName);
        return null;
    }
    if (url.startsWith('data:')) return url;

    const convertBlobToJpegBase64 = (blob) => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.onload = () => {
                const img = new Image();
                img.onload = () => {
                    try {
                        const canvas = document.createElement('canvas');
                        const maxDim = 400;
                        const scale = Math.min(1, maxDim / Math.max(img.width, img.height));
                        canvas.width = img.width * scale;
                        canvas.height = img.height * scale;
                        const ctx = canvas.getContext('2d');
                        ctx.fillStyle = '#ffffff';
                        ctx.fillRect(0, 0, canvas.width, canvas.height);
                        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
                        resolve(canvas.toDataURL('image/jpeg', 0.8));
                    } catch (e) {
                        resolve(reader.result); 
                    }
                };
                img.onerror = () => resolve(null);
                img.src = reader.result;
            };
            reader.onerror = () => resolve(null);
            reader.readAsDataURL(blob);
        });
    };

    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error('Fetch failed');
        const blob = await response.blob();
        const base64 = await convertBlobToJpegBase64(blob);
        if (base64) return base64;
        throw new Error('Conversion failed');
    } catch (e) {
        try {
            const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`;
            const response = await fetch(proxyUrl);
            if (!response.ok) throw new Error('Proxy failed');
            const blob = await response.blob();
            const base64 = await convertBlobToJpegBase64(blob);
            if (base64) return base64;
            throw new Error('Proxy conversion failed');
        } catch (err) {
            if (fallbackName) return await createInitialsAvatar(fallbackName);
            return null;
        }
    }
};


const CgpaModal = ({ isOpen, onClose, cgpaValue = '0.00', cgpaRecord = null, studentId = '', user = null }) => {
    const [isRendered, setIsRendered] = useState(false);
    const [isVisible, setIsVisible] = useState(false);
    const [animatedCgpa, setAnimatedCgpa] = useState(0);

    const cgpaNum = parseFloat(cgpaValue) || 0;
    const maxCgpa = 10.0;
    const progressPercentage = (cgpaNum / maxCgpa) * 100;

    let performanceBadge = { label: 'Average', color: 'text-orange-500', bg: 'bg-orange-500/10' };
    if (cgpaNum >= 8.5) performanceBadge = { label: 'Excellent', color: 'text-green-500', bg: 'bg-green-500/10' };
    else if (cgpaNum >= 7.0) performanceBadge = { label: 'Good', color: 'text-blue-500', bg: 'bg-blue-500/10' };

    const totalCredits = cgpaRecord?.subjects?.reduce((acc, curr) => acc + (parseInt(curr.credits) || 0), 0) || 0;
    const sgpaValue = cgpaRecord?.sgpa || '0.00';

    const [actionLoading, setActionLoading] = useState(null);

    useEffect(() => {
        if (isOpen) {
            setIsRendered(true);
            setTimeout(() => {
                setIsVisible(true);
                document.body.style.overflow = 'hidden';
                document.body.classList.add('hide-bottom-nav');

                // Animate CGPA Number
                let start = 0;
                const duration = 1500; // ms
                const increment = cgpaNum / (duration / 16);
                const timer = setInterval(() => {
                    start += increment;
                    if (start >= cgpaNum) {
                        setAnimatedCgpa(cgpaNum);
                        clearInterval(timer);
                    } else {
                        setAnimatedCgpa(start);
                    }
                }, 16);

                return () => clearInterval(timer);
            }, 10);

            const handleKeyDown = (e) => {
                if (e.key === 'Escape') {
                    handleClose();
                }
            };
            window.addEventListener('keydown', handleKeyDown);

            return () => {
                window.removeEventListener('keydown', handleKeyDown);
            };
        } else {
            setIsVisible(false);
            document.body.style.overflow = '';
            document.body.classList.remove('hide-bottom-nav');
            setTimeout(() => setIsRendered(false), 300); // match transition duration
        }
    }, [isOpen, cgpaNum]);

    const handleClose = () => {
        setIsVisible(false);
        setTimeout(() => onClose(), 300);
    };

    const handleAction = async (actionType) => {
        if (!cgpaRecord) return;
        setActionLoading(actionType);
        try {
            const pngLogo = await svgToPng(LOGO_DATA_URI);
            const userMock = user || { studentId: studentId }; 

            // Get base64 avatar
            let base64Avatar = await urlToBase64(user?.avatar, userMock.fullName);

            const doc = await pdfService.generateAcademicReportPdf(cgpaRecord, userMock, pngLogo, base64Avatar);

            const filename = `${studentId || 'Student'}_Academic_Report.pdf`;

            if (Capacitor.isNativePlatform()) {
                const pdfBase64 = doc.output('datauristring').split(',')[1];

                if (actionType === 'share') {
                    const fileResult = await Filesystem.writeFile({
                        path: filename,
                        data: pdfBase64,
                        directory: Directory.Cache
                    });
                    await CapacitorShare.share({
                        title: 'Academic Performance Report',
                        text: `Sharing Academic Report for ${studentId || 'Student'}`,
                        url: fileResult.uri,
                    });
                } else {
                    await Filesystem.writeFile({
                        path: filename,
                        data: pdfBase64,
                        directory: Directory.Documents
                    });
                    alert(`Report saved to Documents folder!`);
                }
            } else {
                if (actionType === 'share' && navigator.share) {
                    const blob = doc.output('blob');
                    const file = new File([blob], filename, { type: 'application/pdf' });
                    try {
                        await navigator.share({
                            files: [file],
                            title: 'Academic Report',
                        });
                    } catch(err) {
                        doc.save(filename);
                    }
                } else {
                    doc.save(filename);
                }
            }
        } catch (e) {
            console.error('Failed to process PDF', e);
            alert('Failed to process PDF. Please try again.');
        } finally {
            setActionLoading(null);
        }
    };

    if (!isRendered) return null;

    return createPortal(
        <div className={`cgpa-modal-overlay ${isVisible ? 'visible' : ''}`} onClick={handleClose}>
            <div className={`cgpa-modal-content ${isVisible ? 'visible' : ''}`} onClick={e => e.stopPropagation()}>

                <button className="cgpa-close-btn" onClick={handleClose}>
                    <X size={20} />
                </button>

                <div className="cgpa-modal-header">
                    <div className="cgpa-icon-wrapper floating-icon">
                        <GraduationCap size={32} className="text-purple-500" />
                    </div>
                    <h2>Current CGPA</h2>
                    <p>Academic Performance</p>
                </div>

                <div className="cgpa-progress-section">
                    <div className="cgpa-ring-container">
                        <svg className="cgpa-progress-ring" width="160" height="160">
                            <circle
                                className="cgpa-ring-bg"
                                cx="80" cy="80" r="70"
                            />
                            <circle
                                className="cgpa-ring-fill"
                                cx="80" cy="80" r="70"
                                style={{ strokeDashoffset: isVisible ? `calc(440 - (440 * ${progressPercentage}) / 100)` : 440 }}
                            />
                        </svg>
                        <div className="cgpa-ring-content">
                            <span className="cgpa-number glow-text">{animatedCgpa.toFixed(2)}</span>
                            <span className="cgpa-max">/ 10.0</span>
                        </div>
                    </div>

                    <div className={`cgpa-badge ${performanceBadge.bg} ${performanceBadge.color}`}>
                        {performanceBadge.label}
                    </div>
                </div>



                <div className="w-full">
                    {cgpaRecord?.subjects?.length > 0 ? (
                        (() => {
                            let currentGroup = 'PUC-1 (Sem-1)';
                            const groupedSubjects = { 
                                'PUC-1 (Sem-1)': [], 
                                'PUC-1 (Sem-2)': [], 
                                'PUC-2 (Sem-1)': [], 
                                'PUC-2 (Sem-2)': [] 
                            };

                            cgpaRecord.subjects.forEach(s => {
                                if (s.semester) {
                                    if (s.semester === 'P1S1') currentGroup = 'PUC-1 (Sem-1)';
                                    else if (s.semester === 'P1S2') currentGroup = 'PUC-1 (Sem-2)';
                                    else if (s.semester === 'P2S1') currentGroup = 'PUC-2 (Sem-1)';
                                    else if (s.semester === 'P2S2') currentGroup = 'PUC-2 (Sem-2)';
                                } else {
                                    const name = (s.subject || '').toUpperCase().trim();
                                    const match = name.match(/-(I|II|III|IV)$/);
                                    if (match) {
                                        const numeral = match[1];
                                        if (numeral === 'I') currentGroup = 'PUC-1 (Sem-1)';
                                        else if (numeral === 'II') currentGroup = 'PUC-1 (Sem-2)';
                                        else if (numeral === 'III') currentGroup = 'PUC-2 (Sem-1)';
                                        else if (numeral === 'IV') currentGroup = 'PUC-2 (Sem-2)';
                                    }
                                }
                                groupedSubjects[currentGroup].push(s);
                            });

                            return ['PUC-1 (Sem-1)', 'PUC-1 (Sem-2)', 'PUC-2 (Sem-1)', 'PUC-2 (Sem-2)'].map(groupName => (
                                groupedSubjects[groupName].length > 0 && (
                                    <div key={groupName} className="cgpa-semesters-section mb-6">
                                        <h3 className="text-lg font-bold mb-4">{groupName} Subjects</h3>
                                        <div className="cgpa-sem-list">
                                            {groupedSubjects[groupName].map((s, i) => (
                                                <div key={i} className="cgpa-sem-item flex-col items-start gap-1 p-3 border-b border-gray-100 last:border-0">
                                                    <div className="flex justify-between w-full">
                                                        <span className="sem-name font-semibold">{s.subject}</span>
                                                        <span className="sem-gpa font-bold">{s.grade}</span>
                                                    </div>
                                                    <div className="flex justify-between w-full text-xs text-gray-500 mt-1">
                                                        <span>Credits: {s.credits} | CGPA: {s.grp}</span>
                                                        <span>Internal: {s.internal} | {s.status}</span>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                        <div className="mt-3 bg-slate-50 border border-slate-200 rounded-lg p-3 flex justify-between items-center text-sm font-bold text-slate-700">
                                            <div className="flex gap-2 items-center">
                                                <span className="text-slate-500 font-medium">Credits:</span>
                                                <span className="text-slate-800">{groupedSubjects[groupName].reduce((sum, s) => sum + (parseInt(s.credits) || 0), 0)}</span>
                                            </div>
                                            <div className="flex gap-4">
                                                <div className="flex gap-2 items-center">
                                                    <span className="text-slate-500 font-medium">SGPA:</span>
                                                    <span className="text-blue-600">{groupedSubjects[groupName][0]?.sgpa || '0.00'}</span>
                                                </div>
                                                <div className="flex gap-2 items-center">
                                                    <span className="text-slate-500 font-medium">CGPA:</span>
                                                    <span className="text-purple-600">{groupedSubjects[groupName][0]?.cgpa || '0.00'}</span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                )
                            ));
                        })()
                    ) : (
                        <div className="text-center text-sm text-gray-500 py-4">
                            No detailed subject records found for student ID: {studentId || 'Unknown'}
                        </div>
                    )}
                </div>

                <div className="cgpa-actions flex flex-col gap-3">
                    <button className="cgpa-btn-primary ripple w-full m-0" onClick={handleClose}>
                        Done <ChevronRight size={16} />
                    </button>

                    <div className="flex gap-3 w-full">
                        <button 
                            className="cgpa-btn-secondary ripple flex-1 flex justify-center items-center gap-2 m-0" 
                            onClick={() => handleAction('share')}
                            disabled={actionLoading !== null}
                        >
                            {actionLoading === 'share' ? <Loader2 size={18} className="animate-spin" /> : <Share2 size={18} />}
                            {actionLoading === 'share' ? 'Sharing...' : 'Share'}
                        </button>
                        <button 
                            className="cgpa-btn-secondary ripple flex-1 flex justify-center items-center gap-2 m-0" 
                            onClick={() => handleAction('download')}
                            disabled={actionLoading !== null}
                        >
                            {actionLoading === 'download' ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
                            {actionLoading === 'download' ? 'Downloading...' : 'Download'}
                        </button>
                    </div>
                </div>

                <div className="cgpa-footer">
                    Last updated: {new Date().toLocaleDateString()}
                </div>
            </div>
        </div>,
        document.body
    );
};

export default CgpaModal;

