import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { X, Check } from 'lucide-react';
import './HeaderAnimationSheet.css';

const ANIMATIONS = [
    { id: 'none', name: 'None', description: 'Clean professional look' },
    { id: 'theme-flow', name: 'Theme Flow', description: 'Primary to secondary shift' },
    { id: 'soft-pulse', name: 'Soft Pulse', description: 'Gentle breathing border' },
    { id: 'progress-sweep', name: 'Progress Sweep', description: 'Fluid movement streak' },
    { id: 'dash-motion', name: 'Dash Motion', description: 'Clockwise tech dashes' },
    { id: 'glow-edge', name: 'Glow Edge', description: 'Subtle primary highlight' },
    { id: 'wave-motion', name: 'Wave Motion', description: 'Animated gradient wave' },
    { id: 'dual-tone', name: 'Dual Tone Line', description: 'Alternating theme colors' },
    { id: 'corner-pulse', name: 'Corner Pulse', description: 'Soft corner highlights' },
    { id: 'minimal-blink', name: 'Minimal Blink', description: 'Subtle periodic glow' },
    { id: 'liquid-filling', name: 'Liquid Filling', description: 'Fluid rhythmic rising' },
    { id: 'binary-pulse', name: 'Binary Pulse', description: 'Digital stepping dashes' },
    { id: 'crystal-sweep', name: 'Crystal Sweep', description: 'Sharp primary theme paths' },
    { id: 'prism-edge', name: 'Prism Edge', description: 'Multi-tone gradient flow' },
    { id: 'soft-silhouette', name: 'Soft Silhouette', description: 'Deep inner-glow effect' }
];

const HeaderAnimationSheet = ({ isOpen, onClose, currentId, onSelect }) => {
    const [shouldRender, setShouldRender] = useState(isOpen);
    const [isClosing, setIsClosing] = useState(false);
    const [isExpanded, setIsExpanded] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setShouldRender(true);
            setIsClosing(false);
            setIsExpanded(false); // Reset on open
        } else if (shouldRender) {
            setIsClosing(true);
            const timer = setTimeout(() => {
                setShouldRender(false);
                setIsClosing(false);
            }, 400);
            return () => clearTimeout(timer);
        }
    }, [isOpen, shouldRender]);

    if (!shouldRender) return null;

    const visibleAnimations = isExpanded ? ANIMATIONS : ANIMATIONS.slice(0, 4);

    const sheetContent = (
        <div className={`animation-sheet-overlay ${isClosing ? 'is-closing' : ''}`} onClick={onClose}>
            <div 
                className={`animation-sheet-content ${isClosing ? 'animate-slide-down' : 'animate-slide-up'} ${isExpanded ? 'is-expanded' : ''}`} 
                onClick={e => e.stopPropagation()}
            >
                <div className="sheet-grabber"></div>

                <header className="sheet-header">
                    <div className="title-box">
                        <h3>Choose<br/>Border</h3>
                        <p>Personalize your<br/>dashboard experience</p>
                    </div>
                    <div className="header-actions">
                        <button className="close-btn" onClick={onClose}>
                            <X size={20} />
                        </button>
                    </div>
                </header>

                <div className={`animations-grid ${isExpanded ? 'expanded-flow' : ''}`}>
                    {visibleAnimations.map((anim) => (
                        <button 
                            key={anim.id}
                            className={`anim-option-card ${currentId === anim.id ? 'is-selected' : ''}`}
                            onClick={() => onSelect(anim.id)}
                        >
                            <div className="anim-preview-box">
                                <div className={`preview-border ${anim.id}`}></div>
                                {currentId === anim.id && (
                                    <div className="selected-badge">
                                        <Check size={12} />
                                    </div>
                                )}
                            </div>
                            <div className="anim-info">
                                <span className="anim-name">{anim.name}</span>
                                <span className="anim-desc">{anim.description}</span>
                            </div>
                        </button>
                    ))}
                    {!isExpanded && ANIMATIONS.length > 4 && (
                        <button className="view-all-small" onClick={(e) => {
                            e.stopPropagation();
                            setIsExpanded(true);
                        }}>
                            View All {ANIMATIONS.length - 4}
                        </button>
                    )}
                </div>

                <div className="sheet-footer">
                    <button className="apply-btn" onClick={onClose}>Done</button>
                </div>
            </div>
        </div>
    );

    return createPortal(sheetContent, document.body);
};

export default HeaderAnimationSheet;

import React from 'react';

class ErrorBoundary extends React.Component {
    constructor(props) {
        super(props);
        this.state = { hasError: false, error: null, errorInfo: null };
    }

    static getDerivedStateFromError(error) {
        return { hasError: true };
    }

    componentDidCatch(error, errorInfo) {
        console.error("Uncaught error:", error, errorInfo);
        this.setState({ error, errorInfo });
    }

    render() {
        if (this.state.hasError) {
            return (
                <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-red-50 text-red-900">
                    <h1 className="text-2xl font-bold mb-4">Something went wrong.</h1>
                    <p className="mb-2">There was an error in the application.</p>
                    <pre className="bg-white p-4 rounded shadow text-sm overflow-auto max-w-full">
                        {this.state.error && this.state.error.toString()}
                    </pre>
                    <button
                        onClick={() => window.location.reload()}
                        className="mt-6 px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700"
                    >
                        Reload Application
                    </button>
                </div>
            );
        }

        return this.props.children;
    }
}

export default ErrorBoundary;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { db, bulkUploadDb } from '../../config/firebase';
import { doc, getDoc } from 'firebase/firestore';
import { Clock, Calendar, PieChart, User, Users, MapPin, GraduationCap, X, TrendingUp, Info, Download, Share2, ChevronRight, AlertCircle } from 'lucide-react';
import { formatAttendancePercent, normalizeAttendanceValue } from '../../utils/formatUtils';
import './AttendanceBottomSheet.css';

const AttendanceBottomSheet = ({ isOpen, onClose, user }) => {
    const [attendance, setAttendance] = useState(null);
    const [loading, setLoading] = useState(false);
    const [shouldRender, setShouldRender] = useState(isOpen);
    const [isClosing, setIsClosing] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setShouldRender(true);
            setIsClosing(false);
            fetchAttendance();
        } else if (shouldRender) {
            setIsClosing(true);
            const timer = setTimeout(() => {
                setShouldRender(false);
                setIsClosing(false);
            }, 400);
            return () => clearTimeout(timer);
        }
    }, [isOpen, shouldRender]);

    const fetchAttendance = async () => {
        setLoading(true);
        if (!user?.studentId) {
            setLoading(false);
            return;
        }
        try {
            const id = user.studentId.toUpperCase().replace(/^RGUKT-/i, '').trim();
            const docSnap = await getDoc(doc(bulkUploadDb, 'attendance_rates', id));
            if (docSnap.exists()) {
                setAttendance(docSnap.data());
            }
        } catch (error) {
            console.error("Error fetching attendance:", error);
        } finally {
            setLoading(false);
        }
    };

    if (!shouldRender) return null;

    const { consolidated = 0, totalConducted = 0, totalPresent = 0, className = 'N/A', campus = 'N/A', group = 'N/A', gender = 'N/A', name = 'N/A', studentId = 'N/A', updatedAt } = attendance || {};
    const normalizedConsolidated = normalizeAttendanceValue(consolidated);
    const absentCount = totalConducted - totalPresent;
    const attendanceColor = normalizedConsolidated >= 75 ? '#10b981' : normalizedConsolidated >= 65 ? '#f59e0b' : '#ef4444';

    const sheetContent = (
        <div className={`attendance-sheet-overlay ${isClosing ? 'is-closing' : ''}`} onClick={onClose}>
            <div 
                className={`attendance-sheet-content ${isClosing ? 'animate-slide-down' : 'animate-slide-up'}`} 
                onClick={e => e.stopPropagation()}
            >
                <div className="attendance-sheet-grabber"></div>

                <header className="attendance-sheet-header">
                    <div className="header-title-box">
                        <div className="icon-circle">
                            <PieChart size={20} />
                        </div>
                        <div className="text-box">
                            <h3>Full Attendance Report</h3>
                            <p>Official records from university portal</p>
                        </div>
                    </div>
                    <button className="close-circle-btn" onClick={onClose}>
                        <X size={20} />
                    </button>
                </header>

                <div className="attendance-sheet-body">
                    {loading ? (
                        <div className="sheet-loading-state">
                            <div className="sheet-loader"></div>
                            <p>Fetching your records...</p>
                        </div>
                    ) : attendance ? (
                        <div className="sheet-data-container animate-fade-in">
                            {/* Main Progress Card */}
                            <div className="sheet-main-card" style={{ '--accent-color': attendanceColor }}>
                                <div className="circular-progress-box">
                                    <svg viewBox="0 0 100 100">
                                        <circle className="bg" cx="50" cy="50" r="45" />
                                        <circle 
                                            className="progress" 
                                            cx="50" cy="50" r="45" 
                                            style={{ 
                                                strokeDasharray: '283',
                                                strokeDashoffset: 283 - (283 * normalizedConsolidated) / 100,
                                                stroke: attendanceColor
                                            }} 
                                        />
                                    </svg>
                                    <div className="progress-value-box">
                                        <span className="value bungee-regular">{formatAttendancePercent(consolidated)}</span>
                                        <span className="label">Consolidated</span>
                                    </div>
                                </div>

                                <div className="quick-stats-grid">
                                    <div className="q-stat">
                                        <span className="q-val">{formatAttendancePercent(totalPresent)}</span>
                                        <span className="q-lab">Present</span>
                                    </div>
                                    <div className="q-divider"></div>
                                    <div className="q-stat">
                                        <span className="q-val">{formatAttendancePercent(absentCount)}</span>
                                        <span className="q-lab">Absent</span>
                                    </div>
                                    <div className="q-divider"></div>
                                    <div className="q-stat">
                                        <span className="q-val">{formatAttendancePercent(totalConducted)}</span>
                                        <span className="q-lab">Total</span>
                                    </div>
                                </div>
                            </div>

                            {/* Section: Profile */}
                            <div className="sheet-section">
                                <div className="section-title">
                                    <User size={14} />
                                    <span>Personal Information</span>
                                </div>
                                <div className="sheet-info-list">
                                    <div className="info-row">
                                        <div className="info-details">
                                            <span className="info-label">Full Name</span>
                                            <span className="info-value">{name}</span>
                                        </div>
                                        <div className="info-details text-right">
                                            <span className="info-label">Gender</span>
                                            <span className="info-value">{gender}</span>
                                        </div>
                                    </div>
                                    <div className="info-row">
                                        <div className="info-details">
                                            <span className="info-label">Student ID</span>
                                            <span className="info-value">{studentId}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Section: Academic */}
                            <div className="sheet-section">
                                <div className="section-title">
                                    <GraduationCap size={14} />
                                    <span>Academic Context</span>
                                </div>
                                <div className="sheet-info-list">
                                    <div className="info-row">
                                        <div className="info-details">
                                            <span className="info-label">Class & Section</span>
                                            <span className="info-value">{className}</span>
                                        </div>
                                        <div className="info-details text-right">
                                            <span className="info-label">Group</span>
                                            <span className="info-value">{group}</span>
                                        </div>
                                    </div>
                                    <div className="info-row">
                                        <div className="info-details">
                                            <span className="info-label">Campus</span>
                                            <span className="info-value">{campus}</span>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Footer Status & Update Time */}
                            <div className="sheet-footer-box">
                                <div className="sheet-footer-notice" style={{ backgroundColor: `${attendanceColor}10`, color: attendanceColor }}>
                                    <AlertCircle size={14} />
                                    <span>{normalizedConsolidated >= 75 ? 'Qualified for semester examinations.' : 'Shortage of attendance detected.'}</span>
                                </div>
                                {updatedAt && (
                                    <p className="sheet-update-ts">
                                        Last updated: {updatedAt.toDate().toLocaleDateString()} at {updatedAt.toDate().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </p>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div className="sheet-empty-state">
                            <Info size={40} opacity={0.3} />
                            <p>No attendance records found for your ID.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );

    return createPortal(sheetContent, document.body);
};

export default AttendanceBottomSheet;

import React, { useState, useEffect } from 'react';
import { Outlet, useLocation, NavLink, useNavigate } from 'react-router-dom';
import { LogOut } from 'lucide-react';
// import { Menu, Sun, Moon, Bell } from 'lucide-react'; // Unused custom icons removed
import { useTheme } from '../../context/ThemeContext';
import { useAuth } from '../../context/AuthContext';
import Sidebar from './Sidebar';
import BottomNav from './BottomNav';
import RCBookHubNav from './RCBookHubNav';
import ProfileBottomSheet from './ProfileBottomSheet';
import LogoutConfirm from '../Common/LogoutConfirm';
import AppFooter from '../Common/AppFooter';
import './Sidebar.css';

const Layout = () => {
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [isCollapsed, setIsCollapsed] = useState(true); // Default to collapsed
    const [isProfileSheetOpen, setIsProfileSheetOpen] = useState(false);
    const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
    const [scrolled, setScrolled] = useState(false);
    const { theme, toggleTheme } = useTheme();
    const { user, logout, setIntentionalLogout } = useAuth();
    const location = useLocation();
    const navigate = useNavigate();

    useEffect(() => {
        const handleScroll = () => {
            setScrolled(window.scrollY > 15);
        };
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    const isContentPage = location.pathname.includes('/courses/') && 
                         (location.pathname.split('/').filter(Boolean).length >= 5); // /courses/:year/:sem/:sub/:unit (length 5 after filter)
                         
    const showNav = user !== null && location.pathname !== '/';

    const handleLogoutConfirm = async () => {
        try {
            setIntentionalLogout(true);
            await logout();
            navigate('/login');
        } catch (error) {
            console.error("Logout failed:", error);
            setIsLogoutModalOpen(false);
        }
    };

    return (
        <div className={`app-layout ${!showNav ? 'no-sidebar' : isCollapsed ? 'sidebar-collapsed' : ''} overflow-x-hidden min-h-screen`}>
