            {/* Main Content Area */}
            <div className={`main-content flex-1 flex flex-col min-w-0 transition-all duration-300 relative ${showNav ? 'md:pb-0' : ''}`}>
                
                {/* Dashboard Top Branding Bar */}
                {showNav && location.pathname === '/dashboard' && (
                    <>
                        <div className="dashboard-appbar">
