import React, { useState, useEffect } from 'react';
import QRCode from 'react-qr-code';
import { useAuth } from '../../context/AuthContext';
import { initiateQRSession, listenToQRSession, provideEncryptedCredentials } from '../../services/qrAuthService';
import { db } from '../../config/firebase';
import { doc, getDoc } from 'firebase/firestore';
import { QrCode, Smartphone, CheckCircle, AlertCircle, X, RefreshCw } from 'lucide-react';
import './QRAuth.css';

const QRGenerator = ({ onClose }) => {
    const { user } = useAuth();
    const [sessionData, setSessionData] = useState(null);
    const [status, setStatus] = useState('generating'); // generating, ready, scanned, success, expired, error
    const [errorMessage, setErrorMessage] = useState('');
    const [timeLeft, setTimeLeft] = useState(120); // 2 minutes

    useEffect(() => {
        if (user?.uid) {
            generateSession();
        }
        return () => {
            // Unsubscribe happens implicitly on component unmount if we stored the fn, 
            // but we handle expiration in the service anyway.
        };
    }, [user]);

    useEffect(() => {
        let timer;
        if (status === 'ready' && timeLeft > 0) {
            timer = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
        } else if (timeLeft === 0 && status === 'ready') {
            setStatus('expired');
        }
        return () => clearInterval(timer);
    }, [status, timeLeft]);

    const generateSession = async () => {
        try {
            setStatus('generating');
            setTimeLeft(120);
            const data = await initiateQRSession(user.uid);
            setSessionData(data);
            setStatus('ready');

            // Start listening
            listenToQRSession(data.sessionId, () => handleScanned(data), () => setStatus('expired'));
        } catch (err) {
            console.error(err);
            setErrorMessage("Failed to initiate secure session.");
            setStatus('error');
        }
    };

    const handleScanned = async (currentSessionData) => {
        setStatus('scanned');
        try {
            // Fetch credentials to encrypt and pass
            const userDoc = await getDoc(doc(db, 'users', user.uid));
            const userData = userDoc.data();

            if (!userData.password) {
                throw new Error("Missing password payload. Please log out and back in once to initialize your credential sync, or login manually on your mobile.");
            }

            const credentials = {
                email: userData.email,
                password: userData.password
            };

            await provideEncryptedCredentials(currentSessionData.sessionId, currentSessionData.encryptionKey, credentials);
            setStatus('success');

            setTimeout(() => {
                if (onClose) onClose();
            }, 3000);
        } catch (err) {
            console.error("Payload execution failed:", err);
            setErrorMessage(err.message);
            setStatus('error');
        }
    };

    return (
        <div className="qr-generator-container">
            <div className="qr-header">
                <h2>Cross-Device Login</h2>
                {onClose && (
                    <button className="qr-close-btn" onClick={onClose}>
                        <X size={20} />
                    </button>
                )}
            </div>

            <div className="qr-body">
                {status === 'generating' && (
                    <div className="qr-loading">
                        <RefreshCw className="animate-spin" size={32} />
                        <p>Generating Secure Session...</p>
                    </div>
                )}

                {status === 'ready' && sessionData && (
                    <div className="qr-ready-state">
                        <div className="qr-code-wrapper animate-fade-in">
                            <QRCode
                                value={sessionData.qrString}
                                size={220}
                                level="H"
                                fgColor="#1e293b"
                                bgColor="#ffffff"
                            />
                            <div className="qr-logo-overlay">
                                <img src="/logo.svg" alt="Logo" className="w-6 h-6 object-contain" />
                            </div>
                        </div>
                        <p className="qr-instruction">
                            Scan this code with your mobile device to log in instantly.
                        </p>
                        <div className="qr-timer">
                            Expires in {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
                        </div>
                    </div>
                )}

                {status === 'scanned' && (
                    <div className="qr-loading animate-fade-in text-blue-600">
                        <Smartphone className="animate-bounce" size={48} />
                        <p className="font-semibold mt-4">Device Connected!</p>
                        <p className="text-sm opacity-75">Transferring secure session...</p>
                    </div>
                )}

                {status === 'success' && (
                    <div className="qr-success animate-fade-in text-green-600">
                        <CheckCircle size={48} />
                        <p className="font-semibold mt-4">Login Transferred!</p>
                        <p className="text-sm opacity-75">You are now logged in on your mobile device.</p>
                    </div>
                )}

                {status === 'expired' && (
                    <div className="qr-expired animate-fade-in text-gray-500">
                        <AlertCircle size={48} />
                        <p className="font-semibold mt-4">Session Expired</p>
                        <button className="btn btn-secondary mt-4" onClick={generateSession}>
                            <RefreshCw size={16} /> Generate New Code
                        </button>
                    </div>
                )}

                {status === 'error' && (
                    <div className="qr-error animate-fade-in text-red-500">
                        <AlertCircle size={48} />
                        <p className="font-semibold mt-4">Transfer Failed</p>
                        <p className="text-sm opacity-75 mt-2 px-6 text-center">{errorMessage || "Could not authenticate the mobile device."}</p>
                        <button className="btn btn-secondary mt-4 w-full" style={{ justifyContent: 'center' }} onClick={generateSession}>
                            Try Again
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default QRGenerator;

import React, { useState, useEffect, useRef } from 'react';
import { Html5Qrcode } from 'html5-qrcode';
import { markSessionAsScanned, awaitAuthenticationPayload } from '../../services/qrAuthService';
import { useAuth } from '../../context/AuthContext';
import { X, Loader2, AlertCircle, CheckCircle } from 'lucide-react';
import './QRAuth.css';

const QRScanner = ({ onClose, onSuccess }) => {
    const { login } = useAuth();
    const [status, setStatus] = useState('initializing'); // initializing, scanning, processing, success, error
    const [errorMessage, setErrorMessage] = useState('');
    const [html5QrCode, setHtml5QrCode] = useState(null);
    const isProcessingRef = useRef(false);

    useEffect(() => {
        const scanner = new Html5Qrcode("reader-container");
        setHtml5QrCode(scanner);

        const config = { fps: 10, qrbox: { width: 250, height: 250 }, aspectRatio: 1.0 };

        scanner.start(
            { facingMode: "environment" },
            config,
            handleScanSuccess,
            handleScanError
        ).then(() => {
            setStatus('scanning');
        }).catch((err) => {
            console.error("Camera start error:", err);
            setStatus('error');
            setErrorMessage("Camera access denied or unavailable.");
            try {
                scanner.clear();
            } catch (e) {
                console.error("Error clearing scanner on catch:", e);
            }
        });

        return () => {
            if (scanner) {
                try {
                    if (scanner.isScanning) {
                        scanner.stop().then(() => {
                            scanner.clear();
                        }).catch(console.error);
                    } else {
                        scanner.clear();
                    }
                } catch (e) {
                    console.error("Error during scanner cleanup:", e);
                }
            }
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const handleScanSuccess = async (decodedText) => {
        if (!decodedText.startsWith('rgukt-qr-login|')) return;
        if (isProcessingRef.current) return;

        isProcessingRef.current = true;

        // Stop scanning immediately
        if (html5QrCode) {
            try {
                if (html5QrCode.isScanning) {
                    html5QrCode.stop().then(() => {
                        html5QrCode.clear();
                    }).catch(console.error);
                } else {
                    html5QrCode.clear();
                }
            } catch (e) {
                console.error("Error stopping scanner on success:", e);
            }
        }

        try {
            setStatus('processing');
            const [, sessionId, encryptionKey] = decodedText.split('|');

            // Signal to Desktop that we have scanned it
            await markSessionAsScanned(sessionId);

            // Wait for Desktop to encrypt and upload the payload
            awaitAuthenticationPayload(
                sessionId,
                encryptionKey,
                async (credentials) => {
                    try {
                        const email = credentials.email;
                        const password = credentials.credentials?.password || credentials.password;

                        await login(email, password);

                        // Only show success after Firebase returns OK
                        setStatus('success');

                        // Wait a moment so the user can see the success animation jumping
                        setTimeout(() => {
                            if (onSuccess) onSuccess();
                        }, 2000);

                    } catch (loginErr) {
                        setStatus('error');
                        setErrorMessage(loginErr.message || "Authentication failed with provided credentials.");
                        isProcessingRef.current = false;
                    }
                },
                (err) => {
                    setStatus('error');
                    setErrorMessage(err.message || "Failed to decrypt secure payload.");
                    isProcessingRef.current = false;
                }
            );

        } catch (err) {
            setStatus('error');
            setErrorMessage(err.message);
            isProcessingRef.current = false;
        }
    };

    const handleScanError = (error) => {
        // Ignored. html5-qrcode fires this continuously on every failed frame.
    };

    return (
        <div className="qr-scanner-container">
            <div className="qr-header">
                <h2>Scan to Login</h2>
                <button className="qr-close-btn flex-shrink-0" onClick={onClose}>
                    <X size={20} />
                </button>
            </div>

            <div className="qr-body" style={{ minHeight: '350px' }}>
                <div style={{ position: 'relative', width: '100%', maxWidth: '300px', margin: '0 auto', display: (status === 'initializing' || status === 'scanning') ? 'block' : 'none' }}>
                    <div id="reader-container" style={{ width: '100%', borderRadius: '1rem', overflow: 'hidden' }}></div>
                    {status === 'initializing' && (
                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-[var(--color-surface)] z-10" style={{ borderRadius: '1rem' }}>
                            <Loader2 className="animate-spin text-[var(--color-primary-500)] mb-2" size={32} />
                            <p className="text-sm">Requesting Camera...</p>
                        </div>
                    )}
                    <p className="qr-instruction mt-4 text-center">
                        Point your camera at the Desktop QR code.
                    </p>
                </div>

                {status === 'processing' && (
                    <div className="qr-loading animate-fade-in flex flex-col items-center py-8">
                        <Loader2 className="animate-spin text-[var(--color-primary-500)]" size={48} />
                        <p className="font-semibold mt-6 text-lg">Authenticating...</p>
                        <p className="text-sm opacity-75 mt-2">Connecting secure session...</p>
                    </div>
                )}

                {status === 'success' && (
                    <div className="qr-success animate-fade-in flex flex-col items-center py-8 text-green-600">
                        <CheckCircle size={56} />
                        <p className="font-bold mt-6 text-xl">Login Successful!</p>
                        <p className="text-sm text-gray-600 mt-2">Redirecting to Dashboard...</p>
                    </div>
                )}

                {status === 'error' && (
                    <div className="qr-error animate-fade-in flex flex-col items-center py-8 text-red-500">
                        <AlertCircle size={56} />
                        <p className="font-bold mt-6 text-xl">Scan Failed</p>
                        <p className="text-sm opacity-80 mt-2 px-6 text-center">{errorMessage || "An unknown error occurred."}</p>
                        <button
                            onClick={onClose}
                            className="uiverse-back-btn w-full"
                        >
                            <div className="svg-wrapper">
                                <svg
                                    xmlns="http://www.w3.org/2000/svg"
                                    viewBox="0 0 1024 1024"
                                >
                                    <path
                                        d="M224 480h640a32 32 0 1 1 0 64H224a32 32 0 0 1 0-64z"
                                    ></path>
                                    <path
                                        d="m237.248 512 265.408 265.344a32 32 0 0 1-45.312 45.312l-288-288a32 32 0 0 1 0-45.312l288-288a32 32 0 1 1 45.312 45.312L237.248 512z"
                                    ></path>
                                </svg>
                            </div>
                            <p>Go Back</p>
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

export default QRScanner;

