                    email: firebaseUser.email,
                    fullName: firebaseUser.displayName || 'Loading...',
                    avatar: firebaseUser.photoURL || `https://ui-avatars.com/api/?name=${firebaseUser.displayName || 'User'}&background=0D8ABC&color=fff`,
