                                                try {
                                                    const attRef = doc(bulkUploadDb, 'attendance_rates', idToSearch);
                                                    const attSnap = await getDoc(attRef);
                                                    if (attSnap.exists()) {
                                                        autoBranch = attSnap.data().group || '';
