export const ToastProvider = ({ children }) => {
    const [toast, setToast] = useState({ visible: false, message: '', type: 'success', id: null });
    const [pendingDeletion, setPendingDeletion] = useState(null);
    const toastTimerRef = useRef(null);
    const deleteTimerRef = useRef(null);

    const showToast = useCallback((message, type = 'success') => {
        if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
        const id = Date.now();
        setToast({ visible: true, message, type, id });

        if (type !== 'undo') {
            toastTimerRef.current = setTimeout(() => {
                setToast(prev => ({ ...prev, visible: false }));
            }, 3500);
        }
    }, []);

    const showUndoToast = useCallback((message, itemData, onRestore) => {
        if (deleteTimerRef.current) clearTimeout(deleteTimerRef.current);
        if (toastTimerRef.current) clearTimeout(toastTimerRef.current);

        const id = Date.now();
        setPendingDeletion({ ...itemData, onRestore });
        setToast({ visible: true, message, type: 'undo', id });

        deleteTimerRef.current = setTimeout(async () => {
            try {
                if (itemData.collection && itemData.docId) {
                    await deleteDoc(doc(db, itemData.collection, itemData.docId));
                }
                setPendingDeletion(null);
                setToast(prev => prev.id === id ? { ...prev, visible: false } : prev);
            } catch (error) {
                console.error("Error finalizing deletion:", error);
                showToast("Failed to permanently delete item.", "error");
            }
        }, 10000);
    }, [showToast]);

    const handleUndo = useCallback(() => {
        if (!pendingDeletion) return;
        if (deleteTimerRef.current) clearTimeout(deleteTimerRef.current);
        if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
        const { onRestore, name } = pendingDeletion;
        if (onRestore) onRestore(pendingDeletion);
        setPendingDeletion(null);
        setToast({ visible: false, message: '', type: 'success', id: null });
        showToast(`Restored ${name || 'item'}`);
    }, [pendingDeletion, showToast]);

    const hideToast = useCallback(() => {
        setToast(prev => ({ ...prev, visible: false }));
    }, []);

    const config = TOAST_CONFIG[toast.type] || TOAST_CONFIG.success;
    const Icon = config.icon;

    return (
        <ToastContext.Provider value={{ showToast, showUndoToast, handleUndo, hideToast, toast }}>
            {children}

            {/* Premium Global Toast */}
            <div className="toast-container" aria-live="polite">
                <div className={`premium-toast ${toast.visible ? 'visible' : ''}`}
                    style={{ '--toast-accent': config.accent, '--toast-glow': config.glow, '--toast-light-bg': config.lightBg }}
                >
                    {/* Left accent bar */}
                    <div className="toast-accent-bar" style={{ background: config.gradient }} />

                    {/* Icon */}
                    <div className="toast-icon-wrap" style={{ background: config.lightBg }}>
                        <Icon size={20} style={{ color: config.accent }} strokeWidth={2.5} />
                    </div>

                    {/* Content */}
                    <div className="toast-body">
                        <span className="toast-label" style={{ color: config.accent }}>{config.label}</span>
                        <p className="toast-msg">{toast.message}</p>
                    </div>

                    {/* Undo button */}
                    {toast.type === 'undo' && (
                        <button className="toast-undo-btn" onClick={handleUndo}>
                            <RotateCcw size={13} />
                            Undo
                        </button>
                    )}

                    {/* Close */}
                    <button className="toast-close-btn" onClick={hideToast} aria-label="Close notification">
                        <X size={15} />
                    </button>

                    {/* Progress bar */}
                    {toast.visible && (
                        <div
                            className={`toast-progress ${toast.type === 'undo' ? 'undo-progress' : ''}`}
                            style={{ background: config.gradient }}
                        />
                    )}
                </div>
            </div>
        </ToastContext.Provider>
    );
};

export const useToast = () => {
    const context = useContext(ToastContext);
    if (!context) throw new Error('useToast must be used within a ToastProvider');
    return context;
};

import React, { useState, useRef } from 'react';
import { UploadCloud, FileText, X, AlertCircle, CheckCircle, Loader2 } from 'lucide-react';
import { pdfService } from '../../services/pdfService';
import { useAuth } from '../../context/AuthContext';
import './PdfUpload.css';

// Replace this with your actual Google Apps Script Web App URL after deploying
const GAS_WEB_APP_URL = "https://script.google.com/macros/s/AKfycbz_REPLACE_WITH_YOUR_URL/exec";

const PdfUpload = () => {
    const { user } = useAuth();
    const [isUploading, setIsUploading] = useState(false);
    const [uploadStatus, setUploadStatus] = useState({ type: '', message: '' });

    const [formData, setFormData] = useState({
        title: '',
        branch: 'BTech',
        year: 'Year 1',
        semester: 'Semester 1',
        subject: '',
        module: '',
        description: '',
        pdfUrl: ''
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleUpload = async (e) => {
        e.preventDefault();

        if (!formData.pdfUrl) {
            setUploadStatus({ type: 'error', message: 'Please provide a PDF URL.' });
            return;
        }

        if (!formData.title || !formData.subject) {
            setUploadStatus({ type: 'error', message: 'Please fill in all required metadata fields.' });
            return;
        }

        setIsUploading(true);
        setUploadStatus({ type: 'info', message: 'Saving metadata to database...' });

        try {
            const pdfMetadata = {
                ...formData,
                fileSize: 0,
                fileType: 'application/pdf',
                uploadedBy: user ? user.uid : 'admin',
                googleDriveFileId: '',
                googleDriveViewLink: formData.pdfUrl,
                googleDriveDownloadLink: formData.pdfUrl
            };

            await pdfService.uploadPdfMetadata(pdfMetadata);

            setUploadStatus({ type: 'success', message: 'PDF link successfully saved and indexed!' });

            // Reset form after 3 seconds
            setTimeout(() => {
                setFormData({
                    title: '',
                    branch: 'BTech',
                    year: 'Year 1',
                    semester: 'Semester 1',
                    subject: '',
                    module: '',
                    description: '',
                    pdfUrl: ''
                });
                setIsUploading(false);
                setUploadStatus({ type: '', message: '' });
            }, 3000);

        } catch (error) {
            console.error("Upload error: ", error);
            setUploadStatus({ type: 'error', message: error.message || 'Failed to save PDF metadata.' });
            setIsUploading(false);
        }
    };

    return (
        <div className="pdf-upload-container animate-fade-in">
            <div className="pdf-upload-header">
                <h1 className="pdf-upload-title">Add New PDF Link</h1>
                <p className="pdf-upload-subtitle">Add new learning materials to the student library by providing a direct link.</p>
            </div>

            <div className="pdf-upload-card">
                {!isUploading ? (
                    <>
                        {/* Status Message */}
                        {uploadStatus.message && (
                            <div className={`mb-6 p-4 rounded-xl flex items-center gap-3 ${
                                uploadStatus.type === 'error' ? 'bg-red-50 text-red-600 border border-red-200' :
                                uploadStatus.type === 'success' ? 'bg-emerald-50 text-emerald-600 border border-emerald-200' :
                                'bg-blue-50 text-blue-600 border border-blue-200'
                            }`}>
                                {uploadStatus.type === 'error' && <AlertCircle size={20} />}
                                {uploadStatus.type === 'success' && <CheckCircle size={20} />}
                                <span>{uploadStatus.message}</span>
                            </div>
                        )}

                        {/* Metadata Form */}
                        <form onSubmit={handleUpload}>
                            <div className="metadata-grid">
                                <div className="form-group full-width">
                                    <label className="form-label">PDF URL / Link *</label>
                                    <input 
                                        type="url" 
                                        className="form-input" 
                                        name="pdfUrl"
                                        value={formData.pdfUrl}
                                        onChange={handleChange}
                                        placeholder="https://example.com/file.pdf or Google Drive link"
                                        required 
                                    />
                                </div>

                                <div className="form-group full-width">
                                    <label className="form-label">Document Title *</label>
                                    <input 
                                        type="text" 
                                        className="form-input" 
                                        name="title"
                                        value={formData.title}
                                        onChange={handleChange}
                                        placeholder="E.g., Engineering Physics Unit 1"
                                        required 
                                    />
                                </div>

                                <div className="form-group">
                                    <label className="form-label">Branch *</label>
                                    <select className="form-select" name="branch" value={formData.branch} onChange={handleChange}>
                                        <option value="PUC">PUC</option>
                                        <option value="BTech">BTech (Common)</option>
                                        <option value="CSE">CSE</option>
                                        <option value="ECE">ECE</option>
                                        <option value="EEE">EEE</option>
                                        <option value="Civil">Civil</option>
                                        <option value="Mechanical">Mechanical</option>
                                        <option value="Chemical">Chemical</option>
                                        <option value="MME">MME</option>
                                    </select>
                                </div>

                                <div className="form-group">
                                    <label className="form-label">Academic Year *</label>
                                    <select className="form-select" name="year" value={formData.year} onChange={handleChange}>
                                        <option value="Year 1">Year 1</option>
                                        <option value="Year 2">Year 2</option>
                                        <option value="Year 3">Year 3</option>
                                        <option value="Year 4">Year 4</option>
                                    </select>
                                </div>

                                <div className="form-group">
                                    <label className="form-label">Semester *</label>
                                    <select className="form-select" name="semester" value={formData.semester} onChange={handleChange}>
                                        <option value="Semester 1">Semester 1</option>
                                        <option value="Semester 2">Semester 2</option>
                                    </select>
                                </div>

                                <div className="form-group">
                                    <label className="form-label">Subject *</label>
                                    <input 
                                        type="text" 
                                        className="form-input" 
                                        name="subject"
                                        value={formData.subject}
