        { id: 'under_review', label: 'Under Review', icon: Search, color: '#8b5cf6' }, // Purple
        { id: 'in_progress', label: 'In Progress', icon: Settings, color: '#06b6d4' }, // Cyan
        { id: 'resolved', label: 'Resolved', icon: ShieldCheck, color: '#10b981' }, // Emerald
