import React from 'react';
import LoadingTransition from '../components/Common/LoadingTransition';
import Branding from '../components/Branding';
import { FileText, AlertCircle, Download, CheckCircle, GraduationCap, ClipboardList, Zap, Share2, Search, MapPin, Bookmark, User as UserIcon, Calendar, Clock, Loader2 } from 'lucide-react';
