                                    <button className="clear-search-btn" onClick={() => { setSeatingSearchId(''); setSeatingResults([]); setHasSearched(false); }}>
                                        &times;
                                    </button>
                                )}
                            </div>
                            <button className="seating-search-btn-v2" onClick={() => handleSearchSeating(seatingSearchId)}>
