  return (
    <div className="faculty-dashboard-container">
      {/* Header section */}
      <div className="faculty-header">
        <div className="faculty-title-wrapper">
          <h1>Faculty Portal</h1>
          <p>Welcome back, Prof. {user?.fullName || 'Faculty'}</p>
