import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { ArrowLeft, ArrowRight, CheckCircle2, ShieldCheck, AlertCircle, User, Fingerprint } from 'lucide-react';
import { sendPasswordResetEmail } from 'firebase/auth';
import { auth } from '../config/firebase';
import Branding from '../components/Branding';
import AppFooter from '../components/Common/AppFooter';
import { useAuth } from '../context/AuthContext';
import './ForgetPassword.css';

const ForgetPassword = () => {
    const [step, setStep] = useState(1); // 1: IDs, 2: Verifying, 3: Success (Email Sent)
    const [rcId, setRcId] = useState('');
    const [studentId, setStudentId] = useState('');
    const [targetUser, setTargetUser] = useState(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [isMismatch, setIsMismatch] = useState(false);

    const { verifyIdentifiers, recoverRcId } = useAuth();
    const navigate = useNavigate();

    const [showRcIdModal, setShowRcIdModal] = useState(false);
    const [rcIdName, setRcIdName] = useState('');
    const [rcIdCollegeId, setRcIdCollegeId] = useState('');
    const [rcIdMobile, setRcIdMobile] = useState('');
    const [recoveredRcId, setRecoveredRcId] = useState('');
    const [rcIdError, setRcIdError] = useState('');
    const [rcIdLoading, setRcIdLoading] = useState(false);

    // Clear mismatch state when typing
    useEffect(() => {
        if (isMismatch) setIsMismatch(false);
    }, [rcId, studentId]);

    const handleRecoverRcId = async (e) => {
        e.preventDefault();
        setRcIdError('');
        setRecoveredRcId('');

        if (!rcIdName || !rcIdCollegeId || !rcIdMobile) {
            setRcIdError('All fields are required.');
            return;
        }

        setRcIdLoading(true);
        try {
            const result = await recoverRcId(rcIdName, rcIdCollegeId, rcIdMobile);
            setRecoveredRcId(result);
            setRcIdLoading(false);
        } catch (err) {
            setRcIdLoading(false);
            setRcIdError(err.message || 'Failed to recover RC ID.');
        }
    };

    const handleVerifyIdentifiers = async (e) => {
        e.preventDefault();
        setError('');
        setIsMismatch(false);

        const cleanRcId = rcId.trim().toUpperCase();
        const cleanStudentId = studentId.trim().toUpperCase();

        if (!cleanRcId || !cleanStudentId) {
            setError('Please enter both your RGUKT Connect ID and College ID.');
            return;
        }

        setIsLoading(true);

        try {
            // "Perfectly match" verification
            const matchedUser = await verifyIdentifiers(cleanRcId, cleanStudentId);

            if (!matchedUser) {
                setIsMismatch(true);
                setError('Identity mismatch! The provided RC ID and College ID do not match any registered account.');
                setIsLoading(false);
                return;
            }

            // Identification success
            setTargetUser(matchedUser);
            setStep(2); 

            // Verification animation delay
            setTimeout(async () => {
                try {
                    await sendPasswordResetEmail(auth, matchedUser.email);
                    setIsLoading(false);
                    setStep(3); // Move to success step (email sent)
                } catch (emailErr) {
                    setIsLoading(false);
                    setError('Failed to send reset email. Please try again later.');
                }
            }, 1800);

        } catch (err) {
            setIsLoading(false);
            setError('An error occurred during secure verification. Please try again.');
        }
    };

    return (
        <div className={`forget-container ${isMismatch ? 'red-alert-active' : ''}`}>
            <div className="forget-card">
                <div className="forget-branding-wrapper">
                    <Branding size="md" />
                </div>

                {error && (
                    <div className={`forget-error ${isMismatch ? 'error-urgent' : ''}`}>
                        <AlertCircle size={18} />
                        <span>{error}</span>
                    </div>
                )}

                {step === 1 && (
                    <div className="forget-step animate-fade-in">
                        <div className="step-header">
                            <div className="step-icon-wrapper">
                                <ShieldCheck size={28} />
                            </div>
                            <h2>Identity Verification</h2>
                            <p>Verify your account using your unique platform identifiers.</p>
                        </div>

                        <form onSubmit={handleVerifyIdentifiers} className="forget-form" noValidate>
                            <div className="form-group">
                                <label htmlFor="rcId">RGUKT Connect ID</label>
                                <div className="input-wrapper">
                                    <ShieldCheck className="input-icon" size={18} />
                                    <input
                                        type="text"
                                        id="rcId"
                                        name="rc_id_field"
                                        placeholder="RCXXXXXX"
                                        value={rcId}
                                        onChange={(e) => setRcId(e.target.value)}
                                        className={isMismatch ? 'input-error' : ''}
                                        disabled={isLoading}
                                        autoFocus
                                        required
                                        autoComplete="off"
                                    />
                                </div>
                            </div>

                            <div className="form-group">
                                <label htmlFor="studentId">College ID</label>
                                <div className="input-wrapper">
                                    <User className="input-icon" size={18} />
                                    <input
                                        type="text"
                                        id="studentId"
                                        name="student_id_field"
                                        placeholder="RXXXXXX"
                                        value={studentId}
                                        onChange={(e) => setStudentId(e.target.value)}
                                        className={isMismatch ? 'input-error' : ''}
                                        disabled={isLoading}
                                        required
                                        autoComplete="off"
                                    />
                                </div>
                            </div>

                            <button type="submit" className={`forget-btn ${isMismatch ? 'btn-urgent' : ''}`} disabled={isLoading || !rcId || !studentId}>
                                <span>Verify Identity</span>
                                <ArrowRight size={18} />
                            </button>

                            <div className="forget-links" style={{ marginTop: '1rem', display: 'flex', justifyContent: 'center' }}>
                                <button type="button" className="rc-id-recovery-link" onClick={() => setShowRcIdModal(true)}>
                                    Don't know your RC ID?
                                </button>
                            </div>
                        </form>
                    </div>
                )}

                {step === 2 && (
                    <div className="forget-step verifying-step animate-fade-in">
                        <div className="verification-animation">
                            <div className="pulse-ring verify-pulse-1"></div>
                            <div className="pulse-ring verify-pulse-2"></div>
                            <div className="verify-icon">
                                <ShieldCheck size={32} className="text-white" />
                            </div>
                        </div>
                        <h3>Establishing Secure Link</h3>
                        <p>Authenticating credentials for <strong>{targetUser?.fullName}</strong>...</p>
                    </div>
                )}

                {step === 3 && (
                    <div className="forget-step success-step animate-fade-in">
                        <div className="step-icon-wrapper success-icon">
                            <CheckCircle2 size={32} />
                        </div>
                        <h2>Verification Successful</h2>
                        <p style={{ marginTop: '1rem', lineHeight: '1.6' }}>
                            Identity confirmed for <strong>{targetUser?.fullName}</strong>.
                        </p>
                        <div className="forget-success-box" style={{ marginTop: '1.5rem', marginBottom: '1.5rem' }}>
                            <p>We have securely sent a password reset link to your institutional email:</p>
                            <h4 style={{ color: 'var(--color-primary-600)', marginTop: '0.5rem', wordBreak: 'break-all' }}>
                                {targetUser?.email}
                            </h4>
                        </div>
                        <p style={{ fontSize: '0.9rem', color: 'var(--color-text-light)' }}>
                            Please check your inbox and click the link to choose a new password.
                        </p>
                        <button className="forget-btn" onClick={() => navigate('/login')} style={{ marginTop: '2rem' }}>
                            Return to Login
                        </button>
                    </div>
                )}

                {step !== 4 && step !== 2 && (
                    <div className="forget-footer">
                        <Link to="/login" className="back-link">
                            <ArrowLeft size={16} />
                            <span>Back to Login</span>
                        </Link>
                    </div>
                )}
            </div>
            <AppFooter />

            {showRcIdModal && (
                <div className="modal-overlay">
                    <div className="modal-content">
                        <h3>Recover RC ID</h3>
                        <p style={{ fontSize: '0.9rem', color: 'var(--color-text-muted)', marginBottom: '1rem' }}>Enter your details to recover your RGUKT Connect ID.</p>

                        {rcIdError && (
                            <div className="forget-error error-urgent" style={{ marginBottom: '1rem' }}>
                                <AlertCircle size={18} />
                                <span>{rcIdError}</span>
                            </div>
                        )}

                        {recoveredRcId ? (
                            <div className="success-box" style={{ padding: '1rem', background: 'var(--color-success)', color: 'white', borderRadius: 'var(--radius-md)', textAlign: 'center', marginBottom: '1rem' }}>
                                <p>Your RC ID is:</p>
                                <h2 style={{ color: 'white', margin: '0.5rem 0' }}>{recoveredRcId}</h2>
                                <button className="btn btn-secondary" style={{ marginTop: '0.5rem', width: '100%', color: 'var(--color-text-main)' }} onClick={() => {
                                    setRcId(recoveredRcId);
                                    setShowRcIdModal(false);
                                }}>Use this ID</button>
                            </div>
                        ) : (
                            <form onSubmit={handleRecoverRcId}>
                                <div className="form-group" style={{ marginBottom: '1rem' }}>
                                    <label>Student Name</label>
                                    <input type="text" className="input" value={rcIdName} onChange={e => setRcIdName(e.target.value)} required />
                                </div>
                                <div className="form-group" style={{ marginBottom: '1rem' }}>
                                    <label>College ID (RXXXXXX)</label>
                                    <input type="text" className="input" value={rcIdCollegeId} onChange={e => setRcIdCollegeId(e.target.value)} required />
                                </div>
                                <div className="form-group" style={{ marginBottom: '1.5rem' }}>
                                    <label>Mobile Number</label>
                                    <input type="tel" className="input" value={rcIdMobile} onChange={e => setRcIdMobile(e.target.value)} required />
                                </div>
                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                    <button type="button" className="btn btn-secondary" style={{ flex: 1 }} onClick={() => setShowRcIdModal(false)}>Cancel</button>
                                    <button type="submit" className="btn btn-primary" style={{ flex: 1 }} disabled={rcIdLoading}>
                                        {rcIdLoading ? 'Searching...' : 'Find ID'}
                                    </button>
                                </div>
                            </form>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default ForgetPassword;

import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';
import { useDownload } from '../context/DownloadContext';
import { useNavigate, Navigate, Link } from 'react-router-dom';
import { User, Lock, ArrowRight, ShieldCheck, Mail, AlertCircle, Sun, Moon, Eye, EyeOff, Check, Info, ClipboardList, Sparkle, Sparkles, UserCircle, Trash2, ShieldAlert } from 'lucide-react';
import Branding from '../components/Branding';
import AppFooter from '../components/Common/AppFooter';
import { AutofillService } from '../services/autofillService';
import { nativeAuthService } from '../services/nativeAuthService';
import { Capacitor } from '@capacitor/core';
import LoadingTransition from '../components/Common/LoadingTransition';
import './Login.css';

const Login = () => {
    const { login, loginWithGoogle, user, logout } = useAuth();
    const { theme, toggleTheme } = useTheme();
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [isSuccess, setIsSuccess] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState('');
    const [formData, setFormData] = useState({
        email: '',
        password: ''
    });

    // PIN Verification State
    const [showPinModal, setShowPinModal] = useState(false);
    const [pin, setPin] = useState(['', '', '', '', '', '']);
    const [tempUserUid, setTempUserUid] = useState(null);
    const pinInputRefs = React.useRef([]);
    const { verifyPin, verifyFace } = useAuth();

    // Track if admin has verified in this session (local state for now, assuming refresh clears it effectively forces re-login flow on this page)
    // Actually, if we want to force it on every refresh, we just need to NOT redirect if admin until they verify here.
    const [isAdminVerified, setIsAdminVerified] = useState(false);
    const [showAutofillPrompt, setShowAutofillPrompt] = useState(false);
    const [showSavePrompt, setShowSavePrompt] = useState(false);
    const [isSavingSuccess, setIsSavingSuccess] = useState(false);
    const [savedData, setSavedData] = useState([]); // Array of profiles
    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const [profileToDelete, setProfileToDelete] = useState(null);
    const [deletePassword, setDeletePassword] = useState('');
    const [deleteError, setDeleteError] = useState('');
    const [isDeletingSuccess, setIsDeletingSuccess] = useState(false);
    const [isDeletingInProgress, setIsDeletingInProgress] = useState(false);
    const [isDirectLoggingIn, setIsDirectLoggingIn] = useState(false);
    const longPressTimerRef = useRef(null);
    const isLongPressActive = useRef(false);
    const { triggerSuccessFeedback, notify } = useDownload();

    // Force dark theme on login page
    useEffect(() => {
        const root = window.document.documentElement;
        const originalTheme = root.getAttribute('data-theme');
        const hadDarkClass = root.classList.contains('dark');
        
        root.setAttribute('data-theme', 'dark');
        root.classList.add('dark');
        
        return () => {
            // Restore original theme on unmount
            if (originalTheme) {
                root.setAttribute('data-theme', originalTheme);
            }
            if (!hadDarkClass) {
                root.classList.remove('dark');
            }
        };
    }, []);

    // Autofill Logic
    useEffect(() => {
        const checkAutofill = async () => {
            const data = await AutofillService.get();
            if (data && data.length > 0) {
                setSavedData(data);
                if (Capacitor.getPlatform() === 'web') {
                    setShowAutofillPrompt(true);
                }
            }
        };
        checkAutofill();
    }, []);

    const applyAutofill = async (profile) => {
        const authenticated = await nativeAuthService.authenticate();
        
        if (authenticated) {
            if (profile && profile.email) {
                // Show dedicated direct login overlay
                setIsDirectLoggingIn(true);
                setShowAutofillPrompt(false);
                
                // Trigger immediate login
                handleLogin(null, profile.email, profile.password, true);
            }
        }
    };

    useEffect(() => {
        // Only auto-redirect if NOT in the middle of a process (login, success check, or save prompt)
        if (user && !showSavePrompt && !isSuccess && !isLoading && !isDirectLoggingIn) {
            // Redirect directly based on role
            if (user.role === 'admin') {
                logout();
                setError('Admins cannot login to the mobile app. Please use the Admin Web Panel.');
            } else if (user.role === 'faculty') {
                navigate('/faculty', { replace: true });
            } else {
                navigate('/dashboard', { replace: true });
            }
        } else if (!user) {
            // If user is null (logged out), ensure modal is closed
            setShowPinModal(false);
            setIsAdminVerified(false);
        }
    }, [user, navigate, isAdminVerified, showSavePrompt, isSuccess, isLoading, logout]);

    const handleLogin = async (e, directEmail = null, directPassword = null, isAutofill = false) => {
        if (e) e.preventDefault();
        
        const loginEmail = directEmail || formData.email;
        const loginPassword = directPassword || formData.password;

        if (!loginEmail || !loginPassword) return;

        console.log("Login attempt for:", loginEmail);
        setError('');
        setIsLoading(true);

        try {
            const result = await login(loginEmail, loginPassword);
            console.log("Login successful, result user:", result.user.uid);

            // Check if we should show the save prompt BEFORE updating success states
            const profiles = await AutofillService.get();
            // Show prompt if profile doesn't exist OR if password has changed
            const existingProfile = profiles.find(p => p.email.toLowerCase() === loginEmail.toLowerCase());
            const needsSave = !existingProfile || existingProfile.password !== loginPassword;

            if (needsSave) {
                setShowSavePrompt(true);
            }

            setIsLoading(false);
            setIsSuccess(true);

            // Notify user of successful login
            notify('Login Successful ✅', `Welcome back! You are now logged in as ${loginEmail}.`, 'ic_stat_notification');

            if (!needsSave) {
                // Already saved, just clear success delay to let useEffect handle it dynamically based on the fetched user.role
                setTimeout(() => {
                    setIsSuccess(false);
                    if (isAutofill) setIsDirectLoggingIn(false);
                }, 1000);
            }
        } catch (err) {
            console.error("Login catch block error:", err);
            setIsLoading(false);
            if (isAutofill) setIsDirectLoggingIn(false);

            if (isAutofill && (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential')) {
                // Automatically remove the invalid/deleted account from saved data
                const currentProfiles = await AutofillService.get();
                const updatedProfiles = currentProfiles.filter(p => p.email.toLowerCase() !== loginEmail.toLowerCase());
                
                const { Preferences } = await import('@capacitor/preferences');
                await Preferences.set({
                    key: 'rgukt_autofill_data',
                    value: JSON.stringify(updatedProfiles)
                });
                
                setSavedData(updatedProfiles);
                if (updatedProfiles.length === 0) {
                    setShowAutofillPrompt(false);
                }
                
                setError(`Account ${loginEmail} is no longer valid or has been deleted. It has been removed from saved accounts.`);
                return;
            }

            if (loginEmail === 'admin@rguktconnect.ac.in' && (err.code === 'auth/user-not-found' || err.code === 'auth/invalid-credential')) {
                setError('Admin account not found. Please click "Create Account" below and register as a Student first (you will be auto-elevated to Admin).');
            } else if (err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential') {
                setError('Invalid email or password.');
            } else if (err.code === 'auth/invalid-email') {
                setError('Please provide a valid institutional email.');
            } else {
                setError(`Authentication failed: ${err.code} - ${err.message}`);
            }
        }
    };

    const handleGoogleLogin = async () => {
        setError('');
        setIsLoading(true);
        try {
            await loginWithGoogle();
            setIsLoading(false);
            setIsSuccess(true);
            setTimeout(() => {
                setIsSuccess(false);
            }, 1000);
        } catch (err) {
            console.error("Google login error:", err);
            setError(`Google Sign-In failed: ${err.message || 'Unknown error'}`);
            setIsLoading(false);
        }
    };

    const handlePinChange = (index, value) => {
        if (isNaN(value)) return;
        const newPin = [...pin];
        newPin[index] = value;
        setPin(newPin);

        // Auto-focus next input
        if (value && index < 5) {
            pinInputRefs.current[index + 1].focus();
        }

        // Auto-validate if all digits are filled
        const filledPin = newPin.join('');
        if (filledPin.length === 6) {
            verifyAdminPin(filledPin);
        }
    };

    const handlePinKeyDown = (index, e) => {
        if (e.key === 'Backspace' && !pin[index] && index > 0) {
            pinInputRefs.current[index - 1].focus();
        }
    };

    const verifyAdminPin = async (manualPin = null) => {
        const enteredPin = manualPin || pin.join('');
        if (enteredPin.length < 4) {
            setError('Please enter a valid PIN.');
            return;
        }

        setIsLoading(true);
        const isValid = await verifyPin(tempUserUid, enteredPin);

        if (isValid) {
            setIsLoading(false);
            setIsSuccess(true);
            setTimeout(() => {
                setIsAdminVerified(true);
                navigate('/admin', { replace: true });
            }, 1000);
        } else {
            setError('Incorrect PIN. Please try again.');
            setIsLoading(false);
            setPin(['', '', '', '', '', '']);
            pinInputRefs.current[0]?.focus();
        }
    };



    const handleChange = (e) => {
        setFormData({
            ...formData,
            [e.target.name]: e.target.value
        });
        if (error) setError('');
    };

    const handleSaveConfirm = async () => {
        setIsSavingSuccess(true);
        await AutofillService.save({ 
            email: formData.email,
            password: formData.password, // Save password for full autofill
            avatar: user?.avatar || null // Save profile photo for the selector
        });
        
        // Wait for animation
        setTimeout(() => {
            setShowSavePrompt(false);
            setIsSavingSuccess(false);
            if (isDirectLoggingIn) setIsDirectLoggingIn(false);
            setIsSuccess(false);
        }, 1500);
    };

    const handleSaveDecline = () => {
        setShowSavePrompt(false);
        if (isDirectLoggingIn) setIsDirectLoggingIn(false);
        setIsSuccess(false);
    };

    const handleTouchStart = (e, profile) => {
        isLongPressActive.current = false;
        longPressTimerRef.current = setTimeout(() => {
            isLongPressActive.current = true;
            // Haptic Feedback for long press
            if (window.navigator.vibrate) window.navigator.vibrate(50);
            console.log("Long press detected for:", profile.email);
            handleDeleteRequest(profile);
        }, 600); // 600ms for long press
    };

    const handleTouchEnd = () => {
        if (longPressTimerRef.current) {
            clearTimeout(longPressTimerRef.current);
            longPressTimerRef.current = null;
        }
    };

    const handleDeleteRequest = (profile) => {
        console.log("Showing delete confirmation for:", profile.email);
        setProfileToDelete(profile);
        setShowDeleteConfirm(true);
        setDeletePassword('');
        setDeleteError('');
    };

    const handleConfirmDelete = async () => {
        if (!profileToDelete) return;
        
        if (deletePassword !== profileToDelete.password) {
            setDeleteError('Incorrect password. Please verify your identity.');
            return;
        }

        setIsDeletingInProgress(true);
        
        // Artificial delay for the 2-second deleting animation
        await new Promise(resolve => setTimeout(resolve, 2000));

        setIsDeletingInProgress(false);
        setIsDeletingSuccess(true);
        
        // Remove from storage
        const currentProfiles = await AutofillService.get();
        const updatedProfiles = currentProfiles.filter(p => p.email.toLowerCase() !== profileToDelete.email.toLowerCase());
        
        const { Preferences } = await import('@capacitor/preferences');
        await Preferences.set({
            key: 'rgukt_autofill_data',
            value: JSON.stringify(updatedProfiles)
        });

        // Trigger notification
        notify('Account Removed', `Account ${profileToDelete.email} has been deleted from this device.`, 'ic_stat_notification');

        // Wait for animation
        setTimeout(() => {
            setSavedData(updatedProfiles);
            setIsDeletingSuccess(false);
            setShowDeleteConfirm(false);
            setProfileToDelete(null);
            
            if (updatedProfiles.length === 0) {
                setShowAutofillPrompt(false);
            }
        }, 1500);
    };

    // Prevent flash of login screen while waiting for redirect useEffect to fire
    if (user && !showSavePrompt && !isDirectLoggingIn && !isSuccess && !isLoading) {
        return <LoadingTransition persistent />;
    }

    return (
        <>
        <div className="login-container login-modern-layout">
            {/* Animated Background Orbs */}
            <div className="animated-bg-container">
                <div className="bg-orb orb-1"></div>
                <div className="bg-orb orb-2"></div>
                <div className="bg-orb orb-3"></div>
            </div>

            <div className="login-glass-wrapper">
                <div className="login-glass-card">
                    <div className="login-card-inner">
                        {/* Centered Branding */}
                        <div className="login-header-v2">
                            <div className="branding-container">
                                <Branding size="lg" variant="auto" />
                            </div>
                            <h1 className="login-title">Welcome Back</h1>
                            <p className="login-subtitle">Sign in to your institutional account</p>
                        </div>


                        {error && (
                            <div className="animate-fade-in" style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: '0.75rem',
                                padding: '1rem',
                                background: 'rgba(239, 68, 68, 0.1)',
                                border: '1px solid rgba(239, 68, 68, 0.2)',
                                borderRadius: '0.75rem',
                                color: '#ef4444',
                                fontSize: '0.85rem',
                                marginBottom: '1.5rem'
                            }}>
                                <AlertCircle size={18} />
                                <span>{error}</span>
                            </div>
                        )}

                        <form onSubmit={handleLogin} className="space-y-4" noValidate>
                            <div className="login-form-group">
                                <label className="login-label" htmlFor="email">Institutional ID / Email</label>
                                <div className="login-input-wrapper">
                                    <div className="login-input-icon">
                                        <Mail size={18} />
                                    </div>
                                    <input
                                        id="email"
                                        name="email"
                                        type="text"
                                        className="login-input"
                                        placeholder="R240387 or student@rguktrkv.ac.in"
                                        value={formData.email}
                                        onChange={handleChange}
                                        required
                                        style={{ paddingRight: savedData.length > 0 ? '4.5rem' : '12px' }}
                                    />
                                    {savedData.length > 0 && (
                                        <button 
                                            type="button"
                                            className="autofill-trigger-badge"
                                            onClick={() => setShowAutofillPrompt(true)}
                                        >
                                            <UserCircle size={14} />
                                            <span>Saved</span>
                                        </button>
                                    )}
                                </div>
                            </div>

                            <div className="login-form-group">
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                                    <label className="login-label" style={{ marginBottom: 0 }} htmlFor="password">Password</label>
                                    <Link to="/forgot-password" className="login-forgot-link">Forgot password?</Link>
                                </div>
                                <div className="login-input-wrapper" style={{ position: 'relative' }}>
                                    <div className="login-input-icon">
                                        <Lock size={18} />
                                    </div>
                                    <input
                                        id="password"
                                        name="password"
                                        type={showPassword ? "text" : "password"}
                                        className="login-input"
                                        placeholder="••••••••"
                                        value={formData.password}
                                        onChange={handleChange}
                                        style={{ paddingRight: '5rem' }}
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        style={{
                                            position: 'absolute',
                                            right: '10px',
                                            top: '50%',
                                            transform: 'translateY(-50%)',
                                            background: 'none',
                                            border: 'none',
                                            cursor: 'pointer',
                                            color: 'var(--color-slate-400)',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            padding: '4px'
                                        }}
                                        aria-label={showPassword ? "Hide password" : "Show password"}
                                    >
                                        {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                                    </button>
                                </div>
                            </div>

                            <button
                                type="submit"
                                className="login-btn"
                                disabled={isLoading}
                            >
                                {isLoading ? (
                                    <span style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                        <span className="animate-spin" style={{ border: '2px solid white', borderTopColor: 'transparent', borderRadius: '50%', width: '1rem', height: '1rem' }}></span>
                                        Signing in...
                                    </span>
                                ) : (
                                    <>
                                        <span>Sign In securely</span>
                                        <ArrowRight size={18} />
                                    </>
                                )}
                            </button>









                            <div className="login-divider">
                                <span>or continue with</span>
                            </div>

                            <button
                                type="button"
                                className="google-login-btn"
                                onClick={handleGoogleLogin}
                                disabled={isLoading}
                            >
                                <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Google" />
                                <span>Sign In with Google</span>
                            </button>
                        </form>
                    </div>
                    
                    <div className="login-footer-bar-v2">
                        <span>Don't have an account?</span>
                        <Link to="/register" className="login-footer-btn-v2">Create Account</Link>
                    </div>
                </div>

                <div className="footer-wrapper">
                    <AppFooter />
                </div>
            </div>

            {/* PIN Verification Modal */}
            {showPinModal && (
                <div className="auth-modal-overlay">
                    <div className="auth-modal-content">
                        {isSuccess ? (
                            <div className="success-animation-container">
                                <div className="success-wrapper-horizontal">
                                    <div className="checkmark-circle">
                                        <svg className="w-12 h-12 text-[var(--color-slate-900)]" viewBox="0 0 24 24">
                                            <path className="checkmark-svg" d="M20 6L9 17L4 12" style={{ stroke: 'currentColor' }} />
                                        </svg>
                                    </div>
                                    <div className="sparkles-side-container">
                                        <div className="sparkle-accent ss1"><Sparkle size={14} fill="currentColor" /></div>
                                        <div className="sparkle-accent ss2"><Sparkles size={22} fill="currentColor" /></div>
                                        <div className="sparkle-accent ss3"><Sparkle size={12} fill="currentColor" /></div>
                                    </div>
                                </div>
                                <h3 className="success-text">Verified!</h3>
                                <p className="success-subtext">Redirecting to dashboard...</p>
                            </div>
                        ) : (
                            <>
                                <div className="text-center mb-6">
                                    <div className="auth-modal-icon-wrapper">
                                        <Lock size={32} />
                                    </div>
                                    <h3 className="auth-modal-title">Admin Verification</h3>
                                    <p className="auth-modal-desc">
                                        Please enter your 6-digit PIN to continue.
                                    </p>
                                </div>

                                <div className="pin-input-container">
                                    {pin.map((digit, index) => (
                                        <input
                                            key={index}
                                            ref={el => pinInputRefs.current[index] = el}
                                            type="password"
                                            maxLength={1}
                                            className="pin-input-field"
                                            value={digit}
                                            onChange={(e) => handlePinChange(index, e.target.value)}
                                            onKeyDown={(e) => handlePinKeyDown(index, e)}
                                            autoFocus={index === 0}
                                        />
                                    ))}
                                </div>

                                {error && (
                                    <div className="mb-6 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg text-red-600 dark:text-red-400 text-sm text-center flex items-center justify-center gap-2">
                                        <AlertCircle size={16} />
                                        {error}
                                    </div>
                                )}

                                <button
                                    onClick={verifyAdminPin}
                                    className="login-btn"
                                    style={{ marginBottom: '1rem' }}
                                    disabled={isLoading}
                                >
                                    {isLoading ? 'Verifying...' : 'Verify Access'}
                                </button>
                            </>
                        )}
                    </div>
                </div>
            )}


        </div>

            {/* Direct Login Overlay */}
            {isDirectLoggingIn && (
                <div className="direct-login-overlay animate-fade-in">
                    <div className="direct-login-content">
                        <div className="direct-login-spinner"></div>
                        <div className="direct-login-text">
                            <h3>Please wait</h3>
                            <p>Account logging in...</p>
                        </div>
                    </div>
                </div>
            )}

            {/* Account Selector Bottom Sheet (Autofill) */}
            {showAutofillPrompt && savedData && (
                <div className="save-prompt-overlay" onClick={() => setShowAutofillPrompt(false)}>
                    <div className="save-prompt-sheet animate-slide-up-bottom" onClick={e => e.stopPropagation()}>
                        <div className="save-prompt-header">
                            <div className="save-prompt-icon">
                                <UserCircle size={28} />
                            </div>
                            <div className="save-prompt-titles">
                                <h3>Choose an account</h3>
                                <p>Continue with your saved credentials</p>
                            </div>
                        </div>

                        <div className="account-selector-hint">
                            <ShieldAlert size={12} />
                            <span>Long press an account to remove it</span>
                        </div>
                        
                        <div className="account-selector-list" style={{ maxHeight: '300px', overflowY: 'auto' }}>
                            {savedData.map((profile, idx) => (
                                <div 
                                    key={idx} 
                                    className="account-item" 
                                    onClick={() => {
                                        if (!isLongPressActive.current) {
                                            applyAutofill(profile);
                                        }
                                    }}
                                    onTouchStart={(e) => handleTouchStart(e, profile)}
                                    onTouchEnd={handleTouchEnd}
                                    onTouchMove={handleTouchEnd} // Cancel on scroll/move
                                    onContextMenu={(e) => e.preventDefault()} // Disable native menu
                                >
                                    <div className="account-avatar">
                                        {profile.avatar ? (
                                            <img 
                                                src={profile.avatar} 
                                                alt="Profile" 
                                                className="account-photo-img"
                                                onError={(e) => {
                                                    e.target.onerror = null;
                                                    e.target.style.display = 'none';
                                                }}
                                            />
                                        ) : (
                                            profile.email.charAt(0).toUpperCase()
                                        )}
                                    </div>
                                    <div className="account-info">
                                        <span className="account-email">{profile.email}</span>
                                        <span className="account-status">Saved on this device</span>
                                    </div>
                                    <div className="account-actions">
                                        <ArrowRight size={18} className="account-arrow" />
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="save-prompt-actions">
                            <button onClick={() => setShowAutofillPrompt(false)} className="btn-save-decline">Use another account</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Save Credentials Bottom Sheet */}
            {showSavePrompt && (
                <div className="save-prompt-overlay">
                    <div className="save-prompt-sheet animate-slide-up-bottom">
                        <div className="save-prompt-header">
                            <div className={`save-prompt-icon ${isSavingSuccess ? 'success-mode' : ''}`}>
                                {isSavingSuccess ? <Check size={24} /> : <ShieldCheck size={24} />}
                            </div>
                            <div className="save-prompt-titles">
                                <h3>{isSavingSuccess ? 'Saved successfully!' : 'Save details?'}</h3>
                                <p>{isSavingSuccess ? 'Your credentials are now secure.' : 'Autofill will be available next time you log in.'}</p>
                            </div>
                        </div>
                        
                        <div className="save-prompt-preview">
                            <div className="preview-item">
                                <Mail size={16} />
                                <span>{formData.email}</span>
                            </div>
                        </div>

                        <div className="save-prompt-actions">
                            <button onClick={handleSaveDecline} className="btn-save-decline">Decline</button>
                            <button onClick={handleSaveConfirm} className="btn-save-confirm">Save Details</button>
                        </div>
                    </div>
                </div>
            )}
            {/* Delete Confirmation Modal */}
            {showDeleteConfirm && (
                <div className="save-prompt-overlay" style={{ zIndex: 3000 }} onClick={() => !isDeletingSuccess && setShowDeleteConfirm(false)}>
                    <div className="save-prompt-sheet animate-slide-up-bottom" style={{ maxWidth: '400px' }} onClick={e => e.stopPropagation()}>
                        {isDeletingInProgress ? (
                            <div className="save-success-container">
                                <div className="deleting-spinner-wrapper">
                                    <div className="deleting-spinner-ring"></div>
                                    <Trash2 size={40} className="deleting-icon-anim" />
                                </div>
                                <h3 style={{ color: 'var(--color-red-600)', fontWeight: 800 }}>Deleting Account</h3>
                                <p style={{ color: 'var(--color-slate-500)' }}>Permanently removing credentials...</p>
                            </div>
                        ) : isDeletingSuccess ? (
                            <div className="save-success-container">
                                <div className="success-tick-wrapper">
                                    <div className="success-ring"></div>
                                    <Check size={48} className="success-tick animate-scale-in-check" />
                                </div>
                                <h3 style={{ color: 'var(--color-emerald-600)', fontWeight: 800 }}>Account Deleted</h3>
                                <p style={{ fontSize: '1rem', color: 'var(--color-slate-500)' }}>Successfully removed from this device</p>
                            </div>
                        ) : (
                            <>
                                <div className="delete-profile-preview">
                                    <div className="delete-avatar-wrapper">
                                        {profileToDelete?.avatar ? (
                                            <img src={profileToDelete.avatar} alt="Profile" className="delete-avatar-img" />
                                        ) : (
                                            <div className="delete-avatar-initial">
                                                {profileToDelete?.email.charAt(0).toUpperCase()}
                                            </div>
                                        )}
                                        <div className="delete-warning-badge">
                                            <ShieldAlert size={14} />
                                        </div>
                                    </div>
                                    <div className="delete-profile-details">
                                        <h4>{profileToDelete?.email}</h4>
                                        <p>This account will be removed from this device</p>
                                    </div>
                                </div>
                                
                                <div className="delete-confirm-content">
                                    <div className="input-group-v2">
                                        <label className="input-label-v2">Identity Verification</label>
                                        <div className={`input-wrapper-v2 ${deleteError ? 'error' : ''}`}>
                                            <Lock className="input-icon-v2" size={20} />
                                            <input 
                                                type="password"
                                                placeholder="Enter account password"
                                                value={deletePassword}
                                                onChange={(e) => {
                                                    setDeletePassword(e.target.value);
                                                    if (deleteError) setDeleteError('');
                                                }}
                                                className="input-field-v2"
                                            />
                                        </div>
                                        {deleteError && <p className="error-text-v2"><AlertCircle size={14} /> {deleteError}</p>}
                                    </div>
                                </div>

                                <div className="save-prompt-actions" style={{ marginTop: '1rem' }}>
                                    <button 
                                        onClick={() => setShowDeleteConfirm(false)} 
                                        className="btn-save-decline"
                                    >
                                        Cancel
                                    </button>
                                    <button 
                                        onClick={handleConfirmDelete} 
                                        className="btn-save-confirm btn-danger"
                                    >
                                        Delete
                                    </button>
                                </div>
                            </>
                        )}
                    </div>
                </div>
            )}
        </>
    );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import { PROGRAMS } from '../config/academics';
import { fetchDynamicSubjects, fetchDynamicUnits, fetchDynamicModules, getModuleById, getUnitById } from '../utils/academicsUtils';
import { getEmbedUrl, getPdfEmbedUrl, getDirectPdfUrl } from '../utils/videoUtils';
import { FileText, ArrowLeft, PlayCircle, BookOpen, Minimize2, ExternalLink, Download, RefreshCw, HelpCircle, AlertCircle, PenTool, Lightbulb, ArrowRight, CheckCircle, RefreshCcw } from 'lucide-react';
import { checkPdfStatus, downloadPdf, openPdf } from '../services/pdfCacheService';
import { pdfService } from '../services/pdfService';
import LoadingTransition from '../components/Common/LoadingTransition';
import EmbeddedQuiz from '../components/Quiz/EmbeddedQuiz';
import { getQuestionsForQuiz } from '../services/quizService';
import PdfDownloadCard from '../components/Common/PdfDownloadCard';

const ModuleContent = () => {
    const { yearId, semesterId, subjectId, unitId, moduleId } = useParams();
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    const branchId = searchParams.get('branch');
    const [currentModule, setCurrentModule] = useState(null);
    const [currentUnit, setCurrentUnit] = useState(null);
    const [currentProgram, setCurrentProgram] = useState(null);
    const [loading, setLoading] = useState(true);
    const [showQuiz, setShowQuiz] = useState(false);
    const [isGeneratingQuiz, setIsGeneratingQuiz] = useState(false);
    const [quizQuestions, setQuizQuestions] = useState(null);
    const [showFab, setShowFab] = useState(false);
    const [viewMode, setViewMode] = useState('selection');
    const [activePdf, setActivePdf] = useState({ label: '', url: '', embedUrl: '' });
    const [showPdfHelp, setShowPdfHelp] = useState(false);
    const [useBackupViewer, setUseBackupViewer] = useState(false);
    
    const [quizSettings, setQuizSettings] = useState({
        isEnabled: true,
        passingPercentage: 40,
        maxRetakes: 3
    });

    // Fetch Quiz Settings
    useEffect(() => {
        if (!currentModule) return;
        const fetchSettings = async () => {
            try {
                const docRef = doc(db, 'quiz_settings', currentModule.id);
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    setQuizSettings(docSnap.data());
                }
            } catch (error) {
                console.error("Error fetching quiz settings:", error);
            }
        };
        fetchSettings();
    }, [currentModule]);

    // Timer to show FAB after 60 seconds of "reading"
    useEffect(() => {
        if (!currentModule || !quizSettings.isEnabled) return;
        
        // If they already have progress saved, show it immediately
        if (localStorage.getItem(`quiz_progress_${currentModule.id}`)) {
            setShowFab(true);
            return;
        }

        const timer = setTimeout(() => {
            setShowFab(true);
        }, 60000); // 60 seconds

        return () => clearTimeout(timer);
    }, [currentModule]);

    const handleGenerateQuiz = async () => {
        if (quizQuestions) {
            setShowQuiz(true);
            return;
        }
        setIsGeneratingQuiz(true);
        try {
            // 1. Check if admin has pre-configured questions for this module from Firebase
            let questions = await getQuestionsForQuiz(currentModule.id);
            
            // 2. If no questions exist, alert the user instead of using AI
            if (!questions || questions.length === 0) {
                alert("No quiz questions have been added for this module yet. Please check back later.");
                setIsGeneratingQuiz(false);
                return;
            }
            
            setQuizQuestions(questions);
            setShowQuiz(true);
        } catch (error) {
            console.error("Failed to fetch quiz from Firebase", error);
            alert("Failed to load quiz from database. Please try again or check connection.");
        } finally {
            setIsGeneratingQuiz(false);
        }
    };

    useEffect(() => {
        const loadModule = async () => {
            const modulePromise = getModuleById(moduleId);
            const unitPromise = getUnitById(unitId);

            const resolveHierarchy = async () => {
                const program = PROGRAMS.find(p => p.years.some(y => y.id === yearId));
                const year = program?.years.find(y => y.id === yearId);
                let targetSemesters = year?.semesters;
                if (branchId && year?.branches) {
                    const branch = year.branches.find(b => b.id === branchId);
                    if (branch) targetSemesters = branch.semesters;
                }
                const semester = targetSemesters?.find(s => s.id === semesterId);
                let subject = semester?.subjects.find(s => s.id === subjectId);

                if (!subject && program) {
                    const dynSubjects = await fetchDynamicSubjects(program.id, yearId, branchId || null, semesterId);
                    subject = dynSubjects.find(s => s.id === subjectId);
                }
                return { program, subject };
            };

            const [moduleData, unitData, hierarchy] = await Promise.all([
                modulePromise,
                unitPromise,
                resolveHierarchy()
            ]);

            if (moduleData) {
                // Resolve PDF metadata if stored as an ID
                const resolvePdf = async (url) => {
                    if (url && !url.startsWith('http')) {
                        const pdfData = await pdfService.getPdfById(url);
                        return pdfData;
                    }
                    return null;
                };

                const mainPdfData = await resolvePdf(moduleData.pdfUrl);
                const hwPdfData = await resolvePdf(moduleData.handwrittenNotesUrl);
                
                // Add resolved data to module object
                if (mainPdfData) moduleData.resolvedPdfData = mainPdfData;
                if (hwPdfData) moduleData.resolvedHwPdfData = hwPdfData;

                if (moduleData.additionalNotes && moduleData.additionalNotes.length > 0) {
                    for (let note of moduleData.additionalNotes) {
                        const noteData = await resolvePdf(note.url);
                        if (noteData) note.resolvedData = noteData;
                    }
                }

                setCurrentModule(moduleData);
            }
            if (unitData) setCurrentUnit(unitData);
            if (hierarchy.program) setCurrentProgram(hierarchy.program);

            setLoading(false);
        };
        loadModule();
    }, [yearId, semesterId, subjectId, unitId, moduleId]);

    const hierarchy = [
        searchParams.get('branch') ? `Branch_${searchParams.get('branch')}` : (currentProgram?.label || 'General'),
        'Semester', // Can't easily get semester name here without extra lookup
        'Subject',   // Can't easily get subject name here without extra lookup
        currentUnit?.label || 'Unit',
        currentModule?.label || 'Module'
    ];



    if (loading) return <LoadingTransition persistent variant="book" />;

    if (!currentModule) {
        return <div className="p-12 text-center text-[var(--color-text-muted)] font-bold italic">Module not found.</div>;
    }

    const renderSelectionView = () => (
        <div className="flex-1 flex flex-col items-center justify-center py-12 px-4">

            <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 w-full max-w-7xl hover-blur-group`}>
                
                {/* Notes Column */}
                <div className="flex flex-col gap-4 w-full">
                    <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                        <BookOpen size={20} className="text-[var(--color-primary-500)]" />
                        Available Materials
                    </h2>
                    
                    {currentModule.pdfUrl && (
                        <div onClick={() => {
                            if (currentModule.resolvedPdfData?.embedUrl) {
                                setActivePdf({ label: currentModule.pdfName || 'Main Lecture Notes', url: currentModule.resolvedPdfData.downloadUrl, embedUrl: currentModule.resolvedPdfData.embedUrl });
                                setViewMode('notes');
                            }
                        }}>
                            <PdfDownloadCard 
                                label={currentModule.pdfName || currentModule.resolvedPdfData?.fileName || "Main Lecture Notes"} 
                                url={currentModule.resolvedPdfData?.downloadUrl || currentModule.pdfUrl} 
                                idPrefix={currentModule.id} 
                                hierarchy={hierarchy} 
                                size={currentModule.resolvedPdfData?.size}
                                backendUrl={currentModule.resolvedPdfData?.backendUrl}
                            />
                        </div>
                    )}
                    
                    {currentModule.additionalNotes?.map((note, idx) => (
                        <div key={`add_${idx}`} onClick={() => {
                            if (note.resolvedData?.embedUrl) {
                                setActivePdf({ label: note.resolvedData.fileName || note.label, url: note.resolvedData.downloadUrl, embedUrl: note.resolvedData.embedUrl });
                                setViewMode('notes');
                            }
                        }}>
                            <PdfDownloadCard 
                                label={note.resolvedData?.fileName || note.label} 
                                url={note.resolvedData?.downloadUrl || note.url} 
                                idPrefix={currentModule.id} 
                                hierarchy={hierarchy}
                                size={note.resolvedData?.size} 
                                backendUrl={note.resolvedData?.backendUrl}
                            />
                        </div>
                    ))}

                    {currentModule.handwrittenNotesUrl && (
                        <div onClick={() => {
                            if (currentModule.resolvedHwPdfData?.embedUrl) {
                                setActivePdf({ label: currentModule.handwrittenNotesName || currentModule.resolvedHwPdfData?.fileName || 'Handwritten Notes', url: currentModule.resolvedHwPdfData.downloadUrl, embedUrl: currentModule.resolvedHwPdfData.embedUrl });
                                setViewMode('notes');
                            }
                        }}>
                            <PdfDownloadCard 
                                label={currentModule.handwrittenNotesName || currentModule.resolvedHwPdfData?.fileName || "Handwritten Notes"} 
                                url={currentModule.resolvedHwPdfData?.downloadUrl || currentModule.handwrittenNotesUrl} 
                                idPrefix={`${currentModule.id}_HW`} 
                                hierarchy={hierarchy} 
                                size={currentModule.resolvedHwPdfData?.size}
                                backendUrl={currentModule.resolvedHwPdfData?.backendUrl}
                            />
                        </div>
                    )}

                    {(!currentModule.pdfUrl && !currentModule.handwrittenNotesUrl && (!currentModule.additionalNotes || currentModule.additionalNotes.length === 0)) && (
                        <div className="p-8 text-center text-slate-400 bg-white rounded-2xl border border-slate-200 border-dashed">
                            No materials available for download.
                        </div>
                    )}
                </div>

                {/* Video Card */}
                {currentModule.videoUrl?.trim() && (
                    <div className="flex flex-col gap-4 w-full">
                        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                            <PlayCircle size={20} className="text-red-500" />
                            Video Lecture
                        </h2>
                        <div className="embedded-card group h-64 md:h-auto md:aspect-video rounded-2xl overflow-hidden shadow-sm border border-slate-200">
                            <div className="embed-container w-full h-full">
                                <iframe
                                    className="w-full h-full"
                                    src={getEmbedUrl(currentModule.videoUrl)}
                                    title="Video Preview"
                                    frameBorder="0"
                                ></iframe>
                            </div>
                        </div>
                    </div>
                )}
            </div>

            {/* Test Your Knowledge Action (Inline) */}
            {quizSettings.isEnabled && (
                <div className="mt-16 w-full max-w-4xl mx-auto px-4 pb-16">
                    <div className="relative w-full rounded-3xl overflow-hidden p-8 md:p-12 shadow-xl border" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)' }}>
                        {/* Decorative glow effects */}
                        <div className="absolute top-0 right-0 w-64 h-64 rounded-full mix-blend-multiply filter blur-[80px] opacity-30 -mr-20 -mt-20 pointer-events-none" style={{ background: 'var(--color-primary-500)' }}></div>
                        <div className="absolute bottom-0 left-0 w-64 h-64 rounded-full mix-blend-multiply filter blur-[80px] opacity-20 -ml-20 -mb-20 pointer-events-none" style={{ background: '#6366f1' }}></div>
                        
                        <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
                            <div className="flex-1 text-center md:text-left">
                                <div className="inline-flex items-center justify-center w-14 h-14 rounded-2xl mb-6 shadow-lg border" style={{ background: 'var(--color-primary-600)', borderColor: 'var(--color-primary-400)' }}>
                                    <Lightbulb size={28} color="#ffffff" className="animate-pulse" style={{ animationDuration: '3s' }} />
                                </div>
                                <h3 className="text-2xl md:text-3xl font-bold mb-3" style={{ color: 'var(--color-text-main)' }}>Ready to test your knowledge?</h3>
                                <p className="text-lg max-w-lg mx-auto md:mx-0" style={{ color: 'var(--color-text-muted)' }}>Take a quick 15-minute quiz to solidify your understanding of this topic and track your progress.</p>
                            </div>
                            
                            <div className="shrink-0 flex flex-col items-center">
                                <button 
                                    onClick={handleGenerateQuiz}
                                    disabled={isGeneratingQuiz}
                                    className="btn-primary transform hover:scale-105 active:scale-95 transition-all shadow-lg"
                                    style={{ 
                                        padding: '1rem 2.5rem', 
                                        fontSize: '1.125rem', 
                                        borderRadius: '9999px', 
                                        display: 'flex', 
                                        alignItems: 'center', 
                                        gap: '0.75rem',
                                        boxShadow: '0 10px 25px -5px rgba(var(--color-primary-500-rgb), 0.4)'
                                    }}
                                >
                                    {isGeneratingQuiz ? (
                                        <>
                                            <RefreshCw className="animate-spin" size={20} /> Preparing Quiz...
                                        </>
                                    ) : (
                                        <>
                                            Start Unit Quiz <ArrowRight size={20} />
                                        </>
                                    )}
                                </button>
                                <span className="mt-4 text-xs font-medium uppercase tracking-wider opacity-70" style={{ color: 'var(--color-text-muted)' }}>
                                    {quizSettings.passingPercentage}% to pass
                                </span>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );

    const renderFullNotes = () => (
        <div className="fixed inset-0 z-[50000] bg-[var(--color-background)] flex flex-col animate-fade-in">
            <div className="flex items-center justify-between px-8 py-4 border-b border-[var(--color-border)] bg-[var(--color-surface)]/[0.8] backdrop-blur-xl z-10 shrink-0">
                <div className="flex items-center gap-6">
                    <button
                        onClick={() => setViewMode('selection')}
                        className="group flex items-center justify-center w-12 h-12 rounded-[var(--radius-lg)] bg-[var(--color-surface-hover)] border border-[var(--color-border)] hover:bg-[var(--color-brand)] hover:text-[var(--color-on-brand)] transition-all transform hover:rotate-[-5deg] mobile-hidden"
                    >
                        <ArrowLeft size={24} />
                    </button>
                    <div>
                        <h2 className="text-2xl font-black text-[var(--color-text-main)] italic tracking-tight">{activePdf.label}</h2>
                        <div className="flex items-center gap-2">
                            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-[var(--color-text-muted)] italic">Document Flow</p>
                        </div>
                    </div>
                </div>
                <div className="flex items-center gap-6">
                    {currentModule.videoUrl && (
                        <button
                            onClick={() => setViewMode('video')}
                            className="hidden md:flex items-center gap-3 px-6 py-3 rounded-[var(--radius-lg)] bg-red-50 dark:bg-red-900/20 text-red-600 font-black text-xs hover:bg-red-600 hover:text-white transition-all transform hover:scale-105 shadow-lg shadow-red-500/10"
                        >
                            <PlayCircle size={18} /> Switch to Video
                        </button>
                    )}
                    <button onClick={() => setShowPdfHelp(!showPdfHelp)} className="p-3 rounded-[var(--radius-lg)] bg-amber-50 dark:bg-amber-900/30 text-amber-600 hover:bg-amber-600 hover:text-white transition-all">
                        <HelpCircle size={22} />
                    </button>
                </div>
            </div>

            <div className="flex-1 bg-[var(--color-slate-100)] dark:bg-[var(--color-slate-950)] relative">
                <iframe
                    src={activePdf.embedUrl || getPdfEmbedUrl(activePdf.url, useBackupViewer)}
                    className="w-full h-full border-none"
                    title="Fullscreen PDF"
                ></iframe>

                <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-[var(--color-surface)]/[0.9] backdrop-blur-3xl p-4 rounded-full border border-[var(--color-border)] shadow-2xl">
                    <button
                        onClick={() => setUseBackupViewer(!useBackupViewer)}
                        className={`flex items-center gap-3 px-8 h-12 rounded-full font-black text-xs transition-all ${useBackupViewer ? 'bg-[var(--color-brand)] text-[var(--color-on-brand)] shadow-lg shadow-primary-500/40' : 'bg-[var(--color-surface-hover)] text-[var(--color-brand)] hover:bg-[var(--color-primary-50)]'}`}
                    >
                        <RefreshCw size={18} className={useBackupViewer ? 'animate-spin-slow' : ''} />
                        {useBackupViewer ? 'Using Backup Proxy' : 'Toggle Backup Viewer'}
                    </button>
                    <a href={activePdf.url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 px-8 h-12 rounded-full bg-[var(--color-brand)] text-[var(--color-on-brand)] font-black text-xs shadow-lg shadow-primary-500/40 hover:scale-[1.05] active:scale-95 transition-all">
                        <ExternalLink size={18} /> Open Direct
                    </a>
                </div>
            </div>
        </div>
    );

    const renderFullVideo = () => (
        <div className="fixed inset-0 z-[50000] bg-slate-950 flex flex-col p-6 animate-fade-in">
            <div className="flex items-center justify-between mb-8 px-4 h-16 shrink-0 bg-transparent">
                <div className="flex items-center gap-6">
                    <button
                        onClick={() => setViewMode('selection')}
                        className="flex items-center justify-center w-14 h-14 rounded-[var(--radius-xl)] bg-white/5 hover:bg-white/10 text-white transition-all transform hover:rotate-[-5deg] border border-white/10 mobile-hidden"
                    >
                        <ArrowLeft size={28} />
                    </button>
                    <div>
                        <h2 className="text-3xl font-black text-white italic tracking-tight">Cinema Mode</h2>
                        <p className="text-xs font-black uppercase tracking-[0.4em] text-red-500 italic flex items-center gap-2">
                            Immersive Video Lecture
                        </p>
                    </div>
                </div>
                {activePdf.url && (
                    <button
                        onClick={() => setViewMode('notes')}
                        className="hidden md:flex items-center gap-3 px-8 h-14 rounded-2xl bg-[var(--color-brand)]/[0.1] text-[var(--color-brand)] font-black text-sm border-2 border-[var(--color-brand)]/[0.2] hover:bg-[var(--color-brand)] hover:text-[var(--color-on-brand)] transition-all shadow-2xl shadow-primary-500/10"
                    >
                        <BookOpen size={20} /> Switch to Notes
                    </button>
                )}
            </div>

            <div className="flex-1 rounded-[3rem] overflow-hidden bg-black relative border-8 border-white/5 ring-4 ring-white/5 p-2 bg-gradient-to-b from-white/5 to-transparent shadow-2xl">
                <iframe
                    className="w-full h-full rounded-[2.5rem]"
                    src={getEmbedUrl(currentModule.videoUrl)}
                    title="Immersive video player"
                    frameBorder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                ></iframe>
            </div>
        </div>
    );

    return (
        <div className="min-h-screen flex flex-col gap-8 pb-20 overflow-visible animate-fade-in">
            {/* Unified Theme Header - Standard Pattern */}
            {viewMode === 'selection' && (
                <div className="page-header-v2">

                    <div className="header-accent-bar"></div>
                    <div className="header-content-v2">
                        <h1 className="page-title-v2">{currentModule.label}</h1>
                        <p className="page-subtitle-v2">Academic Mastery Module</p>
                    </div>
                </div>
            )}

            {/* Content Display */}
            <div className="flex-1 flex flex-col justify-center min-h-0">
                {viewMode === 'selection' && renderSelectionView()}
                {viewMode === 'notes' && renderFullNotes()}
                {viewMode === 'video' && renderFullVideo()}
            </div>

            {/* Quiz Overlay */}
            {showQuiz && quizQuestions && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto" style={{ zIndex: 60000 }}>
                    <div className="w-full max-w-3xl my-auto animate-fade-in relative z-10 pt-16 md:pt-0">
                        <EmbeddedQuiz 
                            moduleId={currentModule.id} 
                            moduleTitle={currentModule.label}
                            questions={quizQuestions} 
                            onClose={() => setShowQuiz(false)} 
                            passingPercentage={quizSettings.passingPercentage}
                        />
                    </div>
                </div>
            )}

            {/* Floating Action Button for Quiz (Appears after 60s) */}
            {showFab && !showQuiz && viewMode === 'selection' && quizSettings.isEnabled && (
                <button
                    onClick={handleGenerateQuiz}
                    disabled={isGeneratingQuiz}
