import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { User, Lock, Mail, ArrowRight, ShieldCheck, GraduationCap, UserCircle, AlertCircle, CreditCard, Loader2, Check, Eye, EyeOff, Info, Sparkle, Sparkles, CheckCircle, Layout } from 'lucide-react';
import Branding from '../components/Branding';
import AppFooter from '../components/Common/AppFooter';
import { AutofillService } from '../services/autofillService';
import { nativeAuthService } from '../services/nativeAuthService';

import { useDownload } from '../context/DownloadContext';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';
import { db } from '../config/firebase';
import { doc, getDoc } from 'firebase/firestore';
import { formatClassID } from '../utils/formatUtils';
import './Register.css';

const Register = () => {
    const { register, loginWithGoogle } = useAuth();
    const { theme } = useTheme();
    const { triggerSuccessFeedback, notify } = useDownload();

    // Force light theme for register page
    useEffect(() => {
        const root = window.document.documentElement;
        const originalTheme = root.getAttribute('data-theme');
        root.setAttribute('data-theme', 'light');
        
        return () => {
            // Restore original theme on unmount
            if (originalTheme) {
                root.setAttribute('data-theme', originalTheme);
            }
        };
    }, [theme]);

    // Autofill Logic
    useEffect(() => {
        const checkAutofill = async () => {
            const data = await AutofillService.get();
            if (data && data.length > 0) {
                setSavedData(data);
                setShowAutofillPrompt(true);
            }
        };
        checkAutofill();
    }, []);

    const applyAutofill = async (profile) => {
        const authenticated = await nativeAuthService.authenticate();

        if (authenticated) {
            if (profile) {
                setFormData(prev => ({
                    ...prev,
                    studentId: profile.studentId || prev.studentId,
                    fullName: profile.fullName || prev.fullName,
                    email: profile.email || prev.email,
                    password: profile.password || prev.password,
                    currentClass: profile.currentClass || prev.currentClass
                }));
            }
            setShowAutofillPrompt(false);
        }
    };
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [isFetching, setIsFetching] = useState(false); // New fetching state
    const [showAutofillPrompt, setShowAutofillPrompt] = useState(false);
    const [savedData, setSavedData] = useState([]); // Array of profiles
    const [progress, setProgress] = useState(0);
    const [error, setError] = useState('');
    const [isValidStudent, setIsValidStudent] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const [formData, setFormData] = useState({
        studentId: '',
        fullName: '',
        currentClass: '',
        email: '',
        password: '',
        confirmPassword: ''
    });

    // Auto-fill logic with 2.5s delay
    React.useEffect(() => {
        let timer;
        if (formData.studentId && formData.studentId.length >= 6) {
            setIsFetching(true);
            // Clear current fields while fetching to indicate fresh data load
            setFormData(prev => ({ ...prev, fullName: '', classSection: '', email: '' }));

            timer = setTimeout(async () => {
                try {
                    const docRef = doc(db, 'students_master', formData.studentId.toUpperCase());
                    const docSnap = await getDoc(docRef);

                    console.log("Searching for:", formData.studentId, "Found in DB:", docSnap.exists());

                    if (docSnap.exists()) {
                        const student = docSnap.data();
                        const rawClass = student.classSection || student.currentClass || '';
                        setFormData(prev => ({
                            ...prev,
                            fullName: student.name || '',
                            currentClass: formatClassID(rawClass),
                            email: student.email || ''
                        }));
                        setIsValidStudent(true);
                    } else {
                        console.log("Student not found in database.");
                        setIsValidStudent(false);
                    }
                } catch (err) {
                    console.error("Error fetching student from DB:", err);
                    setIsValidStudent(false);
                } finally {
                    setIsFetching(false);
                }
            }, 800); // Reduced delay from 2500ms for better UX
        } else {
            setIsFetching(false);
            setIsValidStudent(false);
        }

        return () => clearTimeout(timer);
    }, [formData.studentId]);


    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: name === 'studentId' ? value.replace(/^RGUKT-/i, '').toUpperCase() : value
        }));
        if (error) setError('');
    };

    const handleRegister = async (e) => {
        e.preventDefault();
        setError('');

        if (formData.password !== formData.confirmPassword) {
            return setError('Passwords, unlike some relationships, must match perfectly.');
        }

        setIsLoading(true);

        try {
            const role = 'student'; // Always student

            // Simulate progress
            const progressInterval = setInterval(() => {
                setProgress(prev => (prev < 90 ? prev + 10 : prev));
            }, 200);

            const formattedStudentId = formData.studentId;

            await register(formData.email, formData.password, formData.fullName, role, formattedStudentId, formData.currentClass);

            setIsLoading(false);
            setProgress(100);

            // Play success sound and trigger haptics
            triggerSuccessFeedback();
            
            notify("Account Created Successfully", `${formData.fullName} (${formData.studentId}), your account is ready. Welcome to RGUKT Connect.`);

        } catch (err) {
            console.error("Registration failed:", err);

            if (err.code === 'auth/email-already-in-use' || (err.message && err.message.includes('email is already registered'))) {
                setError(
                    <span>
                        Email already registered. <Link to="/login" className="underline font-bold">Log In here</Link>
                    </span>
                );
            } else if (err.message && err.message.includes('Password incorrect')) {
                setError('Account exists but password didn\'t match. Please Log In.');
            } else {
                setError(err.message || 'Account creation failed.');
            }

            setIsLoading(false);
            setProgress(0);
        }
    };


    const handleGoogleRegister = async () => {
        setError('');
        setIsLoading(true);
        try {
            await loginWithGoogle();
        } catch (err) {
            console.error("Google register error:", err);
            setError('Google registration failed. Please try again.');
            setIsLoading(false);
        }
    };

    // Rendering success state...
    if (progress === 100) {
        return (
            <div className="register-container success-mode">
                <div className="register-bg-pattern"></div>
                
                {/* Decorative background celebration elements */}
                <div className="celebration-elements">
                    <div className="confetti-piece"></div>
                    <div className="confetti-piece"></div>
                    <div className="confetti-piece"></div>
                    <div className="confetti-piece"></div>
                    <div className="confetti-piece"></div>
                </div>

                <div className="register-content">
                    <div className="register-card success-card-glow">
                        <div className="register-card-body register-success-view">
                            <div className="success-badge-premium animate-bounce-subtle">
                                <ShieldCheck size={14} className="text-emerald-500" />
                                <span>Successfully Created Account</span>
                            </div>

                            <div className="success-icon-wrapper">
                                <div className="success-wrapper-horizontal">
