                ...noticeData,
                attachments: uploadedFiles,
                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp(),
                publishedAt: noticeData.status === 'published' ? serverTimestamp() : null,
                viewCount: 0,
                readCount: 0
            };

            const docRef = await addDoc(collection(db, NOTICES_COLLECTION), noticePayload);
            return { id: docRef.id, ...noticePayload };
        } catch (error) {
            console.error("Error creating notice:", error);
            throw error;
        }
    },

    /**
     * Updates an existing notice.
     */
    async updateNotice(noticeId, updateData, newAttachments = []) {
        try {
            let uploadedFiles = [];
            if (newAttachments.length > 0) {
                uploadedFiles = await this._uploadAttachments(newAttachments);
            }

            const noticeRef = doc(db, NOTICES_COLLECTION, noticeId);
            const payload = {
                ...updateData,
                updatedAt: serverTimestamp()
            };

            // If we have new attachments, merge them or replace them depending on logic.
            // For simplicity, assuming updateData.attachments contains the old ones being kept.
            if (uploadedFiles.length > 0) {
                payload.attachments = [...(updateData.attachments || []), ...uploadedFiles];
            }

            await updateDoc(noticeRef, payload);
            return { id: noticeId, ...payload };
        } catch (error) {
            console.error("Error updating notice:", error);
            throw error;
        }
    },

    /**
     * Deletes a notice and its attachments.
     */
    async deleteNotice(noticeId, attachments = []) {
        try {
            // Delete attachments from storage
            for (const file of attachments) {
                if (file.storagePath) {
                    const fileRef = ref(storage, file.storagePath);
                    await deleteObject(fileRef).catch(e => console.warn("Could not delete file:", e));
                }
            }

            // Delete the document
            await deleteDoc(doc(db, NOTICES_COLLECTION, noticeId));

            // Note: Should ideally delete all interactions for this notice via a Cloud Function
        } catch (error) {
            console.error("Error deleting notice:", error);
            throw error;
        }
    },

    /**
     * Fetches all notices (for Admin dashboard).
     */
    async getAllNotices() {
        try {
            const q = query(collection(db, NOTICES_COLLECTION), orderBy('createdAt', 'desc'));
            const snapshot = await getDocs(q);
            return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        } catch (error) {
            console.error("Error fetching all notices:", error);
            return [];
        }
    },

    // ---------------------------------------------------------
    // Student Operations
    // ---------------------------------------------------------

    /**
     * Fetches eligible notices for a specific student based on their profile.
     */
    async getEligibleNotices(user) {
        if (!user) return [];

        try {
            // In a real production app with massive scale, this logic might run on a Cloud Function.
            // Here, we fetch published, non-expired notices and filter client-side for complex array matching.

            const now = new Date();
            const noticesRef = collection(db, NOTICES_COLLECTION);

            // Query: We fetch by createdAt to avoid needing a composite index.
            // We will filter status === 'published' client-side.
            const q = query(
                noticesRef, 
                orderBy('createdAt', 'desc')
            );

            const snapshot = await getDocs(q);
            let eligibleNotices = [];

            snapshot.forEach(docSnap => {
                const notice = { id: docSnap.id, ...docSnap.data() };

                if (notice.status !== 'published') return;

                // Check Expiry
                if (notice.expiryDate) {
                    const expiry = notice.expiryDate.toDate ? notice.expiryDate.toDate() : new Date(notice.expiryDate);
                    if (expiry < now) return; // Expired
                }

                // Check Target Audience Eligibility
                const target = notice.targetAudience;
                if (!target) {
                    eligibleNotices.push(notice); // If no target defined, assume global
                    return;
                }

                let isEligible = false;

                if (target.targetAll) {
                    isEligible = true;
                } else {
                    const hasRoleFilter = target.roles && target.roles.length > 0;
                    const hasDeptFilter = target.departments && target.departments.length > 0;
                    const hasClassFilter = target.classes && target.classes.length > 0;

                    if (hasRoleFilter || hasDeptFilter || hasClassFilter) {
                        const getShortBranch = (branchStr) => {
                            if (!branchStr) return '';
                            const b = branchStr.toUpperCase();
                            if (/CSE\(AI&ML\)|CSC \(AI&ML\)|AIML/i.test(b)) return 'CSE(AI&ML)';
                            if (/ECE|E\.C\.E|ELECTRONICS/i.test(b)) return 'ECE';
                            if (/CSE|C\.S\.E|COMPUTER/i.test(b)) return 'CSE';
                            if (/CIVIL|CE|C\.E/i.test(b)) return 'CE';
                            if (/MECH|M\.E|ME/i.test(b)) return 'ME';
                            if (/MME|METALLURGY/i.test(b)) return 'MME';
                            if (/CHEM|CHE|C\.H\.E/i.test(b)) return 'CHE';
                            if (/EEE|E\.E\.E/i.test(b)) return 'EEE';
                            return branchStr;
                        };

                        const userShortBranch = getShortBranch(user.branch || user.department);

                        const roleMatch = hasRoleFilter ? target.roles.includes(user.role) : true;
                        const deptMatch = hasDeptFilter ? target.departments.includes(userShortBranch) : true;

                        // Check classes using exact match
                        // Treat 'AIML' and 'CSE(AI&ML)' as synonymous for classes
                        const classMatch = hasClassFilter ? target.classes.some(tc => {
                            const c1 = tc.toUpperCase();
                            const c2 = (user.currentClass || '').toUpperCase();
                            if ((c1 === 'AIML' || c1 === 'CSE(AI&ML)') && (c2 === 'AIML' || c2 === 'CSE(AI&ML)')) return true;
                            return c1 === c2;
                        }) : true;

                        isEligible = roleMatch && deptMatch && classMatch;
                    }
                }

                if (isEligible) {
                    eligibleNotices.push(notice);
                }
            });

            return eligibleNotices;
        } catch (error) {
            console.error("Error fetching eligible notices:", error);
            return [];
        }
    },

    /**
     * Gets a single notice by ID.
     */
    async getNoticeById(noticeId) {
        try {
            const docRef = doc(db, NOTICES_COLLECTION, noticeId);
            const docSnap = await getDoc(docRef);
            if (docSnap.exists()) {
                return { id: docSnap.id, ...docSnap.data() };
            }
            return null;
        } catch (error) {
            console.error("Error fetching notice:", error);
            throw error;
        }
    },

    /**
     * Gets the user's interactions (read receipts, bookmarks) for a list of notices.
     */
    async getUserInteractions(userId) {
        try {
            const q = query(collection(db, INTERACTIONS_COLLECTION), where('userId', '==', userId));
            const snapshot = await getDocs(q);
            const interactions = {};
            snapshot.forEach(doc => {
                const data = doc.data();
                interactions[data.noticeId] = data;
            });
            return interactions; // Returns a map: { noticeId: { isRead, bookmarked } }
        } catch (error) {
            console.error("Error fetching interactions:", error);
            return {};
        }
    },

    /**
     * Marks a notice as read by the user.
     */
    async markAsRead(noticeId, userId) {
        try {
            // We use a composite ID for uniqueness: userId_noticeId
            const interactionId = `${userId}_${noticeId}`;
            const interactionRef = doc(db, INTERACTIONS_COLLECTION, interactionId);

            const docSnap = await getDoc(interactionRef);

            if (!docSnap.exists()) {
                // Create interaction
                await addDoc(collection(db, INTERACTIONS_COLLECTION), { // Or use setDoc with fixed ID
                    userId,
                    noticeId,
                    isRead: true,
                    readAt: serverTimestamp(),
                    bookmarked: false
                });

                // Increment readCount in the notice document
                // This is a simple approximation. For strict concurrency, use a transaction.
                const noticeRef = doc(db, NOTICES_COLLECTION, noticeId);
                const noticeSnap = await getDoc(noticeRef);
                if (noticeSnap.exists()) {
                    await updateDoc(noticeRef, {
                        readCount: (noticeSnap.data().readCount || 0) + 1
                    });
                }
            } else if (!docSnap.data().isRead) {
                // Update to read
                await updateDoc(interactionRef, {
                    isRead: true,
                    readAt: serverTimestamp()
                });
            }
        } catch (error) {
            console.error("Error marking as read:", error);
        }
    },

    /**
     * Toggles bookmark status.
     */
    async toggleBookmark(noticeId, userId, currentStatus) {
        try {
            const interactionId = `${userId}_${noticeId}`;
            const interactionRef = doc(db, INTERACTIONS_COLLECTION, interactionId);

            const docSnap = await getDoc(interactionRef);
            if (!docSnap.exists()) {
                await addDoc(collection(db, INTERACTIONS_COLLECTION), {
                    userId,
                    noticeId,
                    isRead: false,
                    bookmarked: !currentStatus
                });
            } else {
                await updateDoc(interactionRef, {
                    bookmarked: !currentStatus
                });
            }
            return !currentStatus;
        } catch (error) {
            console.error("Error toggling bookmark:", error);
            throw error;
        }
    },

    /**
     * Increments the total view count for a notice.
     */
    async incrementViewCount(noticeId) {
        try {
            const noticeRef = doc(db, NOTICES_COLLECTION, noticeId);
            const noticeSnap = await getDoc(noticeRef);
            if (noticeSnap.exists()) {
                await updateDoc(noticeRef, {
                    viewCount: (noticeSnap.data().viewCount || 0) + 1
                });
            }
        } catch (error) {
            console.error("Error incrementing view count:", error);
        }
    },

    // ---------------------------------------------------------
    // Helper Methods
    // ---------------------------------------------------------

    async _uploadAttachments(files) {
        const uploadedFiles = [];
        for (const fileObj of files) {
            if (fileObj.file) { // It's a new file to upload
                const file = fileObj.file;
                const timestamp = new Date().getTime();
                const storagePath = `notices/${timestamp}_${file.name}`;
                const fileRef = ref(storage, storagePath);

                const snapshot = await uploadBytes(fileRef, file);
                const downloadURL = await getDownloadURL(snapshot.ref);

                uploadedFiles.push({
                    name: file.name,
                    size: file.size,
                    type: file.type,
                    url: downloadURL,
                    storagePath: storagePath
                });
            } else {
                // It's an existing file, just keep it
                uploadedFiles.push(fileObj);
            }
        }
        return uploadedFiles;
    }
};

import { Filesystem, Directory } from '@capacitor/filesystem';
import { Preferences } from '@capacitor/preferences';
import { Capacitor } from '@capacitor/core';
import { FileOpener } from '@capacitor-community/file-opener';

const PDF_CACHE_KEY = 'rgukt_cached_pdfs';

/**
 * Normalizes a string for use as a folder/file name
 */
const sanitizeName = (name) => {
    if (!name) return 'Unknown';
    return name.replace(/[^a-zA-Z0-9.\-_\s]/g, '_').trim();
};

/**
 * Converts standard GitHub URLs to raw URLs for direct download
 */
export const getDownloadableUrl = (url) => {
    if (!url) return url;
    try {
        const urlObj = new URL(url);
        if (urlObj.hostname === 'github.com' && urlObj.pathname.includes('/blob/')) {
            urlObj.hostname = 'raw.githubusercontent.com';
            urlObj.pathname = urlObj.pathname.replace('/blob/', '/');
            return urlObj.toString();
        }

        if (urlObj.hostname.includes('drive.google.com')) {
            let fileId = null;
            if (urlObj.searchParams.has('id')) {
                fileId = urlObj.searchParams.get('id');
            } else if (urlObj.pathname.includes('/file/d/')) {
                const match = urlObj.pathname.match(/\/d\/([a-zA-Z0-9_-]+)/);
                if (match) fileId = match[1];
            }
            if (fileId) {
                return `https://drive.google.com/uc?export=download&id=${fileId}`;
            }
        }
    } catch (e) {
        // Invalid URL, ignore
    }
    return url;
};

/**
 * Get all cached PDFs metadata
 */
export const getAllCachedPdfs = async () => {
    try {
        const { value } = await Preferences.get({ key: PDF_CACHE_KEY });
        return value ? JSON.parse(value) : {};
    } catch (e) {
        console.error('Error reading PDF cache metadata:', e);
        return {};
    }
};

/**
 * Check the status of a specific PDF
 * Returns: { status: 'NOT_DOWNLOADED' | 'DOWNLOADED' | 'UPDATE_AVAILABLE', localUri?: string, metadata?: object }
 */
export const checkPdfStatus = async (pdfId, currentUrl) => {
    const cache = await getAllCachedPdfs();
    const cachedData = cache[pdfId];

    if (!cachedData) {
        return { status: 'NOT_DOWNLOADED' };
    }

    try {
        // Verify file actually exists
        await Filesystem.stat({
            path: cachedData.localPath,
            directory: Directory.Data
        });

        // Check if the URL has changed (rudimentary version check)
        if (cachedData.originalUrl !== currentUrl) {
            return { status: 'UPDATE_AVAILABLE', localUri: cachedData.localUri, metadata: cachedData };
        }

        return { status: 'DOWNLOADED', localUri: cachedData.localUri, metadata: cachedData };
    } catch (e) {
        // File doesn't exist on disk, remove from preferences
        await deletePdf(pdfId);
        return { status: 'NOT_DOWNLOADED' };
    }
};

/**
 * Downloads a PDF and saves it to the custom folder structure
 * hierarchy: [department, semester, subject, unit]
 */
export const downloadPdf = async (pdfId, url, fileName, hierarchy, onProgress, backendUrl) => {
    try {
        if (Capacitor.isNativePlatform()) {
            const status = await Filesystem.checkPermissions();
            if (status.publicStorage !== 'granted') {
                const request = await Filesystem.requestPermissions();
                if (request.publicStorage !== 'granted') {
                    // It may fail on Android 13+ depending on what Capacitor asks for.
                    // But we use Directory.Data now, which doesn't strictly need publicStorage permission.
                    console.warn('publicStorage permission not granted, but proceeding since we use Directory.Data');
                }
            }
        }

        // 1. Build the path: RGUKT CONNECT/AI&ML/Sem1/Python/Unit1/file.pdf
        const safeHierarchy = hierarchy.map(sanitizeName);
        const folderPath = ['RGUKT CONNECT', ...safeHierarchy].join('/');
        const safeFileName = sanitizeName(fileName);
        let ext = '.pdf';
        if (safeFileName.toLowerCase().endsWith('.pdf')) {
            ext = '';
        }
        const fullPath = `${folderPath}/${safeFileName}${ext}`;

        const downloadUrl = getDownloadableUrl(url);

        let actualFullPath = fullPath;
        let writeResult;

        // Create directories explicitly
        try {
            await Filesystem.mkdir({
                path: folderPath,
                directory: Directory.Data,
                recursive: true
            });
        } catch (mkdirError) {
            console.warn("mkdir warning (might already exist):", mkdirError);
        }

        if (Capacitor.isNativePlatform()) {
            let progressListener;
            if (onProgress) {
                await Filesystem.removeAllListeners();
                progressListener = await Filesystem.addListener('progress', (progress) => {
                    if (progress.url === downloadUrl) {
                        const percentComplete = Math.round((progress.bytes / progress.contentLength) * 100);
                        onProgress(percentComplete);
                    }
                });
            }

            writeResult = await Filesystem.downloadFile({
                url: downloadUrl,
                path: actualFullPath,
                directory: Directory.Data,
                recursive: true,
                progress: true
            });

            if (progressListener) {
                await progressListener.remove();
            }
        } else {
            // Web fallback (usually blocked by CORS for Drive, but included for completeness)
            const blob = await new Promise((resolve, reject) => {
                const xhr = new XMLHttpRequest();
                xhr.open('GET', downloadUrl, true);
                xhr.responseType = 'blob';

                if (onProgress) {
                    xhr.onprogress = (event) => {
                        if (event.lengthComputable) {
                            const percentComplete = Math.round((event.loaded / event.total) * 100);
                            onProgress(percentComplete);
                        }
                    };
                }

                xhr.onload = () => {
                    if (xhr.status >= 200 && xhr.status < 300) {
                        resolve(xhr.response);
                    } else {
                        reject(new Error(`Network request failed with status ${xhr.status}`));
                    }
                };

                xhr.onerror = () => reject(new Error('Network request failed'));
                xhr.send();
            });

            const reader = new FileReader();
            const base64Promise = new Promise((resolve, reject) => {
                reader.onloadend = () => {
                    const b64 = reader.result.split(',')[1];
                    resolve(b64);
                };
                reader.onerror = reject;
            });
            reader.readAsDataURL(blob);
            const base64Data = await base64Promise;

            writeResult = await Filesystem.writeFile({
                path: actualFullPath,
                data: base64Data,
                directory: Directory.Data,
                recursive: true
            });
        }

        // Check if writeResult was successful
        if (!writeResult || (!writeResult.path && !writeResult.uri)) {
            throw new Error("Failed to write file to storage");
        }

        let fileUri = writeResult.uri;
        if (!fileUri) {
            // downloadFile returns 'path' but not 'uri', so we need to get it
            const stat = await Filesystem.getUri({
                path: actualFullPath,
                directory: Directory.Data
            });
            fileUri = stat.uri;
        }

        // 5. Save metadata
        const cache = await getAllCachedPdfs();
        cache[pdfId] = {
            id: pdfId,
            name: `${safeFileName}${ext}`,
            originalUrl: url,
            localPath: actualFullPath,
            localUri: fileUri, 
            hierarchy: safeHierarchy,
            downloadedAt: new Date().toISOString()
        };

        await Preferences.set({
            key: PDF_CACHE_KEY,
            value: JSON.stringify(cache)
        });

        // Notify UI that a PDF was downloaded
        window.dispatchEvent(new CustomEvent('pdf-cache-updated', { detail: { pdfId } }));

        return { success: true, localUri: fileUri, path: fullPath };
    } catch (error) {
        console.error('Error downloading PDF:', error);
        throw error;
    }
};

/**
 * Delete a downloaded PDF
 */
export const deletePdf = async (pdfId) => {
    const cache = await getAllCachedPdfs();
    const cachedData = cache[pdfId];

    if (cachedData) {
        try {
            await Filesystem.deleteFile({
                path: cachedData.localPath,
                directory: Directory.Data
            });
        } catch (e) {
            console.error('Error deleting file from filesystem:', e);
        }

        delete cache[pdfId];
        await Preferences.set({
            key: PDF_CACHE_KEY,
            value: JSON.stringify(cache)
        });

        // Notify UI that a PDF was deleted
        window.dispatchEvent(new CustomEvent('pdf-cache-updated', { detail: { pdfId } }));
    }
};

/**
 * Open the PDF
 */
export const openPdf = async (uri) => {
    try {
        if (!uri) throw new Error("No file path provided to open.");

        if (Capacitor.isNativePlatform()) {
            // Using FileOpener with openWithDefault: false uses Android's Intent.createChooser()
            // This filters for PDF viewers and hides the 'Always/Just once' prompt!
            await FileOpener.open({
                filePath: uri,
                contentType: 'application/pdf',
                openWithDefault: false
            });
        } else {
            // Fallback for web
            window.open(uri, '_blank');
        }
    } catch (e) {
        console.error('Error opening PDF:', e);
        alert('Error: ' + (e.message || JSON.stringify(e)));
    }
};

import { 
    collection, 
    addDoc, 
    updateDoc, 
    deleteDoc, 
    doc, 
    getDocs, 
    getDoc, 
    query, 
    where, 
    orderBy,
    serverTimestamp,
    increment
} from 'firebase/firestore';
import { db } from '../config/firebase';

const COLLECTION_NAME = 'pdfs';

export const pdfService = {
    /**
     * Save PDF metadata to Firestore after a successful Google Drive upload
     */
    async uploadPdfMetadata(pdfData) {
        try {
            const docRef = await addDoc(collection(db, COLLECTION_NAME), {
                ...pdfData,
                uploadedDate: serverTimestamp(),
                downloads: 0,
                views: 0,
                status: 'active'
            });
            return { success: true, id: docRef.id };
        } catch (error) {
            console.error('Error adding document: ', error);
            throw new Error('Failed to save PDF metadata: ' + error.message);
        }
    },

    /**
     * Fetch PDFs with optional filters
     */
    async fetchPdfs(filters = {}) {
        try {
            let q = collection(db, COLLECTION_NAME);
            const queryConstraints = [];

            if (filters.branch) queryConstraints.push(where('branch', '==', filters.branch));
            if (filters.semester) queryConstraints.push(where('semester', '==', filters.semester));
            if (filters.subject) queryConstraints.push(where('subject', '==', filters.subject));

            // Note: If combining 'where' and 'orderBy' on different fields, Firestore requires a composite index.
            queryConstraints.push(orderBy('uploadedDate', 'desc'));

            if (queryConstraints.length > 0) {
                q = query(q, ...queryConstraints);
            }

            const querySnapshot = await getDocs(q);
            return querySnapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));
        } catch (error) {
            console.error('Error fetching PDFs: ', error);
            throw new Error('Failed to fetch PDFs: ' + error.message);
        }
    },

    /**
     * Get a single PDF by ID
     */
    async getPdfById(id) {
        try {
            const docRef = doc(db, COLLECTION_NAME, id);
            const docSnap = await getDoc(docRef);
            if (docSnap.exists()) {
                return { id: docSnap.id, ...docSnap.data() };
            }
            return null;
        } catch (error) {
            console.error('Error fetching PDF: ', error);
            throw new Error('Failed to fetch PDF details: ' + error.message);
        }
    },

    /**
     * Increment download count
     */
    async incrementDownloadCount(id) {
        try {
            const docRef = doc(db, COLLECTION_NAME, id);
            await updateDoc(docRef, {
                downloads: increment(1)
            });
            return true;
        } catch (error) {
            console.error('Error updating download count: ', error);
            return false;
        }
    },

    /**
     * Increment view count
     */
    async incrementViewCount(id) {
        try {
            const docRef = doc(db, COLLECTION_NAME, id);
            await updateDoc(docRef, {
                views: increment(1)
            });
            return true;
        } catch (error) {
            console.error('Error updating view count: ', error);
            return false;
        }
    },

    /**
     * Update PDF metadata
     */
    async updatePdfMetadata(id, updateData) {
        try {
            const docRef = doc(db, COLLECTION_NAME, id);
            await updateDoc(docRef, updateData);
            return true;
        } catch (error) {
            console.error('Error updating document: ', error);
            throw new Error('Failed to update PDF metadata: ' + error.message);
        }
    },

    /**
     * Delete PDF metadata
     */
    async deletePdfMetadata(id) {
        try {
            const docRef = doc(db, COLLECTION_NAME, id);
            await deleteDoc(docRef);
            return true;
        } catch (error) {
            console.error('Error deleting document: ', error);
            throw new Error('Failed to delete PDF metadata: ' + error.message);
        }
    },

    /**
     * Generates a native vector PDF for the student profile report.
     * This provides selectable text and perfect quality.
     */
    async generateStudentProfilePdf(formData, user, logoUri, avatarUri) {
        const { jsPDF } = await import('jspdf');

        // Create PDF in A4 format
        const doc = new jsPDF({
            orientation: 'portrait',
            unit: 'mm',
            format: 'a4',
            compress: true
        });

        const pageWidth = doc.internal.pageSize.width || doc.internal.pageSize.getWidth();
        const pageHeight = doc.internal.pageSize.height || doc.internal.pageSize.getHeight();
        const margin = 15;
        const contentWidth = pageWidth - (margin * 2);

        // --- BACKGROUND / ACCENTS ---
        doc.setFillColor(255, 255, 255);
        doc.rect(0, 0, pageWidth, pageHeight, 'F');

        // Header Primary Bar
        doc.setFillColor(30, 58, 138); 
        doc.rect(0, 0, pageWidth, 4, 'F');

        // --- SUBTLE WATERMARK (SAFE) ---
        try {
            doc.setTextColor(245, 247, 250);
            doc.setFontSize(40);
            doc.setFont('helvetica', 'bold');
            if (typeof doc.saveGraphicsState === 'function') {
                doc.saveGraphicsState();
                doc.text('OFFICIAL RECORD', pageWidth / 2, pageHeight / 2, { align: 'center', angle: 45 });
                doc.restoreGraphicsState();
            } else {
                // Fallback for older jsPDF versions
                doc.text('OFFICIAL RECORD', pageWidth / 2, pageHeight / 2, null, 45);
            }
        } catch (e) {}

        // --- HEADER ---
        let currentY = 15;

        // Logo
        if (logoUri) {
            try {
                doc.addImage(logoUri, 'PNG', margin, currentY, 18, 18);
            } catch (e) {}
        }

        // Brand Name & System Info
        doc.setTextColor(30, 41, 59);
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(18);
        doc.text('RGUKT CONNECT', margin + 22, currentY + 7);

        doc.setFontSize(8);
        doc.setFont('helvetica', 'bold');
        doc.setTextColor(100, 116, 139);
