import { db } from '../config/firebase';
import { doc, setDoc, getDoc, onSnapshot, deleteDoc, updateDoc } from 'firebase/firestore';
import CryptoJS from 'crypto-js';

const COLLECTION_NAME = 'qr_sessions';

/**
 * Generate a random string of given length
 */
const generateRandomString = (length = 32) => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    let result = '';
    for (let i = 0; i < length; i++) {
        result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return result;
};

/**
 * Initiates a new QR Login Session from the Desktop/Laptop.
 * @param {string} userId - The UID of the currently logged-in user.
 * @returns {object} { sessionId, encryptionKey, qrString }
 */
export const initiateQRSession = async (userId) => {
    const sessionId = generateRandomString(24);
    const encryptionKey = generateRandomString(32); // Key stays strictly on device and in QR
    const qrString = `rgukt-qr-login|${sessionId}|${encryptionKey}`;

    // Expires in 2 minutes
    const expiresAt = new Date(Date.now() + 2 * 60 * 1000).toISOString();

    await setDoc(doc(db, COLLECTION_NAME, sessionId), {
        status: 'pending', // pending -> scanned -> authenticated
        expiresAt,
        userId,
        createdAt: new Date().toISOString()
    });

    return { sessionId, encryptionKey, qrString };
};

/**
 * Subscribe to the QR Session to wait for mobile scan.
 * @param {string} sessionId
 * @param {function} onScanned - Callback when mobile scans the QR
 * @param {function} onExpired - Callback when session expires
 */
export const listenToQRSession = (sessionId, onScanned, onExpired) => {
    const unsubscribe = onSnapshot(doc(db, COLLECTION_NAME, sessionId), (docSnap) => {
        if (!docSnap.exists()) {
            // Document was deleted (either consumed or manually removed)
            return;
        }

        const data = docSnap.data();
        const now = new Date();
        const expiry = new Date(data.expiresAt);

        if (now > expiry) {
            onExpired();
            unsubscribe();
            // Clean up
            deleteDoc(doc(db, COLLECTION_NAME, sessionId)).catch(console.error);
            return;
        }

        if (data.status === 'scanned') {
            onScanned();
        }
    });

    return unsubscribe;
};

/**
 * Confirm the scan from Desktop and provide the encrypted credentials.
 * @param {string} sessionId
 * @param {string} encryptionKey
 * @param {object} credentials - { email, password }
 */
export const provideEncryptedCredentials = async (sessionId, encryptionKey, credentials) => {
    const stringifiedCreds = JSON.stringify(credentials);
    const encryptedPayload = CryptoJS.AES.encrypt(stringifiedCreds, encryptionKey).toString();

    await updateDoc(doc(db, COLLECTION_NAME, sessionId), {
        status: 'authenticated',
        encryptedPayload
    });
};

/**
 * Called by Mobile Device after scanning the QR code to signal readiness.
 * @param {string} sessionId
 */
export const markSessionAsScanned = async (sessionId) => {
    const docRef = doc(db, COLLECTION_NAME, sessionId);
    const docSnap = await getDoc(docRef);

    if (!docSnap.exists()) {
        throw new Error("Invalid or expired QR code.");
    }

    const data = docSnap.data();
    if (new Date() > new Date(data.expiresAt)) {
        throw new Error("QR code has expired.");
    }

    if (data.status !== 'pending') {
        throw new Error("QR code has already been used.");
    }

    // Set user agent or basic device info (optional)
    const deviceInfo = navigator.userAgent;

    await updateDoc(docRef, {
        status: 'scanned',
        deviceInfo
    });
};

/**
 * Mobile Device awaits the payload after marking as scanned.
 * @param {string} sessionId
 * @param {string} encryptionKey
 * @param {function} onSuccess - Callback with decrypted credentials { email, password }
 * @param {function} onError
 */
export const awaitAuthenticationPayload = (sessionId, encryptionKey, onSuccess, onError) => {
    const unsubscribe = onSnapshot(doc(db, COLLECTION_NAME, sessionId), (docSnap) => {
        if (!docSnap.exists()) return;

        const data = docSnap.data();
        if (data.status === 'authenticated' && data.encryptedPayload) {
            try {
                // Decrypt
                const bytes = CryptoJS.AES.decrypt(data.encryptedPayload, encryptionKey);
                const decryptedStr = bytes.toString(CryptoJS.enc.Utf8);
                const credentials = JSON.parse(decryptedStr);

                // Immediately delete the session to prevent replay
                deleteDoc(doc(db, COLLECTION_NAME, sessionId)).catch(console.error);

                unsubscribe();
                onSuccess(credentials);
            } catch (err) {
                unsubscribe();
                onError(new Error("Failed to decrypt credentials. Invalid QR code."));
            }
        }
    });

    return unsubscribe;
};

import { db } from '../config/firebase';
import { collection, doc, setDoc, updateDoc, getDocs, query, orderBy, deleteDoc, onSnapshot, getDoc } from 'firebase/firestore';
import { UAParser } from 'ua-parser-js';

// Helper to generate a unique local session ID
const generateSessionId = () => {
    return 'sess_' + Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
};

// Fetch IP Address
const fetchIpAddress = async () => {
    try {
        const response = await fetch('https://api.ipify.org?format=json');
        const data = await response.json();
        return data.ip;
    } catch (err) {
        console.warn("Failed to fetch IP address:", err);
        return 'Unknown IP';
    }
};

/**
 * Creates a new session document in Firestore and returns the sessionId.
 * @param {string} userId
 */
export const createSession = async (userId) => {
    try {
        const parser = new UAParser();
        const result = parser.getResult();
        const sessionId = generateSessionId();

        const browser = `${result.browser.name || 'Unknown Browser'} ${result.browser.version ? result.browser.version.split('.')[0] : ''}`;
        const os = `${result.os.name || 'Unknown OS'} ${result.os.version || ''}`.trim();

        let deviceType = result.device.type || 'desktop';
        let deviceName = `${os} ${deviceType === 'desktop' ? 'PC/Laptop' : deviceType.charAt(0).toUpperCase() + deviceType.slice(1)}`;

        if (result.device.vendor && result.device.model) {
            deviceName = `${result.device.vendor} ${result.device.model}`;
        }

        const sessionData = {
            id: sessionId,
            userId,
            deviceName,
            deviceType,
            browser,
            os,
            ipAddress: 'Detecting...',
            loginTime: new Date().toISOString(),
            lastActive: new Date().toISOString(),
            status: 'active',
            trusted: false,
        };

        const sessionRef = doc(db, 'users', userId, 'sessions', sessionId);

        // Create the session document in the background for absolute speed
        // Firestore's offline persistence handles this gracefully
        setDoc(sessionRef, sessionData).catch(err => console.warn("Initial session write failed:", err));

        // Run IP fetch and security checks in the background
        (async () => {
            try {
                const ipAddress = await fetchIpAddress();
                const existingSessions = await getUserSessions(userId);
                let isNewDevice = false;

                if (existingSessions.length > 0) {
                    const hasSeenThisDevice = existingSessions.some(
                        s => s.os === os && s.browser === browser
                    );
                    if (!hasSeenThisDevice) {
                        isNewDevice = true;
                        const notifRef = doc(collection(db, 'users', userId, 'notifications'));
                        setDoc(notifRef, {
                            type: 'security_alert',
                            title: 'New Login Detected',
                            message: `New login from ${deviceName} (${browser}) at ${ipAddress}.`,
                            timestamp: new Date().toISOString(),
                            read: false,
                            icon: 'ShieldAlert'
                        }).catch(() => {});
                    }
                }

                // Update session with correct IP
                updateDoc(sessionRef, { ipAddress }).catch(() => {});
            } catch (bgError) {
                console.warn("Background session tasks failed:", bgError);
            }
        })();

        // Store sessionId locally
        localStorage.setItem('rgukt_connect_session_id', sessionId);
        
        return { sessionData, isNewDevice: false }; 
    } catch (err) {
        console.error("Failed to create session:", err);
        return { sessionData: null, isNewDevice: false };
    }
};

/**
 * Ping the current session to update lastActive time
 * @param {string} userId
 * @param {string} sessionId
 */
export const pingSessionActivity = async (userId, sessionId) => {
    if (!userId || !sessionId) return;
    try {
        const sessionRef = doc(db, 'users', userId, 'sessions', sessionId);
        await updateDoc(sessionRef, {
            lastActive: new Date().toISOString()
        });
    } catch (err) {
        console.error("Failed to ping session:", err);
    }
};

/**
 * Fetch all sessions for a user
 */
export const getUserSessions = async (userId) => {
    if (!userId) return [];
    try {
        const sessionsRef = collection(db, 'users', userId, 'sessions');
        const q = query(sessionsRef, orderBy('lastActive', 'desc'));
        const snapshot = await getDocs(q);

        return snapshot.docs.map(doc => ({
            ...doc.data(),
            id: doc.id
        }));
    } catch (err) {
        console.error("Failed to fetch sessions:", err);
        return [];
    }
};

/**
 * Revokes a specific session (kicks the device out)
 */
export const revokeSession = async (userId, sessionId) => {
    try {
        const sessionRef = doc(db, 'users', userId, 'sessions', sessionId);
        await deleteDoc(sessionRef);
        return true;
    } catch (err) {
        console.error("Failed to revoke session:", err);
        return false;
    }
};

/**
 * Completely deletes a session document (used for manual signouts to clean up the DB)
 */
export const deleteSession = async (userId, sessionId) => {
    try {
        const sessionRef = doc(db, 'users', userId, 'sessions', sessionId);
        await deleteDoc(sessionRef);
        return true;
    } catch (err) {
        console.error("Failed to delete session:", err);
        return false;
    }
};

/**
 * Revokes all sessions EXCEPT the current one
 */
export const revokeAllOtherSessions = async (userId, currentSessionId) => {
    try {
        const sessions = await getUserSessions(userId);
        const promises = sessions
            .filter(s => s.id !== currentSessionId)
            .map(s => deleteSession(userId, s.id));

        await Promise.all(promises);
        return true;
    } catch (err) {
        console.error("Failed to revoke other sessions:", err);
        return false;
    }
};

/**
 * Update session details (e.g., Name, Trusted status)
 */
export const updateSessionDetails = async (userId, sessionId, updates) => {
    try {
        const sessionRef = doc(db, 'users', userId, 'sessions', sessionId);
        await updateDoc(sessionRef, updates);
        return true;
    } catch (err) {
        console.error("Failed to update session details:", err);
        return false;
    }
};

/**
 * Real-time listener for current session status.
 * If status changes to 'revoked', triggering callback (e.g., force logout)
 */
export const listenToMySessionStatus = (userId, sessionId, onRevoked) => {
    if (!userId || !sessionId) return () => { };

    let isFirstSnapshot = true;

    const sessionRef = doc(db, 'users', userId, 'sessions', sessionId);
    const unsubscribe = onSnapshot(sessionRef, (docSnap) => {
        if (!docSnap.exists()) {
            if (isFirstSnapshot) {
                // Race condition: sometimes Firebase snapshot returns !exists() immediately 
                // before the local setDoc cache is fully registered for the listener.
                isFirstSnapshot = false;

                // Double check if it REALLY doesn't exist after a larger delay to allow for slow sync
                setTimeout(async () => {
                    const checkRef = doc(db, 'users', userId, 'sessions', sessionId);
                    const checkSnap = await getDoc(checkRef).catch(() => null);
                    if (!checkSnap?.exists()) {
                        console.warn("Session watchdog: Session definitely missing after 5s check. Logging out.");
                        onRevoked();
                    }
                }, 5000);
                return;
            }
            // Document was actively deleted by a remote logout action
            onRevoked();
        } else {
            isFirstSnapshot = false;
            const data = docSnap.data();
            if (data.status === 'revoked') {
                onRevoked();
            }
        }
    });

    return unsubscribe;
};

export const createImage = (url) =>
  new Promise((resolve, reject) => {
    const image = new Image();
    image.addEventListener('load', () => resolve(image));
    image.addEventListener('error', (error) => reject(error));
    image.setAttribute('crossOrigin', 'anonymous'); // needed to avoid cross-origin issues on CodeSandbox
    image.src = url;
  });

export function getRadianAngle(degreeValue) {
  return (degreeValue * Math.PI) / 180;
}

/**
 * Returns the new bounding area of a rotated rectangle.
 */
export function rotateSize(width, height, rotation) {
  const rotRad = getRadianAngle(rotation);

  return {
    width:
      Math.abs(Math.cos(rotRad) * width) + Math.abs(Math.sin(rotRad) * height),
    height:
      Math.abs(Math.sin(rotRad) * width) + Math.abs(Math.cos(rotRad) * height),
  };
}

/**
 * This function was adapted from the one in the ReadMe of https://github.com/DominicTobias/react-image-crop
 */
export default async function getCroppedImg(
  imageSrc,
  pixelCrop,
  rotation = 0,
  flip = { horizontal: false, vertical: false }
) {
  const image = await createImage(imageSrc);
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  if (!ctx) {
    return null;
  }

  const rotRad = getRadianAngle(rotation);

  // calculate bounding box of the rotated image
  const { width: bBoxWidth, height: bBoxHeight } = rotateSize(
    image.width,
    image.height,
    rotation
  );

  // set canvas size to match the bounding box
  canvas.width = bBoxWidth;
  canvas.height = bBoxHeight;

  // translate canvas context to a central location to allow rotating and flipping around the center
  ctx.translate(bBoxWidth / 2, bBoxHeight / 2);
  ctx.rotate(rotRad);
  ctx.scale(flip.horizontal ? -1 : 1, flip.vertical ? -1 : 1);
  ctx.translate(-image.width / 2, -image.height / 2);

  // draw rotated image
  ctx.drawImage(image, 0, 0);

  const croppedCanvas = document.createElement('canvas');

  const croppedCtx = croppedCanvas.getContext('2d');

  if (!croppedCtx) {
    return null;
  }

  // Set the size of the cropped canvas
  croppedCanvas.width = pixelCrop.width;
  croppedCanvas.height = pixelCrop.height;

  // Draw the cropped image onto the new canvas
  croppedCtx.drawImage(
    canvas,
    pixelCrop.x,
    pixelCrop.y,
    pixelCrop.width,
    pixelCrop.height,
    0,
    0,
    pixelCrop.width,
    pixelCrop.height
  );

  // As a blob
  return new Promise((resolve, reject) => {
    croppedCanvas.toBlob((file) => {
      resolve(file);
    }, 'image/jpeg');
  });
}

